window.__D("text/sefer-hasichot-rayatz/c004",{"p":[[4301600203,"שמדברים אודות חסידות<sup data-n=\"322\">3</sup>, אבל זקני אדמו\"ר מהר\"ש זצוקללה\"ה זי\"ע אמר זמירות שתי פעמים ובאחד מהפעמים הי' כ\"ק אאמו\"ר זצוקללה\"ה זי\"ע אצל השלחן — כי לא היו יושבים כל בניו תמיד אצל השלחן בש\"ק, רק שהיו מתחלפים שבוע זו א' ושנית ב' — ואמר אאמו\"ר שבפעם הא' הי' גם הוא<sup data-n=\"323\">4</sup>.\nושאל אחד: הלא בבית אדמו\"ר הצ\"צ זי\"ע היו מנגנים בני היכלא? ושאל עוד אחד: האם אכלו בבית הצ\"צ שלש סעודות? ואמר השואל הא': כן. והשיב ע\"ז כ\"ק אדמו\"ר<sup data-n=\"324\">5</sup>, שלא אכלו<sup data-n=\"325\">6</sup>, וכן גם בבית אדמו\"ר האמצעי וגם בבית אדמו\"ר הזקן לאחר שנת תקס\"ב לאחר ביאתו מפ\"ב בפעם הב' שנאמר הדרוש<sup data-n=\"326\">7</sup> אשר נזכר בו \"היום לא\"<sup data-n=\"327\">8</sup>, מאז הפסיקו ענין השלש סעודות, וקודם לזה אכלו ולאחר דרוש זה הפסיקו ובמקום זה נא' הדרו' דביאורי הזהר<sup data-n=\"328\">9</sup>.\nושאל אחד: הרי ר' הלל<sup data-n=\"329\">10</sup> אכל שלש סעודות?\nואמר כ\"ק אדמו\"ר: אַ רבי און",[["322","3","בהגהת כ\"ק אדמו\"ר מהורש\"ב נ\"ע לסידור [נדפס בסידור הנ\"ל רמה, א]: ומכ\"ק אאמו\"ר [מהר\"ש] זצוקללה\"ה (בשם כ\"ק אאזמו\"ר [הצ\"צ] זצוקללה\"ה) שמעתי שאמר [בשם] רבינו הגדול זצוקללה\"ה שמה שלא העמיד בהסדור זמירות הוא שחשב שישירו בתוך הסעודה ושיר למעלה מזמרה. ופעם אמר שמה שלא כו' הוא שחשב שידברו חסידות בתוך הסעודה. וראה עד\"ז בספר השיחות תש\"ד ע' 94: דער טעם פארוואס הוד כ\"ק רבינו הזקן האט ניט אריינגעשטעלט זמירות אין סידור, האט הוד כ\"ק אאזמו\"ר הרה\"ק צ\"צ געזאגט, ווייל ער האט גערעכענט מען וועט ריידען אין חסידות ביים טיש. הוד כ\"ק אאזמו\"ר מוהר\"ש האט געזאגט, ווייל מ'וועט זאגען א ניגון. הוד כ\"ק אאמו\"ר הרה\"ק האט מתווך געווען די ביידע ענינים. עיי\"ש ההמשך.\nובאגרות­קודש ח\"ג ע' תפב: דער עלטער זיידע [אדמו\"ר הזקן] האט געהאלטן אז זמירות שבת דארפן זיך זאגן, און דאס וואס דארף זיך זאגן איז אז עס זאגט זיך איז דאס געזאגט, אבער אז דאס איז מערניט ווי געזאגט איז דאס ניט געזאגט<sup data-n=\"e12\">*</sup>.\nוכשסיים את דבריו אלה התחיל לנגן את הזמירות והמסובים ענו אחריו."],["323","4","בהגהת כ\"ק אדמו\"ר מהורש\"ב נ\"ע לסידור שם: וכמה פעמים הייתי בעת הסעודה [אצל אדמו\"ר מהר\"ש] ולא ראיתיו שיאמר הפזמונים הנ\"ל [אזמר בשבחין, אסדר, בני היכלא], ופעם אחד (בהזמן שאכלנו אתו על השלחן) צוה לנו שנאמר הפזמונים הנ\"ל אך זה נמשך זמן קצר רק איזה שבתים ולא אמר לנו עוד שנאמר כו'. ובאגרות­קודש שם: בסעודת ליל ש\"ק ההיא [שבת סליחות תרל\"ז] סיפר כ\"ק אאמו\"ר [מהר\"ש] אשר אצל כ\"ק אבותינו רבותינו היו זמנים שהיו אומרים זמירות בסעודות שבת."],["324","5","ראה גם לקמן ע' 220. ע' 245. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 217."],["325","6","ראה בארוכה לקוטי שיחות חכ\"א (ע' 84 ואילך) ע\"ד מנהג רבותינו נשיאינו שברובא דרובא לא אכלו פת בסעודה שלישית."],["326","7","ראה אוה\"ת בשלח ס\"ע תרג ואילך. ס\"ע תרכ ואילך. ע' תרלא (נדפס במאה שערים מד, א). ד\"ה מהרה ישמע תרמ\"ח (הועתק ב\"היום יום\" כב אדר א). המשך תער\"ב ח\"ב ס\"ע א'קכז ואילך."],["327","8","בשלח טז, כה. וראה לבוש או\"ח סרצ\"א ס\"ה. פס\"ד להצ\"צ שנז, סע\"ב."],["328","9","ראה רשימת מאמרי אדמו\"ר הזקן בכרם חב\"ד גליון 4 חלק ב ע' 350­348. ולהעיר מאגרות­קודש ח\"ב ע' שכא. ע' תצד."],["329","10","הרב ר' הלל בר' מאיר הלוי מאליסאוו, הידוע בשם \"ר' הלל פאריטשער\" (תקנ\"ה — יא מנ\"א תרכ\"ד). ראשי פרקים מתולדותיו — ראה פלח הרמון על ספר בראשית ועל ספר שמות — הוצאת קה\"ת בתחילתם. ספר השיחות תורת שלום ע' 13. ע' 109. ספר השיחות תר\"פ­תרפ\"ז ע' 52 הערה 12. וש\"נ. לעיל ע' 10. לקמן ע' 60. ע' 215. ע' 245. ע' 260."],["e12","*","כמובן הנה הדרך הזה הוא רק לצדיקים בעלי מדריגה, אבל אנחנו צריכים לעשות הכל בעתו ובזמנו בדרך קבלת עול. — הערת רבינו באגרות­קודש שם."]]],[4301600204,"חסידים איז צוויי זאַכן. כי הרבי צריך להתנהג כמו שהוא הענין, אַ חסיד איז ווי ער וואַלגערט זיך אויס איז גוט, אַבי עפּעס אָפּרייסן פון זיך, מאַכן אַ רקבון, אַ שבירה, אַ שפלות עצמי איז גוט, און בכלל איז ניט טאָן ניט קיין זאַך, אָבער אַ רבי דאַרף זיין ווי דער ענין איז, כמו ענין ויגבה לבו בדרכי ה'<sup data-n=\"330\">11</sup>, דג\"כ צ\"ל אצלו דזה נוגע לההמשכה דלמעלה, ומוכרח שיהי' כן כפי שצריך להיות, ולעצמו נוגע הענין, די האַרץ קריינקט און די קאָפּ אויף דעם וואָס איז ניט אַזוי, זהו רק בהנוגע לעצמו אבל הוא כמו שצריך להיות.\nג. כ\"ק אאמו\"ר הרה\"ק נ\"ע הי' מעיק לו ענין זה מהעדר אכילת שלש סעודות עד שנת רנ\"ד בערך, ואח\"כ איז עם רעכט געוואָרן.\nר' שילם רייך<sup data-n=\"331\">12</sup> סיפר פעם א' שהוא בעצמו ראה שהכניסו לחדר אדמו\"ר מהר\"ש נ\"ע לעת שלש סעודות \"הייזען בלאזין\" (מין מזונות שגם המהדרים אוכלים אותו בלי נטילת ידים), והשיב כ\"ק אאמו\"ר הרה\"ק נ\"ע בלשון תימה: אתם ראיתם ואני לא ראיתי<sup data-n=\"332\">13</sup>?\nד. אח\"כ דיבר עוד בענין הניגונים, ואמר שצריכים לנגן ניגון א' פעמים רבות, וסיפר: בשנת רס\"ג<sup data-n=\"333\">14</sup> זכינו לזכות גדול, והי' עומד ר' מיכאל הזקן<sup data-n=\"334\">15</sup> — געשטאַנען ווי אַ חסיד, ער איז געשטאַנען, ניט אַוועקגעשטעלט זיך נאָר געשטאַנען — וניגנו ניגון אבל במהירות, והי' ניכר מכ\"ק אאמו\"ר הרה\"ק נ\"ע שאין דעתו נוחה מזה שממהרים, והשיב ר' מיכאל: מען וויל דאָך עפּעס. והשיב כ\"ק אאמו\"ר הרה\"ק נ\"ע אַ פּאָר ווערטער, אַז מען דאַרף מאַכן אַ זאַך וואָס איז אַ כלי צו אַ זאַך ביז מען זאָל זיך פאַרגעסן אינגאַנצן אויף דעם און דער כלי אַליין זאָל גוט זיין. וניגנו ניגונים הרבה שלא במהירות, ואח\"כ זכינו להשיחות קדש דרס\"ג<sup data-n=\"333\">14</sup>, זכות גדול הוא.\nבאמצע איזה ניגון אמר: באמת צריכים להיות בשמחה אמיתית, כי הוא זמן שמחה, רק מפני כי שבורים אנחנו מאד הן ממצב העצמי והן מהכלל, אשר באמת איננו בשום דרגא והיינו שאיננו בציור אדם כלל, אבל עכ\"ז צריכים להיות בשמחה באמת.\nושאל אחד: מהו השמחה?\nוהשיב: בענין שתלוי בענין עצמי אז כמו שהוא המצב כך הוא ההרגש, אבל בדבר שתלוי בזמן, והיינו שהזמן בעצם הוא זמן השמחה, וע\"כ צ\"ל בשמחה באמת.",[["330","11","דברי הימים­ב יז, ו."],["331","12","הרה\"ח ר' משולם רייך מווארשא, חתנו של כ\"ק הרב\"ש<sup data-n=\"e13\">*</sup> בנו של אדמו\"ר הצ\"צ, ודר כמה שנים בליובאוויטש (ראה ספר השיחות תורת שלום ע' 2 ובהערה 4. אגרות­קודש ח\"ו ע' ער. ספר השיחות תש\"ה ע' 46). אשתו: מרת רבקה. בנם: חיים משה דובער (אגרת הרב\"ש — מגדל עז ע' תרד. הערות המו\"ל באגרות­קודש אדמו\"ר הצ\"צ ע' תקיא)."],["332","13","ראה גם ספר השיחות שבהערה 5."],["333","14","אולי צ\"ל: תרס\"ד (ראה ספר השיחות תורת שלום ע' 93 — הנחת רבינו), אבל כ\"ה גם תרס\"ג בשיחת יום שמח\"ת תרצ\"ג סעיף כ. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 143. וראה גם ספר השיחות תנש\"א ח\"ב ע' 700."],["334","15","ר' מיכאל בלינער, נקרא בשם ר' מיכאל נעוולער — ראה הערת כ\"ק אדמו\"ר בספר השיחות תורת שלום שבהערה הקודמת. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 221."],["333","14","אולי צ\"ל: תרס\"ד (ראה ספר השיחות תורת שלום ע' 93 — הנחת רבינו), אבל כ\"ה גם תרס\"ג בשיחת יום שמח\"ת תרצ\"ג סעיף כ. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 143. וראה גם ספר השיחות תנש\"א ח\"ב ע' 700."],["e13","*","ראה אודותו — לקמן ע' 227. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 253."]]],[4301600205,"ובאמת יש מעלה בענין השמחה, כי הזמן דר\"ה ועשי\"ת ויום הכיפורים אין צריכים לחשוב במצב עצמו מפני שאפשר לעורר כו' כפי אופן המצב שלו, כמו כשיחשוב ענין המחדו\"מ שלו באיזה אופן שהוא, אם בגסות או בדקות או בדקות דדקות, בכל אופן שהוא ה\"ז גשם.\nה. התחיל לדבר שגם אלחנן<sup data-n=\"336\">16</sup> בטח יש לו סוכה, ואמר: ער איז אַ אמת'ער פנימי, והוא תולדה פון אַ הערצל (לב), דמה שהוא צריך ליתן (אַרויסגעבן) האָבן מיר ניט דאָס געזען נאָך אין חסידים. דאָס איז אַ רבי שהוא בחי' מוחין וראש. אבל חסידים המה רק תולדות לב. והוא ג\"כ אַ תולדה פון אַ הערצל, שנתחנך אצל החסיד ר' הענדל ע\"ה<sup data-n=\"337\">17</sup>. ר' הענדל הי' משפיע, ומה השפיע? מה הי' לו להשפיע? דלענין השגה לא הי' שייך כלל, רק בעל לב נלהב, הוא הי' כהיש כתיקונו, בלא שום חומריות כלל, כענין הכבוד וכדומה, דלזה לא הי' שייך כלל וכלל, אַרויס פון זיך לגמרי, רק בשביל הזולת בצער של הזולת הי' מגיע לו מאד מאד,\nוהשמחה של הזולת הי' מענג אותו הרבה.\nפעם א' שרש\"פ<sup data-n=\"338\">*17</sup> הי' חולה בטיפוס ר\"ל איז ער געלעגן ביי ר' הענדלען אין חדר, און ער אַליין איז געלאָפן קריגען מילך<sup data-n=\"339\">18</sup>, וואָס עם גיין איז געווען זייער שווער, צייטנווייז איז דאָס געווען פאַר אים אַ סכנה, און וועמען ער וואלט בעטן ברענגען אַ ביסל מילך, אַ איד אפילו להבדיל אַ גוי, וואָלט דאָס געטאָן פאַר אים, וויילע ער איז געווען אַ אהוב לכל בריות, איז ער אַליין געלאָפן צו משה זרחי'ן<sup data-n=\"340\">19</sup>, ווייל אין ליובאוויטש האָט מען ניט געקענט קריגען פריש מילך אַזוי אָן אַ סיבה, נאָר ביי משה זרחי'נען איז געווען אַ קליין קינד, איז ער געלאָפן אַהין קריגן מילך.\nאַז עס איז אָנגעקומען די טעלעגראַם ע\"ד שחרורו<sup data-n=\"341\">20</sup> של חנן<sup data-n=\"336\">16</sup> איז ר' הענדל אַריינגעלאפן צום טאַטן — ער פלעגט אַריין ווען ער האָט געוואָלט, ער האָט ניט געדאַרפט קיין דאקלאד<sup data-n=\"343\">21</sup>, — און האָט זיך ממש געהייבן אויף אַ האַלב אַרשין<sup data-n=\"344\">*21</sup> פון בריק.\nפאַרברענגען האָט ער געקענט שטענדיק, ער איז געווען אַלעמאָל ביי דעם, און האָט ניט געדאַרפט קיין משקה<sup data-n=\"345\">22</sup>, ווי דער רשב\"ץ<sup data-n=\"346\">*22</sup> פלעגט זאָגן: די עצם זאַך, אָן מעקלערס. עס איז געשטאַנען אויפן טיש אַ קליין קוואַטירל<sup data-n=\"347\">23</sup>, אָבער די קוואַטירל האָט געקענט זיין אויף עטלעכע מאָל,",[["336","16","הרה\"ח ר' אלחנן דובער מאראזאוו, ממזכירי רבינו. באד\"ר תרפ\"ז נאסר ושלחוהו לסיביר לשלש שנים. — ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 28 הערה 1. וש\"נ. לקמן ע' 169."],["337","17","המשפיע החסיד והעובד ר' חנוך הענדל קוגל מפלעשעניץ. ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 29 הערה 10. וש\"נ. תרצ\"ו — חורף ה'ש\"ת ע' 16. ס\"ע 180 ואילך. ע' 184 ואילך. ע' 196. נזכר לקמן ע' 97. וראה הקדמת רבינו לקונטרס התפלה."],["338","*17","אולי ר' שרגא פייוויש שבהערה 28."],["339","18","ראה גם ספר השיחות תש\"א ע' 49."],["340","19","נזכר ברשימת היומן של רבינו מיום כ' אייר תרנ\"ו (לקו\"ד ח\"ג תקכט, ב). ספר השיחות תש\"ג ע' 141. תש\"ד ע' 7."],["341","20","מעבודת הצבא. — ראה שיחת כ' כסלו תרצ\"ג סעיף יח."],["336","16","הרה\"ח ר' אלחנן דובער מאראזאוו, ממזכירי רבינו. באד\"ר תרפ\"ז נאסר ושלחוהו לסיביר לשלש שנים. — ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 28 הערה 1. וש\"נ. לקמן ע' 169."],["343","21","הודעה מוקדמת."],["344","*21","מדה ידוע ברוסיא — לערך עא סנטימטר."],["345","22","ראה גם ספר השיחות תר\"פ­תרפ\"ז שבהערה 17. תש\"ו ע' 54."],["346","*22","ראה אודותו לקמן ע' 95 הערה 41."],["347","23","רבע של חצי ליטר."]]],[4301600206,"דערנאָך פלעגט ער דאָס אַריינשטעלן אין אַ קרעסלע<sup data-n=\"348\">24</sup>.\nדער טאַטע פלעגט ערב פסח דערמאָנען אַ קוק טאָן ביי הענדל'ען אין קרעסלע צי עס איז ניטאָ דאָרט קיין משקה.\nער איז געווען נאָר האַרץ, אָבער האַרץ איז געווען אָן אַ שיעור<sup data-n=\"349\">25</sup>.\nאַמאָל גיין אויף חזרה איז געווען ניט ווי די לעצטע יאָרן, עס איז געווען ניט שטענדיק, אָבער אַז מען פלעגט שוין אַריינגיין פלעגט דער טאַטע לפעמים אָפּלערנען דעם מאמר, איז דאָס אַלעס געווען דורך הענדלען.\nבאַ דעם וירד העיט<sup data-n=\"350\">26</sup> איז מען אַריין דורך הענדל'ען און ס'איז געווען דאָרט אין מאמר<sup data-n=\"351\">27</sup> די ווערטער עצמם און עצמות, האָט פייוול<sup data-n=\"352\">28</sup> געביטן די ווערטער און האָט געזאָגט עצמיים עצמות [ואמר כ\"ק אדמו\"ר: עצמם האָט מען געמיינט דער חיות הכלי עצמן (וזהו בחי' קיום), און עצמות איז דער אור], האָט דער טאַטע אַרויסגענומען אַ פרדס און האָט מיט אונז אָפּגעלערנט אַ שטיקל פרדס<sup data-n=\"353\">29</sup>, און הענדל איז גאָר געזעסן און געשלאָפן אויף אַ שטול און אים איז דאָס גאָרניט נוגע געווען, אָבער ער האָט געדאַרפט זיין.\n[וסיים כ\"ק אדמו\"ר:] און חנן איז אַ תולדה פון הערצל.\nדער עיקר איז עבודה, דאָס איז דער חיות און קיום כל דבר.\nו. [אמר לאחד:] דער אויבערשטער זאָל דיר העלפן אַז דו זאָלסט זיין געזונט אויף אַ אמת, און קענען נעמען אַ ביסל משקה, וואָלט זייער צוניץ קומען. דער אויבערשטער זאָל טאַקע העלפן זאָלסט זיין געזונט אויף אַ אמת.\n[ושאל א': אם כדאי שיתחיל תיכף? ואמר כ\"ק אדמו\"ר:] וואָס מיינסטו אַ ביסעלע, און זאָג לחיים.\nז. בדבר הניגונים אמר: מ'האָט שוין געדאַרפט האָבן אַ סדר זינגען אַלע אַלטע ניגונים, זיי זיינען אָנגעגאָסן מיט חסידות יעדער ניגון דאַרף מען זינגען אַ סאַך מאָל.\n<b>השמטה</b>\nבתוך הדברים [בסעיף א] אמר:\nאדמו\"ר הצ\"צ הי' נכנס להרב ר' אברהם<sup data-n=\"354\">30</sup> טרם שהי' רבי<sup data-n=\"355\">31</sup>.",[["348","24","כורסה."],["349","25","בספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 180 ואילך: החסיד ר\"ח הענדל איז גיווען זייער א הארציגער מענטש, אלץ איז בא איהם גיווען מיט הארץ, אלע מאהל מיט הארץ. עיי\"ש בארוכה."],["350","26","תרנ\"ח (סה\"מ תרנ\"ח ע' יז ואילך)."],["351","27","סה\"מ שם ע' יח ואילך."],["352","28","החסיד ר' שרגא פייוויש זאלמאנאוו. אחד החוזרים של כ\"ק אדמו\"ר מהורש\"ב נ\"ע. ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 17 ובהערה 34 שם. נזכר לקמן ע' 139."],["353","29","ראה פרדס שער טז (שער אבי\"ע) פ\"ב — הובא בסה\"מ תרנ\"ח שם."],["354","30","הר\"ר חיים אברהם בן אדה\"ז — נולד באלול תקל\"ז או תקל\"ח<sup data-n=\"e14\">*</sup> (רשימת היומן של רבינו מיום כ' מ\"ח תרנ\"ו — נדפס בסה\"מ תש\"ט ע' 90). נפטר בשנת תר\"ח ומ\"כ בליובאוויטש (ספר השיחות קיץ ה'ש\"ת ע' 52 בהערה. בית רבי ח\"א פכ\"ד (נו, ב)).\nראה אודותו: רשימת היומן בסה\"מ תש\"ט שם. רשימת היומן של רבינו ב\"התמים\" חוברת ח ע' ח [שפ, ב] ואילך. ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז) ע' 6. לקמן ע' 68. ע' 231. ספר השיחות תרצ\"ו — קיץ ה'ש\"ת ע' 92. ע' 113. ע' 263. שיחת ל\"ג בעומר וש\"פ נצבים תש\"י (התוועדויות תש\"י ע' 60. ע' 212). בית רבי שם."],["355","31","ע\"ד קבלת הנשיאות של אדמו\"ר הצמח צדק — ראה לקמן ע' 243 ואילך. רשימת היומן של רבינו ב\"התמים\" חוברת ג ע' כב [קכז, ב] ואילך. ספר השיחות תש\"א ע' 147­148. בית רבי ח\"ג פ\"ב."],["e14","*","ברשימת רבינו ב\"בטאון חב\"ד\" גליון 39­38 ע' 40 בהערה 26, שנולד בשנת תקמ\"ה. ובספר השיחות תרצ\"ו — קיץ ה'ש\"ת ע' 92, דבשנת תקמ\"ז הי' ר' חיים אברהם כבן שש או שבע. וראה גם ספר השיחות תש\"ד ע' 77 בהערה."]]],[4301600207,"<h3>שמח\"ת קודם הקפות תרפ\"ט<sup data-n=\"356\">1</sup>, ריגא</h3>\nא. [אמר לר' מרדכי דובין<sup data-n=\"357\">2</sup>:] איר זייט אַ איש הטוב והחסד בעצם, אָבער דאָס איז נאָך ניט קיין עבודה. עבודה איז בירור וזיכוך, אַז איינער האָט מדות לא טובות און ע\"י עבודה איז ער זיי מזכך.\nדער טאַטע האָט געזאָגט, עס איז אַ חקירה וואָס איז בעסער צי מען איז געבאָרן במדות טובות אָדער מ'ווערט געבאָרן מיט מדות לא טובות און ע\"י עבודה איז מען זיי מזכך, דער אמת איז אַז דאָס איז בעסער.\nושאל אחד: במה ניכר אם הפועל טוב הוא מצד שהוא איש החסד בעצם או שהוא על ידי עבודה?\nואמר כ\"ק אדמו\"ר: על ידי עבודה איז אַנדערש, אַמאָל דאַרף ער גאָרניט לויפן אַראָפנעמען אַ נאלאָג<sup data-n=\"358\">3</sup> פון פינף רובל פאַר יענעם, ער דאַרף גאָר איצטער לערנען אַ פּרק משניות, נשקשה זאָל יענער אָפּצאָלן, אַמאָל איז גאָר וויילע ער גיט ניט אויף תורה, כהמעשה בגמרא<sup data-n=\"359\">4</sup> על בני אחתי' דר\"י בן זכאי, שנגזר עליהם שיאבדו בשנה זו כך וכך כסף, וואָס ער האָט זיי גענייט געבן געלט אויף צדקה און די איבעריקע האָט מען ביי זיי צוגענומען, און ער דאַרף נאָר קובע זיין עתים לתורה און ניט לויפן אַראָפּנעמען פאַר אים זיינע נאלאָגן.\nאיך בין ניט קיין אַגיטאַטאָר<sup data-n=\"360\">5</sup>, אַנטקעגן די וואַלן בין איך יע אַ אַגיטאַטאָר, אָבער ווי דער ענין פון נר ה' נשמת אדם<sup data-n=\"361\">6</sup>, להאיר אור, און אַנטקעגן די וואַלן איז ניט מיין ענין, נאָר עס פעלט נאָך אייך זייער אַ סאַך להשלים הכוונה דדירה בתחתונים<sup data-n=\"362\">7</sup>. אַ צוווייטיגטער איד כו'.\nב. [אמר לאחד:] דער אויבערשטער זאָל אייך העלפן אַ טוב הנראה ונגלה. וואָרום אין רוחניות איז אַ געשמאַק אין",[["356","1","כ\"ה בכת\"י השיחה שתח\"י. אבל בכ\"מ בשיחה זו משמע שנאמרה כשהי' עדיין ברוסיא. ואולי נאמרה בשמח\"ת תרפ\"ח."],["357","2","ציר יהודי בסיים (בית הנבחרים) הלטבי. וע\"י השתדלותו יצא רבינו מרוסיא. ראה אודותו \"די יסורים פון ליבאוויטשן רבין אין סאוועט­רוסלאנד\" (ריגא, 1930) ע' 73 ואילך."],["358","3","מס."],["359","4","בבא בתרא י, א. ראה גם לקמן ע' 60."],["360","5","תעמלן."],["361","6","משלי כ, כז."],["362","7","ראה תניא פל\"ו. ובכ\"מ."]]],[4301600208,"דאַוונען אויך אַ טוב, אָבער ער איז נאָך ניט נראה ונגלה; און אין גשמיות איז אַ טוב נראה ונגלה. דער אויבערשטער זאָל אייך העלפן עס זאָל אַזוי גוט זיין אַז נאָך אַלע געשעפטן זאָל אייך בלייבן צייט אויף לערנען חסידות.\nג. [אמר לאחד:] דו ביסט געזונט און וועסט אי\"ה זיין געזונט, נאָר די באָרד זאָלסטו ניט טשעפּען, דאָס טויג ניט, פע, דאָס זאָל מען ניט טשעפּען. און דו זאָלסט זאָגן אַלע טאָג דעם יום תהלים און די פרשה עם רש\"י, וועסטו גיין אין מאָסקווע און קיינער וועט דיך ניט טשעפּען. אויב דו קענסט ניט לערנען אַליין די פרשה חומש עם רש\"י וועסטו בעטן וועמען עס איז זאָל מיט דיר לערנען, נאָר חומש מיט רש\"י קענסטו אַליין, קיין גמרא קענסטו ניט. [וצייר כ\"ק אדמו\"ר:] אַז מען האָט אים געוואָלט פאַרהערן בעת ער האָט געלערנט אין זאַל, האָט ער אויסגעשטעלט די אויגן, וואָס איז דאָס מיך אויך פאַרהערן?\nדער רבי דער צ\"צ איז דאָך אַ מרא דאתרא במדינת רוסיא, און ער פּסק'נט אַז דאָס איז אַ איסור דאורייתא<sup data-n=\"363\">8</sup>, במילא דאַרף מען די באָרד ניט טשעפּען, און זאָגן דעם יום תהלים<sup data-n=\"364\">9</sup> במילא דאַרף מען שוין דאָך דאַוונען מיט אַ מנין, ואז יהי' לך טוב, ויתן לך השי\"ת זרעא חייא וקיימא בשנה זו (כ\"ק אדמו\"ר נתן לו חתיכת בשר מבשר שלו לכוונה זאת).\n[אמר לר' לייב, בעה\"ב של חתנו הרש\"ג:] ע\"י חתני נודע לי שעקרת ביתך איז אַ ערלעכע, כי היא בת מלמד, און דאָס איז דער גרעסטער יחוס ביי אידן, וגם הוא איז אַ ערלעכער, אבל שיניח את הזקן, און זאָל זי ניט טשעפּען, אַ ערלעכער איד דאַרף ניט טשעפּען די באָרד, און ער זאָל זיך אַוועקגעבן אויף תורה, און גיין קלייבן געלט אויף תורה.\nאַז דער רב האָט אַ ישיבה דאַרף ער געלט, און איך וועל אי\"ה אויך מאַכן אַ ישיבה, מילא איך דאַרף קיין געלט ניט, איך האָב געלט, פאַראַן אַ איד פאַר צען טויזענט וויאָרסט און האָט פינף טויזענט רובל, געהערט דאָס צו מיר.\nאָבער דאַרפסט זען אַז עס זאָל זיין געלט אויף תורה, איר האָט דעם וויגרעש<sup data-n=\"365\">10</sup> ווי איינער וואָס האָט אַ וויגרעש און געווינט אויף אים אַ מיליאָן רובל, איז דאָך דער מיליאָן געווען אין דעם וויגרעש, וויבאַלד אַז עס קומט די צייט פון געווינס קריגט ער פאַר עם דעם מיליאָן רובל, נאָר אַ נאַר פאַרקויפט עס מיט אַ האַלבע שעה פריער פאַר'ן געווינס, אָט אַזוי איז איר האָט דעם וויגרעש איר דאַרפט קלייבן געלט אויף תורה.\nהזקן רומז לבחינות עליונות, בחינת עתיק, י\"ג תיקוני דיקנא<sup data-n=\"366\">11</sup>, ווי האָט מען קיין מורא ניט טשעפּען זיך מיט דעם בכלל אַ איד דאַרף טראָגן אַ באָרד.",[["363","8","שו\"ת צ\"צ יו\"ד סצ\"ג. וראה גם חידושיו על הש\"ס מכות פרק ג. פסקי דינים ליו\"ד סקפ\"א­ב. וראה מכתב רבינו — נדפס בקובץ יגדיל תורה ניו יארק שנה ז חוברת נד ע' רסג ואילך. אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' ד ואילך. חי\"ט ע' פה (ושם: \"אדמו\"ר הצמח צדק [דהלכה כמותו בכל מקום, ובפרט בהנוגע לאנ\"ש ואלו שזכו ליהנות מאור תורת החסידות]\")."],["364","9","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 116. ובכ\"מ."],["365","10","כרטיס הגרלה."],["366","11","ראה רשימות הצ\"צ לתהלים אוה\"ת (יהל אור) ע' תרכו ואילך. ועוד. לקוטי שיחות חכ\"ג ע' 303. וש\"נ."]]],[4301600209,"ד. אמר אחד: היינט האָט מען געזאָגט אַ טוטווייען וואָרט, אַז אַ בע\"ת איז אַ מרוחק בעצם.\nואמר כ\"ק אדמו\"ר:\nכן, דער טאַטע האָט מיר מכריח געווען צו זאָגן דאָס, עס איז מיר געווען זייער שווער צו זאָגן דאָס, איך האָב זיך געדרייט אַזוי און אַזוי, אָבער דער טאַטע האָט מיר מכריח געווען. אַ בעל תשובה האָט דאָך עילוים אין זיך, און מ\"מ איז ער בעצם אַ מרוחק<sup data-n=\"367\">12</sup>.\n[שאל הישיש הרז\"י<sup data-n=\"368\">13</sup>: מה תקנתו? ואמר כ\"ק אדמו\"ר:] ער דאַרף משנה זיין דעם עצם.\nה. עס איז אַ פּלא וואָס דער טאַטע לאחר הסתלקותו איז אַלץ איינס ווי בחייו<sup data-n=\"369\">14</sup>, שאר הצדיקים לאחר הסתל­קותם קוקן זיי אויף דער וועלט בחסד וברחמים, און דער טאַטע קוקט אויף דער וועלט אַלץ איינס ווי בחייו. אָט אַזוי ווי בחייו האָט ער אין יעדער ענין געגאַנגען געשניטן, כמו כן הוא גם עכשיו, ער קוקט אויף יעדערן, וואָס כמעט בדרך [...] הייסט ער וואָס מען זאָל איבערגעבן יעדער תמים ווי ער זאָל זיך פירן, ער זאָל טראַכטן כך וכך וכדומה.\nדער טאַטע האָט זיך מוסר נפש געווען אויף די תמימים אַ מסירת נפש בפועל ממש, און ער גלויבט זיי קיינעם ניט אָפּ.\nושאל הרז\"י: אייך גלויבט ער יע אָפּ?\nואמר כ\"ק אדמו\"ר: אפילו מיר אויך ניט.",[["367","12","ראה סה\"מ תרפ\"ד ע' כ. תש\"ט ע' כט."],["368","13","אולי הוא הנזכר בשיחת יט כסלו תרצ\"ב."],["369","14","ראה גם לקמן ע' 164."]]],[4301600210,"<h3>יום שמחת תורה תרפ\"ט<sup data-n=\"370\">1</sup></h3>\nא. דער טאַטע<sup data-n=\"371\">2</sup> אמר לאחד על יחידות בזה\"ל: \"דער טאַטע<sup data-n=\"372\">3</sup> האָט געזאָגט אַז תוקפא דגופא<sup data-n=\"373\">4</sup> תוקפא דנשמתא\". איז דורך די ווערטער איז ער געזונט געוואָרן.\nדתחלת העבודה האמיתית היא להיות כמו שהאלקים עשה את האדם ישר<sup data-n=\"374\">5</sup>, דבירור המדות אינם עבודה רק תיקון החסרון, וואָרום מדות לא טובות דאָס",[["370","1","חלק משיחה זו (סעיף ז וסעיף יב) י\"ל בפ\"ע בהוצאת קה\"ת — ב' ניסן תשכ\"ב. ובה\"פתח­דבר\" שם:\nאין דעם חוברת ווערט ארויסגעגעבן אן אויסצוג פון א שיחה — לויט א פארצייכענונג פון איינעם פון די הערער — וואס כ\"ק אדמו\"ר ר' יוסף יצחק זצוקללה\"ה נבג\"מ זי\"ע האט גערעדט וועגן דער עבודה פון א שוחט — שמחת תורה תרפ\"ט.\n{_*_} {_*_} {_*_}\nדי הערות ומראי מקומות זיינען פון כ\"ק אדמו\"ר שליט\"א.\n\"מערכת אוצר החסידים\""],["371","2","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["372","3","כ\"ק אדמו\"ר מהר\"ש נ\"ע."],["373","4","ראה גם ד\"ה באתי לגני תשי\"ג פ\"ו (סה\"מ מלוקט ח\"א ע' לד). לקוטי שיחות ח\"ג ע' 806. ועוד."],["374","5","ע\"פ קהלת ז, כט."]]],[4301600211,"דאַרף ניט זיין, וכאשר רואים איזה דבר לא טוב בזולתו, צריך להצטער ע\"ז<sup data-n=\"375\">6</sup>, ולחשוב שזהו מהלא טוב שלו<sup data-n=\"376\">7</sup>, הזולת בעצמו הוא טוב, וא\"כ הלא טוב שבזולת הוא מצד הלא טוב שלו, וכאשר מתקן הלא טוב שלו, הנה זה פועל בהזולת, א\"כ הרי זה רק תיקון החסרון בלבד.\nוענין העבודה היא כמו שהאלקים עשה את האדם ישר, בעבודה פנימית, זיין אַ כלי צו אור פנימי (אשר בהתחלה יש כמה מניעות מסבות שונות, וואָס אַ מלאך חגר סומא או חרש האָט אַריין געזאָגט בעת ירידת הנשמה מהיכל להיכל בשביל להתלבש בגוף, כמבואר בספרים), אשר לעבודה זו צריכים גוף בריא. בכלל אַ איד דאַרף זיין געזונט<sup data-n=\"377\">8</sup>, ואז בכחו לעבוד עבודתו בדרך כמו שהאלקים עשה את האדם ישר, ממשיך זיין אור ע\"י לימוד התורה וקיום המצות וואָס מיט דעם איז מען מכשיר דעם גשמיות ער זאָל קאָנען נתברר ווערן, ואח\"כ מגיע גם להאור חוזר, אויף מאַכן כללות ענין הגשמי בעולם שיהי' כלי לגילוי אלקות.\nועי\"ז וואָס דער טאַטע האָט אים געזאָגט, תוקפא דגופא תוקפא דנשמתא, איז ער געזונט געוואָרן.\nב. (דיבר עם ר' ישראל שיחי'): נעכטן האָב איך דיר מבטיח געווען אַלעס, נאָר אויב דו וועסט מאַכן אַ כלי צו אלקות וועסטו האָבן אַ טוב עד אין שיעור, עד שיבלו שפתותיכם מלומר די<sup data-n=\"378\">9</sup>, נאָר מאַכן אַ כלי צו אלקות. און מאַכן אַ כלי צו אלקות מאַכט מען מיט תורה, היינו גייענדיק אין די גאַסן טראַכטן אַ ענין אין תורה. אַ פסוק גדול הוי' ומהולל מאד, חנון ורחום ה'<sup data-n=\"379\">10</sup>, בכלל אַ ענין פון תורה.\nעס קומען צו דיר קונדן<sup data-n=\"380\">11</sup> פרעג באַ זיי: וואָס טוט זיך ביי אייך אין שטעטל, צי מען זאָגט תהלים, צי מען לערנט חומש מיט רש\"י.\nאון וואו מען גייט דאַרף קענטיק זיין אַז דאָ איז געגאַנגען אַ איד, אויף דעם שטיין האָט געטראָטן אַ איד.\nמען דאַרף מאַכן אַ כלי צו אלקות אָן חכמות, וועט מען זיך זען מתוך הרחבה.\nג. (ואח\"כ נמשך הדיבור עם ר' שמואל יעקב הכהן<sup data-n=\"381\">12</sup>:) איך וועל אייך זאָגן דו, חאָטש עס איז מיר זייער שווער, אָבער אַ איד וואָס איז געפאָרן צום טאַטן, וועט האָבן דערפון אַ נחת רוח, דאַרף מען זיך מוסר נפש זיין טאָן אַ אידן אַ טובה, זאָג איך דו.\nדו ביסט דאָך אַ בעל עסק, דער אויבערשטער וועט אייך געבן דעם יאָר",[["375","6","ראה גם אגרות­קודש ח\"ה ס\"ע קא ואילך (הועתק ב\"היום יום\" יב כסלו)."],["376","7","ראה גם לקמן ע' 62. ספר השיחות תר\"פ­תרפ\"ז ע' 83."],["377","8","ראה רמב\"ם הל' דעות רפ\"ד. וראה מקומות שצויינו בהערה 4."],["378","9","שבת לב, ב. תענית ט, א. כב, א."],["379","10","תהלים קמה, ג. שם, ח."],["380","11","קונים."],["381","12","רש\"י הכהן כ\"ץ. נזכר בספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 335.\nזקנו ר' וועלוול הי' אחד מחברי ה\"קאפעליע\" של אדמו\"ר האמצעי<sup data-n=\"e15\">*</sup> — ראה ספר השיחות תש\"ג ע' 97. שיחת תמוז תש\"ד להמסדר דספר הניגונים (נדפסה בספר הניגונים ח\"א ע' מט)."],["e15","*","ע\"ד ה\"קאפעליע\" — ראה אגרות­קודש ח\"ג ע' תמד ואילך (הועתק ב\"היום יום\" כה תשרי). ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 254. תש\"ב ע' 122."]]],[4301600212,"פרנסה מרובה נאָר איר זאָלט מאַכן די גשמיות כלים צו אלקות.\nד. (ונמשך הדיבור עם אחיו של רש\"י:) דאָס וואָס ער טראָגט די קייטעלע אום יו\"ט, דאָס דאַרף ניט זיין. און דאָס פועל'ט אַ הגשמה.\nאין פלוג איז דאָך דאָס טוב, אַ תכשיט צוליב יו\"ט, אָבער באמת דאַרף דאָס ניט זיין.\nאָט ווי אַ ענדיק אויף יו\"ט, ווערט דאָס יו\"ט מיט אַ ענדיק. אַ ענדיק אויף יו\"ט איז גוט, עס דאַרף זיין ושמחת בחגך. אָבער אַז יו\"ט איז מיט דעם ענדיק — דאָס איז אַ העלם און פועל'ט אַ הגשמה.\nבחול איז די קייטעלע צוליב באָרגן אַ גמ\"ח, ער טראָגט אַ שיינע קייטעלע קריגט ער אַ גמ\"ח געכער.\nבאַ דעם רוזינער זצוק\"ל זי\"ע איז געווען אַ זילבערנע קאראד. איז דאָס נאָר ביי דעם וואָס איז שייך צו דעם<sup data-n=\"382\">13</sup>. וואָס אַזוי איז אויך געווען אין ביהמ\"ק<sup data-n=\"383\">14</sup>. באַ אונזערע רביים איז ניט געווען אַזוי להשתמש בכסף כו'. ביי דעם רבי'ן איז געווען ווייסע שטולן. אָבער באַ דעם וואָס ער איז ניט שייך צו דעם איז דאָס אים מגשם.\nאָבער יו\"ט דאַרף מען ניט טראָגן קיין קייטעלע, און דענסטמאָל וועלן די קינדער און אין שטוב דערהערן דעם יו\"ט, זיי זאָלן וויסן אַז יו\"ט איז עפּעס אַ העכערער ענין, מען דאַרף דערציילן מענין היו\"ט אויב זיי ווייסן ניט.\nה. (ונמשך הדיבור עוד הפעם לרש\"י:) דו דאַרפסט וויסן אַז אַ בעל עסק דאַרף מאַכן אַ כלי צו אלקות, עס זאָל קענטיק זיין אַז אויף דעם שטיין האָט געטראָטן אַ איד. ווי אַ שיף וואָס גייט אין ים בלייבט אַ שטראָם, וואָס דער טאַטע איז דאָס מבאר בהמבואר כי המעיינות נמשכים מהתהום, איז דער שטראָם על דרך נהרא פלג לי מימיך<sup data-n=\"384\">15</sup>. אָט אַזוי דאַרף זיין קענטיק אַז אויף דעם שטיין האָט געטראָטן אַ איד.\nמען דאַרף עס זאָל זיין ווי אין די שטרות התנאים שלמעלה, עס איז פאַראַן דער שושבין מצד החתן, דער חתן הוא הקב\"ה<sup data-n=\"385\">16</sup>, וואָס ער איז בחי' נחות דרגא<sup data-n=\"386\">*16</sup> להשפיע טוב לישראל, בטוב הנראה והנגלה, נאָר מען דאַרף אָפּהיטן די תנאים פון די שטרות.\nאָט אַזוי ווי עס איז דאָ אַ מעקלער<sup data-n=\"387\">17</sup>, פון די עלטערן קענט איר ניט הערן, זיי ריידן מיט אייך אָבער איר קענט ניט הערן, ווייל זיי זיינען מיט אַ מדור העכער. ע\"ד בת קול שאין אנו שומעים בהארת הנשמה המלובשת בגוף<sup data-n=\"388\">18</sup>, וענין",[["382","13","להעיר מהמבואר בנוגע עשירותו של אדמו\"ר מהר\"ש — ראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' ריא. שיחות: ש\"פ האזינו, י\"ג תשרי תשי\"ב. ש\"פ מקץ תשט\"ז בסופה. פורים תשכ\"ח. מוצש\"ק האזינו, י\"ג תשרי תשל\"ט. י\"ג תשרי תש\"מ. י\"ג תשרי תשמ\"ג (התוועדויות ח\"א ע' 150). י\"ג תשרי תשד\"מ (התוועדויות ח\"א ס\"ע 154 ואילך). מוצש\"ק צו, אור לי\"ג ניסן תשמ\"ז (התוועדויות ח\"ג ע' 97). ועוד."],["383","14","ראה ב\"ר פט\"ז, ב. שמו\"ר רפל\"ה. וראה שיחת ש\"פ מקץ שבהערה הקודמת. ועוד."],["384","15","חולין ז, א. וראה ספרי הרב המגיד — לקוטי אמרים נז, ד ואילך. אור תורה לא, ג ואילך."],["385","16","ראה מכילתא ופרש\"י יתרו יט, יז. פרש\"י ברכה לג, ב."],["386","*16","תו\"א הוספות שמות קו, א. ובכ\"מ."],["387","17","מתווך, סרסור."],["388","18","ראה כתר שם טוב יח, ג. נג, ד. לקו\"ת תצא לו, ד. האזינו עא, ד. ובכ\"מ."]]],[4301600213,"זה הוא ענין פנימי יותר, הבת קול הוא ממלאך און דאָס איז דאָך אַ גילוי פון נשמות, הערט איר ניט, איז דאָ אַ מעקלער אַ בא כח פון עלטערן, זאָגט דער בא כח המשלחים אַז מען דאַרף מאַכן אַ כלי צו אלקות.\nו. דיבר אל אחד מהעומדים שקראו אותו בכינוי, ואמר שצריכים לקרותו בשם ולא בכינוי, ואמר לו: איר גייט אַרום בשווקים ורחובות, איז דאַרפט איר מאַכן כלים צו אלקות. און די ?אָרד דאַרף מען ניט טשעפּען<sup data-n=\"389\">19</sup>, די חמש פאות טאָר מען דאָך אודאי ניט טשעפּען, וואָדען די איבעריקע און מאַכן אַ פּליעך<sup data-n=\"390\">20</sup> אין מיטן, איז ווער לאָזט דאָס מאַכן אַ פּליעך.\nצו אַ דבר אסור דאַרף אַ איד קיין שייכות ניט האָבן, עס טרעפט נאָר וואָס מען איז זיך מקיל אין אַ ביסקוויט ניט אַ אידישן, ווייל דאָס איז דאָך נאָר דרבנן<sup data-n=\"391\">21</sup>, חלב שחלבו עכו\"ם ואין ישראל רואהו<sup data-n=\"392\">22</sup>, פאַרגעסט מען אויף אַ וויילע אויף דעם מאמר<sup data-n=\"393\">23</sup> ערבים עלי דברי סופרים, און באמת איז דאָך דורך די הגדרות איז מען ממשיך אַ אור עליון יותר, וואָס מבטל זיין אַ דרבנן דאַרף אויך ניט זיין.\nוהנה בענין הבעלי עסקים שיעשו כלים לאלקות, מיט דעם וואָס ער וועט טראַכטן אַ פסוק תורה, הגם שזהו מנחת עני, ומ\"מ הוא יקר במאד, וכמו מנחת מרחשת<sup data-n=\"394\">24</sup>.\nמען דאַרף פּויזען<sup data-n=\"395\">25</sup>, אַז מען קען ניט גיין דאַרף מען לכל הפחות פּויזען כענין המדדה אין מדדה יותר מנ'<sup data-n=\"396\">26</sup>, והיינו המדדה יכול להגיע לשער הנו\"ן.\nמען דאַרף מאַכן אַ כלי צו אלקות. באמת איז דאָך דער גשם נאָר אַ געלעכטער, לעצמו איז ער דאָך ניט קיין זאַך, דאָס איז דאָך אלקות, נאָר דאָס איז דער אלקות באופן ווי נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"397\">27</sup>, אוה למושב לו<sup data-n=\"398\">28</sup>, כי טוב, טבע הטוב להטיב<sup data-n=\"399\">29</sup>, איז מיט וועמען איז ער מטיב. דבאמת הרי לית אתר פנוי מיני'<sup data-n=\"400\">30</sup>, לאחה\"צ כמו קודם הצמצום, היינו מיט וועמען איז ער מטיב, מיט זיך אַליין? אָבער די כוונה עליונה איז דאָך באופן כזה אַז דער גשם ווייזט זיך אַרויס כמו אַ זאַך ממש, און פון דער זאַך דאַרף מען אַראָפּנעמען די גשמיות דערפון, עס זאָל זיך אַרויס זען דער אמת פון דעם. איז אָט דער ענין פירט זיך אויס דורך נשמות המלובשים בגוף שהם דוקא ביכולתם לעשות הגשמי כלי לאלקות.\n\"המלאכה מרובה והפועלים עצלים כו' ובעה\"ב דוחק\"<sup data-n=\"401\">31</sup>, איז אַז מען דערהערט דעם \"בעל הבית דוחק\" דאָס",[["389","19","ראה לעיל ע' 35. וש\"נ."],["390","20","קרחת."],["391","21","ראה ע\"ז לה, ב. רמב\"ם הל' מאכלות אסורות פי\"ז ה\"ט. טושו\"ע יו\"ד סקי\"ג ואילך. ועוד."],["392","22","ע\"ז שם. וראה רמב\"ם שם פ\"ח הי\"ז­ח. פי\"ג ה\"י. ועוד."],["393","23","ע\"ז שם, א."],["394","24","ויקרא ב, ז."],["395","25","לזחול."],["396","26","ביצה יא, א. בבא בתרא כג, ב."],["397","27","תנחומא נשא טז. ועוד. תניא פל\"ו."],["398","28","תהלים קלב, יג."],["399","29","ראה עמק המלך שער שעשועי המלך רפ\"א. שעהיוה\"א פ\"ד (עט, א). וראה הערת כ\"ק אדמו\"ר במאמרי אדמו\"ר האמצעי קונטרסים ע' ה."],["400","30","תקו\"ז תנ\"ז (צא, ב). שעהיוה\"א פ\"ז (פג, ב)."],["401","31","אבות פ\"ב מט\"ו."]]],[4301600214,"הייסט אַז מען דערהערט די כוונה העליונה וואָס פירט יעדערן בהשגחה פרטית און הוא ית' גיט אים כחות לעבוד עבודתו בלימוד התורה וקיום המצוות, איז אַז מען דערהערט דאָס איז גוט, אָבער אַז עס זעט זיך דער \"הפועלים עצלים\" טויג ניט. די עבודת האלקות דאַרף מען טאָן ווי אַ קלוגער בעל עסק, אַ קלוגער בעל עסק — ער ווייסט נאָר אַז מען דאַרף פירן דעם געשעפט, עס איז פאַראַן אַ זמן וואָס עס איז שווער צו צאָלן אין זמן, ניט וויילע עם אַרט דאָס ניט, אָדער וויילע ער איז ניט ערלעך, ער וויל צאָלן און וועט צאָלן און קען צאָלן, נאָר ער מוז דאָס טאָן מיט אַ חשבון בכדי דער געשעפט זאָל זיך קענען פירן בעזהש\"י ווי מען דאַרף. א קלוגער בעל עסק ליגט אין דעם אַז דער עסק זאָל זיך פירן אָן אַ הפסק, דער וואָס ווערט נתפעל פון אַ גרויסן פאַרדינסט איז אַ נאַר, און כמו\"כ הנתפעל מאיזה הפסד ח\"ו איז אויך אַ נאַר.\nגלגל הוא החוזר בעולם<sup data-n=\"402\">32</sup>, די וועלט איז אַ גרויסער ראָד. דער וואָס שטייט אויפן ראָד ומצליח בכל עניניו, ורוחו גבוה עליו, און איז ביי זיך ברייט אין דער דעה מיט זיינע פּאָר גראָשן, ולפעמים גם עז וכמ\"ש<sup data-n=\"403\">33</sup> \"ועשיר יענה עזות\", איז ער אַ נאַר. וויילע ער פאַרגעסט אַז ער שטייט אויף אַ ראָד וואָס דרייט זיך, דער וואָס חלילה די צייט איז געדריקט אין פרנסה וכו' און ער שטייט אויף דעם אונטן פון דעם ראָד, און איז באַ זיך חלילה אַראָפּ געפאַלן און דער גימיט זיינער איז אַ צובראָכענער פון זיין ניט גוטן מצב חלילה, איז אויך אַ נאַר. וויילע ער פאַרגעסט אַז ער שטייט אויף אַ ראָד, אַ ראָד איז אַ קיילעכדיקער זאַך עס איז ניט פאַראַן קיין אויבן און קיין אונטן, עס האַלט זיך אין איין דרייען זיך.\nאַ קלוגער איז דער וואָס ווען ער שטייט אויבן טראַכט ער וועגן דעם וואָס די ראָד דרייט זעך, און מען דאַרף זיין אַ מענטש. און אַז מען שטייט חלילה אונטן טראַכט ער וועגן דעם אויבן.\nכמו\"כ אַ קלוגער בעל עסק טראַכט תמיד נאָר די ראָד זאָל זיך דרייען, עס זאָל זיך ניט אָפּשטעלן, איז יעמאָלט טאָמער חלילה איז ער אפילו אַ וויילע אונטן וועט ער בעזה\"י ארויפקומען על מצב טוב.\nאון אַזוי בעבודת האלקות, מען דאַרף טאָן. דאָס וואָס עס קומט חובות פון עבר דאַרף מען געוויס צאָלן ביסלעכווייז אָבער דער עסק דאַרף זיך ניט אָפּשטעלן. מען טאָר ביי זיך ניט זיין געהויבן אַז מען פאַרשטייט כלומר'שט אַ וואָרט חסידות, אָדער אַז מען דאַוונט ווי מען דאַרף, וויילע עס איז דאָך דאָ אַ אונטן — דאָס הייסט ווי פירט מען זיך נאָכן דאַוונען. וכן וואָס איז די פעולה פון דעם אַז מען פאַרשטייט אַ וואָרט חסידות, אָבער חסידות אָן עבודה איז גאָרניט. וכן להיפך אין צריכים להיות בעצבות ומרה שחורה מהמצב הלא טוב, כ\"א שצ\"ל ענין המרירות שזה מביא לידי פועל טוב. וואָרום עבודת הבירורים הוא כמו עבודת הבעל עסק און אַזוי ווי אַ קלוגער בעל עסק ווייס נאָר אַז מען דאַרף פירן דעם געשעפט כו', אָט אַזוי דאַרף מען טאָן עבודה.",[["402","32","שבת קנא, ב. וראה ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 32. אגרות­קודש ח\"ה ע' קיח. ח\"ז ע' ס. לקמן ע' 207."],["403","33","משלי יח, כג."]]],[4301600215,"ז. (.. . הדיבור<sup data-n=\"404\">34</sup> עם ר\"מ<sup data-n=\"405\">35</sup> שו\"ב שי'):\nמען האָט געדאַרפט מבטל זיין די מניעות ועיכובים וואָס דער שוחט האָט ניט קיין צייט צו טאָן אין תורה ועבודה. אַ שוחט<sup data-n=\"406\">36</sup> דאַרף מען קאָנען אין בית המדרש, ניט פון באָינע<sup data-n=\"407\">37</sup>. אַ שוחט איז דען אַ סקאָטאָבאָיעץ<sup data-n=\"408\">38</sup>? דער ענין פון נטילת נשמה איז דאָך אַ שווערער ענין זייער, דאַרפסט דאָס פאַרשטיין בעומק, גאָר טיף. נטילת נשמה איז דאָך זייער אַ שווערער ענין. באמת איז דער תחלה פון דעם אין גליא שבתורה, איז דאָס וואָס יצחק האָט געזאָגט עשו'ן, וצודה לי ציד­ה<sup data-n=\"409\">39</sup>, דער ה' פון צידה כנודע<sup data-n=\"410\">40</sup>. אָבער דאָס איז אַ שווערער ענין. דער קו הגבורה בכלל, און זיין אַ כלי צו גילוי אור אלקי מיט דעם קו הגבורה, איז זייער שווער<sup data-n=\"411\">41</sup>. און בפרט נטילת נשמה, הוצאת דם. מען נעמט די הינדל, מען ציט אויס דעם סימן, וואָס טוט מען, מען איז שופך דם. און מען טוט דאָס אַזוי קאַלט. וואָס באמת צו דער אַרבעט דאַרף זיין אַזוי. אפילו בענין המילה<sup data-n=\"412\">42</sup> דאַרף דאָך זיין שלא יתבהל, שלא יתעלף כו'<sup data-n=\"413\">43</sup>, דאם לא כן לא תהי' העובדא כדבעי. וכן בשחיטה. אמנם הוא עובדא של נטילת נשמה, און עס איז אַזוי מיט קאַלטקייט. צוליב, אַז אברהם, ברוך, גדלי', דוד זאָלן עסן אַ כשר'ן שטיקל פלייש, וואָס עס קאָן זיין אַז ער איז גאָר אין דעם פאַל וואָס אסור לאכול בשר<sup data-n=\"414\">44</sup> (כמבואר בענין גדרים<sup data-n=\"415\">45</sup>). און באמת דאַרף מען דאָך שעכטן און אַלע זאָלן האָבן נאָר כשר'ע פלייש. דערפאַר איז שחיטה ווערט אָנגערופן אַ מלאכת ד', און אַ שו\"ב איז דער עושה מלאכת ד'. אמנם העשי' גיין נוטל נשמה זיין לשפּוך דם. וואָס נאָך הונדערט און צוואַנציק יאָר איז דאָך ניט גוט צו האָבן צו טאָן אפילו מיט קיין מענטשן, כל שכן מיט בהמות<sup data-n=\"416\">46</sup>.\n* * *\nאַלע פאַרשטייען גוט, אַז ניט דאָס איז אַ שוחט וואָס גייט אַרום מיט אַ מאכלת. אַ מלאך המות גייט אַרום מיט אַ",[["404","34","סעיף זה י\"ל בפ\"ע כנ\"ל הערה 1."],["405","35","ר' מרדכי חפץ מדיסנא. שו\"ב בריגא. ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 18 ובהערה 39. נזכר לקמן ע' 68. 168. 206."],["406","36","ראה גם שיחת כ' אדר שני תרצ\"ב."],["407","37","בית מטבחים."],["408","38","איש ומאכלת בידו. — ראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ב ע' שפא. חי\"ג ע' קסח. חי\"ז ע' רצה. וראה גם אגרות­קודש חי\"ג ע' תקכה. ולהעיר מד\"ה להבין ענין שו\"ב במאמרי אדה\"ז ענינים ע' תי."],["409","39","תולדות כז, ג."],["410","40","ראה דעת זקנים מבעה\"ת וחזקוני תולדות (כז, ג). ס' הליקוטים להאריז\"ל שם. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["411","41","להעיר מד\"ה עלה אלקים דשנה שיחה זו (תרפ\"ט<sup data-n=\"e16\">*</sup> — נדפס (בקופיר) בשנת ה'תש\"ו). — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["412","42","להעיר משבת [קנו,] א. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["413","43","להעיר מנוסח הרחמן לברית מילה: הרחמן הוא יברך המל בשר הערלה. . איש הירא ורך הלבב עבודתו פסולה."],["414","44","ראה לקו\"ת בהעלותך לא, ד. ועוד. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["415","45","אוצ\"ל: נדרים. — ראה לקו\"ת מטות פב, ב (ומציין שם ללקו\"ת בהעלותך שבהערה הקודמת). ובכ\"מ."],["416","46","להעיר מזהר חדש בראשית סד\"ה א\"ר יוסי בן פזי (יא, סע\"ג). — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["e16","*","סה\"מ תרפ\"ט (קה\"ת, תש\"נ) ע' 25 ואילך. המו\"ל."]]],[4301600216,"מעסער. אַ שוחט איז אַן עבד ד', וואָס ער איז מקיים דעם רצון הבורא יתברך, און גיט אידן כשר'ע פלייש. דאַרף דאָך דער עבד ד' האָבן צייט צו לערנען און דאַוונען ווי עס בעדאַרף צו זיין.\n* * *\nדער שוחט אין אַ שטאָט איז אַן עמוד בבית ישראל. אַ רב, אַ שוחט, אַ מלמד, דאָס איז ג' עמודים<sup data-n=\"417\">47</sup> וואָס בית ישראל נשען עליהם. איז אַ שוחט דאַרף זיין אין בית המדרש, לערנען אַ שיעור, אַ בלאַט גמרא, חסידות וכו'.\nדער בכן איז, אַז מען דאַרף אַראָפּנעמען אַלע מניעות ועיכובים און אַז די שוחטים זאָלן האָבן צייט צו לערנען און דאַוונען כדבעי למהוי.\nעס איז פאַראַן אַ טענה, וויילע די צייטן וואָס די אופּראַווע<sup data-n=\"418\">48</sup> האָט אויסגעשטעלט איז אַ מניעה. די אופּראַווע דאַרף דאָך זיין ווי אַן אופּראַווע צו שפּאַקולן<sup data-n=\"419\">49</sup> וואָס מאַכט אַז די ראי' זאָל קומען בעסער. מיר האָבן אַן אמת'ע אופּראַווע. די חוקים פון תורה ומצוות דאָס איז אונזער אופּראַווע. וואָס אַלע חוקי המלוכה, איז אויב עס קאָן זיין קיום חוקי התורה, דעמאָלט איז דאָס חוקים<sup data-n=\"420\">50</sup>. און דאָס איז דאָך נוגע צו כשר'ע פלייש, איז געוויס אַז מען וועט געבן גוט צו פאַרשטיין, וועט מען דאָס פאַרשטיין, און בעזהש\"י וועט געוויס זיין גוט.\n* * *\nח. מען האָט געדאַרפט צונויף קלייבן די חסידישע בעלי עסקים, זיי זאָלן מאַכן כלים צו אלקות. די רוסישע אידן זאָלן געזונט זיין איז אַ גרויסער חלק פון זיי כ\"י, מאַכן כלים לאלקות, דערפאַר איז דאָרטן פאַרמאַכט מען שוין די מערק. זיי האָבן שוין דאָרטן ניט וואָס צו טאָן, זיי דאַרפן שוין עסן \"לחם מן השמים\" — מן, און דער אויבערשטער זאָל זיי געבן אַ השפעה מרובה, אמן.\nזעט, זיי גיט מען די עבודה פון מסירת נפש, זיי פּוצן שוין דעם מונדיר צו גיין אַנטקעגן משיח'ן<sup data-n=\"421\">51</sup>. זיי פּוצן די קנעפּלעך פון די בגדים צו גיין אַנטקעגן משיח'ן<sup data-n=\"421\">51</sup>. און איר זאָלט מאַכן כלים צו אלקות, וועלן מיר אויפהערן צו ליידן. גענוג צרות ר\"ל האָבן מיר שוין געהאַט, און אַז מען וועט מאַכן כלים צו אלקות וועלן מיר קאָנען צו נעמען דעם גילוי אור המשיח, און עס וועט אַראָפּ אַלע מניעות ועיכובים פון תורה. ו\"תורה אור\", מיט דעם אור",[["417","47","אולי אפ\"ל: רב — תורה, קו האמצעי. שוחט — כנ\"ל גבורה. מלמד — מביאו לחיי העוה\"ב (ב\"מ לג, א) — גמ\"ח. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["418","48","כנראה הכוונה לחוקים."],["419","49","משקפים."],["420","50","להעיר מש\"ך יו\"ד סל\"ג סקל\"ט. וש\"נ. וראה ספר השיחות תש\"ג ע' 83. קונטרס אדמו\"ר הצ\"צ ותנועת ההשכלה ע' 24."],["421","51","הובא ונתבאר לרוב ע\"י כ\"ק אדמו\"ר — ראה לקוטי שיחות חלק כה ע' 481. חלק כט ע' 286. שיחת ה' טבת וי\"ב טבת תשמ\"ז (התוועדויות ח\"ב ע' 173. ע' 236 הערה 10). ספר השיחות תשמ\"ח ח\"א ע' 279. ספר השיחות תש\"נ ח\"ב ע' 538 הערה 75. ספר השיחות תשנ\"ב ח\"א ע' 40 הערה 32. ועוד.\nומשנת תשמ\"ז ואילך אמר כ\"ק אדמו\"ר כו\"כ פעמים, שבימינו אלו נסתיימה גם העבודה דצחצוח הכפתורים — ראה שיחת ש\"פ שמות תשמ\"ז (התוועדויות ח\"ב ע' 301). ד\"ה עבדים היינו וסד\"ה ונקדשתי — תשמ\"ח. ספר השיחות תשמ\"ח ח\"א ע' 355. ע' 365 הערה 81. ספר השיחות תנש\"א ח\"א ע' 138. ח\"ב ע' 595. ספר השיחות תשנ\"ב ח\"א ע' 163. ע' 173 ובהערה 66. ח\"ב ע' 350 ואילך. ועוד."],["421","51","הובא ונתבאר לרוב ע\"י כ\"ק אדמו\"ר — ראה לקוטי שיחות חלק כה ע' 481. חלק כט ע' 286. שיחת ה' טבת וי\"ב טבת תשמ\"ז (התוועדויות ח\"ב ע' 173. ע' 236 הערה 10). ספר השיחות תשמ\"ח ח\"א ע' 279. ספר השיחות תש\"נ ח\"ב ע' 538 הערה 75. ספר השיחות תשנ\"ב ח\"א ע' 40 הערה 32. ועוד.\nומשנת תשמ\"ז ואילך אמר כ\"ק אדמו\"ר כו\"כ פעמים, שבימינו אלו נסתיימה גם העבודה דצחצוח הכפתורים — ראה שיחת ש\"פ שמות תשמ\"ז (התוועדויות ח\"ב ע' 301). ד\"ה עבדים היינו וסד\"ה ונקדשתי — תשמ\"ח. ספר השיחות תשמ\"ח ח\"א ע' 355. ע' 365 הערה 81. ספר השיחות תנש\"א ח\"א ע' 138. ח\"ב ע' 595. ספר השיחות תשנ\"ב ח\"א ע' 163. ע' 173 ובהערה 66. ח\"ב ע' 350 ואילך. ועוד."]]],[4301600217,"התורה וועלן מיר קאָנען מקבל זיין דעם אור משיח ולזכות להיעוד ו\"הקיצו ורננו שוכני עפר\"<sup data-n=\"423\">52</sup> והוא בתוכם, וואָס באַ מיר איז אַ סאַך \"והוא\" — אַז דער זיידע דער רבי, דער טאַטע.\nט. ונמשך הדיבור דהשמחה היא כלי לההמשכה דשנה זו, ויועברו כל המניעות ועיכובים מיושבי רוסיא.\nדער אמת איז דאָך אַז כל התחלקות מדרי' וגבולים הם שייכים רק באור דממכ\"ע, אָבער באור הסובב איז דאָך ניט פאַראַן קיין התחלקות, איז לאָמיר גיין אַ ריקוד צוזאַמען מיט די רוסישע אידן. [כ\"ק אדמו\"ר רקד הרבה עם העולם].\nי. אמר לחיים, אַביסל משקה קאָן מעורר זיין אַ דבר טוב, מצד המשכה קאָן אפילו זיין אַ התעוררות בב' אופנים הפכיים. כמו בעת השמחה, מצד היין קאָן ער משפיע זיין אַ טוב ביותר, און עס קאָן זיין חלילה פאַרקערט אַ התגלות פון מדות רעות ח\"ו ווי מען האָט גערעדט. אין השגה גמורה איז דאָס שווער צו נעמען אָבער דער טעם איז וויילע סיבה אחת לשניהם. די סיבה איז די התעוררות, נאָר עס ווענדעט זיך אין וואָס די התעורות איז.\nאַ ריבוי גוטע ענינים און גילוי אלקות איז אַרויס געקומען פון חסידישע משקה. אַ חסידישער פאַרברענגען וואַשט אויס די וועלטיקע בלאָטע, טרייבט אַרויס די מדות רעות, מאַכט ריינער דעם גוף, און איז מעורר את נקודת הלב אַז עס איז זיך מתגלה דער נקודת היהדות, עס שאַיינט דער פּינטל איד. אַ סאַך בעלי תשובה האָט אַ חסידישע פאַרברענגען געמאַכט, אַ סאַך חסידים ואנשי מעשה בעבודה שבלב און מדות נעימות וערבות זיסע און געשמאַקע באמת, וואָרום דער יסוד החסידות והחסידים איז אהבת רעים, וואָס אַלע ליבן זיך צו איין זאַך לעבדו ית' בהג' עמודים דתורה תפלה ועבודת הבירורים בלב שלם.\nיא. אמר אחד שהזמן מאוחר לענין תפלת מנחה ויש רק כעשרים מינוטן. והשיב כ\"ק אדמו\"ר:\nעשרים מינוטן הוא הרבה, ויכולים לעשות תשובה עד שהזדונות נעשים כזכיות<sup data-n=\"424\">53</sup>. זדונות — דאָס ווילן מיר ניט, אָבער די זכיות ווילן מיר. און אין צוואַנציק מינוט קאָן מען תשובה טאָן.\nאחד הזכיר על אחד שיקח משקה. והשיב כ\"ק אדמו\"ר:\nער איז געזונט און וועט זיין געזונט אָבער מצד היוקר דנשמות, דבנים אתם לה' אלקיכם<sup data-n=\"425\">54</sup>, יוקר איז גאָר אַ אַנדער ענין, העכער פאַר אהבה חביבות. מצד היוקר איז אפי' כשיש לו כמה בנים מ\"מ כאו\"א יקר מאד<sup data-n=\"426\">55</sup>, אָט ווי אַ בן יחיד ממש, כמו\"כ בנשמות דבנים אתם כו', איז יעדער איינציילנער איד הוא יקר מאד<sup data-n=\"427\">56</sup>. לזאת איז אויף אַ צען טויזנטן ספק ווילט זיך אויך ניט, וצריכים זהירות והשי\"ת יחזק בריאותו בגו\"ר.\nיב. (דיבר<sup data-n=\"428\">57</sup> עוד הפעם בענין השו\"ב ואמר:)",[["423","52","ישעי' כו, יט."],["424","53","יומא פו, ב. תניא פ\"ז."],["425","54","ראה יד, א."],["426","55","להעיר מב\"ר פל\"ט, ט. פנ\"ה, ז. וראה סה\"מ תש\"א ע' 71."],["427","56","ראה גם ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 312. לקוטי שיחות ח\"ג ע' 982."],["428","57","סעיף זה י\"ל בפ\"ע כנ\"ל הערה 1."]]],[4301600218,"השו\"ב הוא מעמודי העולם, דאָס וואָס ער קיילעט איז דאָך צוליב להכשיר את הבשר, מאַכן כשר'ע פלייש, מאַכן פון נבילה וטריפה כשר'ע פלייש. אבר מן החי איז נבלה<sup data-n=\"429\">58</sup>, שארי קלקולי האברים בשחיטות<sup data-n=\"430\">59</sup> הם טריפה. וואָס דער שוחט בשחיטתו ובדיקתו כדין וכהלכה מאַכט כשר'ע פלייש. איז דאָס אַ גרויסע עבודה און אַ שווערע. וואָס בשר איז מעורר התגברות הדם<sup data-n=\"431\">60</sup>, און בכלל בשר איז ניט קיין גוטע זאַך, עס קאָן מעורר זיין גבורות. נאָר אַז ער מאַכט אַ ברכה על השחיטה, והבדיקה היא כהלכתה, איז ער דאָס מברר. לזאת, אַז דער שוחט גייט אויף להכשיר את הבשר דאַרף ער וויסן אַז ער איז פון די עמודי העולם.\nאַ רב, שוחט, מלמד, זיינען דאָך די ג' עמודי העולם און זיי רופט מען נטורי קרתא<sup data-n=\"432\">61</sup>. דאַרף דער שוחט זען וואָס טוט זיך אין די בתי מדרשים, ניט אין איין בית המדרש, נאָר אין די בתי מדרשים, מ'זאָל לערנען גמרא כו', וויסן וועגן חדרים, תלמוד תורות, ניט איין תלמוד תורה נאָר תלמוד תורות, ישיבות, וועגן טהרת המשפחה, אַ מקוה מי שצריך לילך, און ריידן וועגן דעם עם אלו שצריכים לידע, און שרייבן דורך צעטלען וכדומה. וואָס דאָס איז דאָך אין פלוג דעם רב'ס אַרבעט. איז דער אמת איז אַזוי, אַז דאָס איז דעם רב'ס אַרבעט, דער רב איז דער ראש העדה, ער איז די קאָפּ, אָבער אַ קאָפּ דאַרף האָבן אַ האַרץ און פיס. דער רב אויף וויפל ער זאָל זיין אַ גדול בתורה ויראת שמים, מוז ער האָבן העלפער, די שוחטים וכל העדה. דער רב דאַרף מיסד זיין חדרים, דאָס איז נוגע דעם רב. וכידוע<sup data-n=\"433\">62</sup> שבעל המחבר ספר דעת קדושים<sup data-n=\"434\">63</sup>, שהי' רב, ובעירו אם הי' מי עושה דבר לא טוב, הי' הוא עושה תשובה על זה, דהעיר נוגע להרב, וגם להשו\"ב.\n* * *\nוואָרום דער לימוד דאַרף זיין קמץ אלף אָ קמץ בית באָ. באָ איז דער טייטש: געקומען, דאס הייסט, דער גילוי אלקות. וואָרום אותיות זיינען כלים צו דעם גילוי אור התורה, וואָס דאָס איז חכמתו יתברך. אָבער ווען איז דאָס, אַז ער זאָגט דווקא קמץ אלף אָ קמץ בית באָ, אָבער אַז מען זאָגט ניט קמץ א כו', איז סוף כל סוף וועט דער קינד זיין, חס ושלום וחס וחלילה, אַ כופר באלקי ישראל חלילה<sup data-n=\"435\">64</sup>. אַז מען לערנט מיט אים קמץ אלף אָ קמץ בית באָ, וועט ער בלייבן אַ מאמין, וואָס אין די גילוים זאָל מיט אים ניט זיין, וועט ער בלייבן אַ מאמין באמונה שלמה. דאָס",[["429","58","תוספתא חולין ספ\"ז (עיי\"ש במפרשים). בשר מן החי — הוא טריפה (חולין קב, ב). — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["430","59","לשון הרושם — וצע\"ק הכוונה. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["431","60","עיין לקו\"ת הנ\"ל [הערה 44]. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["432","61","ראה ירושלמי חגיגה פ\"א ה\"ז. — הערת כ\"ק אדמו\"ר (כנ\"ל הערה 1)."],["433","62","ראה גם אגרות­קודש ח\"ג ע' תסה בשוה\"ג."],["434","63","הרה\"ג וכו' הר\"ר אברהם דוד וואהרמאן מבוטשאטש (ו' אדר תקל\"א — ער\"ח מרחשון תר\"א). ראה אודותו — ספר דור דעה (לרי\"א קאמעלהאר) ח\"ב ע' קצט ואילך. קובץ יגדיל תורה ניו יארק שנה ז חוברת נ ע' יג ואילך."],["435","64","ראה גם סה\"מ תרפ\"ז ע' ר. תרפ\"ט ע' 116. ספר השיחות תר\"פ­תרפ\"ז ע' 39. לקמן ע' 127. ע' 159. ע' 178­177. ע' 206. ספר השיחות תש\"א ע' 88. אגרות­קודש ח\"ב ע' תצ ואילך. ח\"ז ע' קמב ואילך. ועוד."]]],[4301600219,"הייסט, כאָטש מצד הגילוים וועט ער זיין שלא כדבעי, אָבער אַ מאמין באלקי ישראל וועט ער בלייבן.\n* * *\n(ואמר למלמד א'):\nער זאָל לערנען מיט די קינדער, אַז זיי זאָלן וויסן אַז דאָס איז אותיות שבהם ניתנה התורה<sup data-n=\"435\">64</sup>. דאָס הייסט דאָס איז די אותיות פון די עשרת הדברות, ניט פון די עשרה מאמרות, און מיט דעם וועסטו אים מאַכן פאַר אַ מאמין באלקי ישראל.\nוואָס אַ שוחט איז אַן עמוד וואָס דאַרף מאַכן חדרים, תלמוד תורות, ישיבות וכדומה, ואם יש מניעות ועיכובים, כמו ההגבלות זמנים דזמני השחיטה, פשוט צריכים השובי\"ם לעשות בקשה כו', כי צריכים זמן על קבלת עול מלכות שמים, או באופן אחר. אָבער די זאַך דאַרף שטאַרק אַרן.\n* * *\nואז מחשבה טובה הקב\"ה מצרפה למעשה<sup data-n=\"437\">65</sup>. דהפירוש \"מצרפה\" ער לייטערט זי אויס שתהי' מאירה גם במעשה הטוב. והוא כמו שלפעמים א' קם בבקר ואומר מודה אני וברכות השחר ומחליט במחשבתו להתעסק בתורה ותפלה, והולך לבית המדרש להתפלל, און אַז ער גייט אַרויס אויפן גאַס, איז עפּעס ניט אַזוי ווי פריער, עס איז עפּעס פאַרכמאַרעט<sup data-n=\"438\">66</sup>. דאָס איז במחשבה. און נאָכדעם קומט אַראָפּ בדיבור, היינו, עס באַגעגנט אים אַ צווייטער און פרעגט אים: וואָס איז דיר, זעסט אויס אַזוי פאַרכמאַרעט, איז שוין אַ דיבור אויך. איז כאָטש די החלטה איז געווען לטוב אָבער די מחשבה ודיבור איז שוין אַזוי. ויש עוד אחד שמחליט לפועל, ואחר כך יוצא לחוץ זעט ער אַלץ אַזוי לעבעדיק, ובא אצלו ההחלטה בפועל טוב.\n* * *\nיג. אמר שינגנו וירקדו וישחקו הנערים, אַז מען זאָל ווערן אַ טפח<sup data-n=\"439\">67</sup> העכער פון דער ערד.\nושאל אחד איך הוא?\nוהשיב כ\"ק אדמו\"ר: ע\"י עבודה כמו בהנחת תפילין וכדומה, לחכות על קיום המצוות, אתרוג לקום בבוקר בהשכמה, והיינו ע\"י עבודה בפועל נעשים טפח העכער.\nושאל השואל האם ע\"י זה נעשים אַ טפח העכער הלא אין מרגישים את זה?\nוהשיב: ישנם ענינים שבאים בהרגש אח\"כ, לא בעת שרוצה להרגיש, רק שנרגש ממילא אח\"כ.\nושאל הנ\"ל שצריכים לבטל הרצון וא\"כ איז ער ניטאָ.\nוהשיב: דער ענין וואָס ער איז ניטאָ דערהערט דאָס ניט די פלייש. הגוף לכשנזדכך דערהערט ער אַז דער עיקר איז אלקות, אָבער ער בלייבט במציאות של בשר, ואדרבה הוא חי מזה.\nפאַראַן דער ענין פון \"כלתה נפשי\"<sup data-n=\"440\">68</sup> און פאַראַן דער ענין פון \"כלה שארי ולבבי\"<sup data-n=\"441\">69</sup>. דאָס איז צוויי מדריגות",[["435","64","ראה גם סה\"מ תרפ\"ז ע' ר. תרפ\"ט ע' 116. ספר השיחות תר\"פ­תרפ\"ז ע' 39. לקמן ע' 127. ע' 159. ע' 178­177. ע' 206. ספר השיחות תש\"א ע' 88. אגרות­קודש ח\"ב ע' תצ ואילך. ח\"ז ע' קמב ואילך. ועוד."],["437","65","קידושין מ, א."],["438","66","עצוב."],["439","67","ראה לעיל ע' 13 הערה 14."],["440","68","תהלים פד, ג."],["441","69","שם עג, כו."]]],[4301600220,"עבודה: \"כלתה נפשי\" איז מצד הנפש; \"כלה שארי ולבבי\" איז מצד הגוף, אַז דער גוף ווערט נזדכך כל כך, ואז המזונות שלו מה שהוא ניזון הוא ברוחניות.\nע\"ד ווי דער טאַטע זאָגט<sup data-n=\"442\">70</sup> אויף דעם זיידן הרה\"ק ר' נחום מטשערנאביל זצוק\"ל זי\"ע<sup data-n=\"443\">71</sup> שהי' שמן בגופו מעניית אמן יהא שמי' רבא. ודבר זה נתחדש בתורתו של מורנו הבעש\"ט נ\"ע על ידי עבודה פנימית דוקא. דמענין השגה יהי' מזה הצהבת פנים הוא דבר פשוט, וכמא'<sup data-n=\"444\">72</sup> צהבו פניו של ר\"א שמצא תוספתא חדתא דער געשמאַק פון שכל מאַכט אַ הייליקן ליכטיקן פנים. והוא דוקא מי שמתעסק בשכל אלקי, בחכמת התורה, כי להבדיל השכל דקליפה איז ניט קיין שכל באמת, דאָס איז נאָר וראיתי איש חכם בעיניו<sup data-n=\"445\">73</sup>, אָבער באמת איז גאָר קיין חכם ניט. אָבער אין חכ' דקדושה איז פון דעם נייעס פון דער השגה ווערט אַ צהיבת פנים, אַז דער פנים איז אַ אַנדערער.\nאָבער דאָס איז נאָר לפי שעה, אבל שתהי' ניזון מזה ממש, כמו שניזון מאכילה ושתי', את זה פעל מורנו הבעש\"ט נ\"ע בתורתו ועבודתו, והיינו שע\"י עבודה פנימית ווערט קענטיק אין פנים, ווי פון אַ גוטן וואַרמעס. און מען דאַרף לכה\"פ אין זמנים ידועים שטייען אַ טפח העכער פון דער ערד.\nושאל עוה\"פ: איך נעשים בטפח גבוה.\nוהשיב: אַז מען דאַרף צופיל ניט סקראָבן די דייזע<sup data-n=\"446\">74</sup>. מען דאַרף סקראָבן וויפל מען דאַרף יעמאָלט איז גוט פאַר די דייזע און פאַר די טייג. אָבער צופיל סקראָבן טויג ניט. יעמאָלט סקראָבעט מען אָפּ די דייזע אויך.\nיד. (ואח\"כ אמר להרי\"פ<sup data-n=\"447\">75</sup>:) אַז מען זעט אַ אידן דאַרף מען עם זאָגן ביסט אַ איד. וועט ער ענטפערן יע, און דאָס קען אויך אַרויס טראָגן דעם נקודת תוכיות לבו לחוץ, מער פאַר אַלע אַנדערע ענינים פון ביטול.\nדאָס וואָס מען דערמאָנט אים אַז ער איז אַ איד, וועקט מען דאָס אויף די נקודה וואָס אין טיפן האַרצן איז פאַרשלאָסן.\nדער אמת איז אַז יענעמ'ס לא טוב, דאַרף זייער דער נעמען און וויי טאָן מיט אַ אמת<sup data-n=\"375\">6</sup>, אָבער אויף דעם עצם לא טוב דאַרף מען ניט קוקן און ניט אָנזען, אויף זיך אַליין איז אַנדערש, זיך דאַרף מען טאַקע מחייב זיין אין אַלץ, אויפזוכן לא טוב אפילו דעם דקות שבדקות לא טוב, און זיין פון דעם צובראָכן, פתות",[["442","70","סה\"מ תרע\"ח ע' קצט. סה\"מ תש\"ב ע' 79. לקמן ע' 166. \"היום היום\" טו תמוז. לקוטי שיחות ח\"א ע' 33. וראה גם אור תורה להרב המגיד כא, סע\"א. סה\"מ תרס\"ט ע' נ."],["443","71","אמו של רבינו הרבנית הצדקנית מרת שטערנא שרה היתה בת הרה\"ק ר' יוסף יצחק (בן כ\"ק אדמו\"ר הצ\"צ) והרבנית מרת חנה, בת הרה\"ק ר' יעקב ישראל מטשערקאס, בן הרה\"ק ר' מרדכי מטשערנאביל, בן הרה\"ק ר' מנחם נחום מטשערנאביל (ראה אגרות­קודש ח\"ב ע' כו). נסתלק יא מרחשון תקנ\"ח (אגרות­קודש ח\"ד ע' תסו)."],["444","72","ראה ירושלמי שבת פ\"ח ה\"א. קה\"ר פ\"ח, א (ד). לקו\"ת צו ט, א. מסעי צג, ב. סה\"מ תרח\"ץ ע' נט. ובכ\"מ."],["445","73","ע\"פ משלי כו, יג."],["446","74","מלוש (קנעט­מאשין)."],["447","75","הר\"ר יחזקאל פייגין. משנת תרפ\"ז ואילך מזכירו של רבינו. — ראה אודותו: ספר השיחות תר\"פ­תרפ\"ז ע' 51 הערה 1."],["375","6","ראה גם אגרות­קודש ח\"ה ס\"ע קא ואילך (הועתק ב\"היום יום\" יב כסלו)."]]],[4301600221,"אותה פתים<sup data-n=\"449\">76</sup>, להיות נבזה בעיני עצמו נמאס. נאָר דאָס איז אַלץ אויף זיך, אָבער אויף דעם זולת לא טוב, דאַרף מען ניט אָנזען. מ\"מ איז אפילו אויף זיך טאָר מען אויך ניט מעורר זיין קיין דינים חלילה, און אויף דעם אַנדערן מכש\"כ, וואָרום כללות הרע וואָס ער נעמט אַרום דעם טוב הוא עד\"מ ווי אַ בריליאַנט וואָס איז אַרום געוואָקסן מיט ווילדע שטיינער, דכך הוא דרך גידולו, און דערפאַר דאַרף מען אים שלייפן, וואָס מיט דעם שלייפן נעמט מען אַראָפּ די אַרום געוואקסענע.\nדאַרף אָבער דאָס אויך זיין מיט אַ סדר, און דער עיקר דאַרף מען טאָן מיט אור דערלייכטן, ווי עס איז ידוע בענין חנות של בושם וחנות של בורסקי<sup data-n=\"450\">77</sup>, דאַרף מען מיט דעם אור דערלייכטן, ועל הזולת צריכים לראות רק בטוב עין, איז מדות לא טובות דאַרף דאָך ניט זיין, דאָס איז דאָך רע ווי בשר חזיר.\nואמר אחד: אויף היגע לשון הייסט דאָס אויסגעשלאָסן.\nוהשיב כ\"ק אדמו\"ר: מען דאַרף ריידן אויף אונזער לשון, ניט קיין היגע לשון און ניט קיין דייטש, נאָר אונזער לשון, וכמאמר<sup data-n=\"451\">78</sup> שלא שינו שמם לשונם ולבושם. איז מדות לא טובות דאַרף ניט זיין.\nטו. אין דעם יאָר איז די כלי צו דער המשכה של הכתיבה טובה בשנה טובה ומתוקה דר\"ה, און חתימה טובה דיוהכ\"פ און גמר חתימה טובה דהו\"ר, איז דא דער כלי דערצו נאָר דער קו השמחה, דעיקרה בחג הסוכות, וואָס דער אויבערשטער זאָל העלפן אַז [דורך] די שמחה פון שמחת תורה זאָל אַראָפּקומען דער גוטער יאָר וואָס איז נקצב געוואָרן בר\"ה יו\"כ כו', אין אַ טוב ממש. אַ טוב נראה ונגלה בחסד וברחמים און זאָל אַראָפּגענומען ווערן אַלע מניעות ועיכובים אויף תורה ופרנסה און געזונט. אַלע אידן זאָלן זיין געזונט. אַז באַ אידן זאָל ניט זיין קיין געלד אויף קיין חולאת חלילה, נאָר אויף גמ\"ח צדקה און תורה.\nושאל אחד: הלא יש מקומות שיש מניעה ועיכוב על לימוד התורה.\nוהשיב: מניעות ועיכובים דאָס איז אַלעמאָל דאָ, דאָס איז עבודת הבירור דגלות, און אַזוי איז דער סדר העבודה פון גלות (יחיש הקב\"ה גאולתינו) ביז משיח'ן, נאָר דעם יאָר איז די כלי צו דער המשכה, איז נאָר קו השמחה און מיט דעם וועט מען אַראָפּנעמען די מניעות ועיכובים, און מען דאַרף דאָס מפרסם זיין.\nמען האָט געדאַרפט אין דעם יאָר זען זיך מיט די רוסישע אידן יחיו, איך מיין ניט וואָס מען קומט אַהער, וויפל קאָנען",[["449","76","ע\"פ ויקרא ב, ו."],["450","77","ראה מדרש משלי פרשה יג: הולך את חכמים יחכם ורוע כסילים ירוע. משל למי שנכנס לחנותו של בשם אע\"פ שאינו מוכר לו ואינו לוקח ממנו הוא יוצא וריחו וריח בגדיו מבושמין ואין ריחו זז ממנו כל היום, עליו הוא אומר הולך את חכמים יחכם. ורועה כסילים ירוע, משל לאחד שנכנס לחנותו של בורסקי אע\"פ שאינו מוכר לו ואינו לוקח ממנו הוא יוצא וריחו וריח בגדיו מלוכלכין, ואין ריחו וריח בגדיו זז ממנו כל היום, ועליו הוא אומר ורועה כסילים ירוע."],["451","78","שמם ולשונם — שמו\"ר פ\"א, כח. ויק\"ר פל\"ב, ה. לבושם — מדרש לקח טוב וארא ו, ו. תבוא כו, ה. וראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א חט\"ו ע' קיח. תורה שלימה שמות מילואים ע' רלט. וארא מילואים ע' קטז."]]],[4301600222,"קומען פופציק הונדערט, ניט דאָס הייסט זען זיך מיט זיי, נאָר עס זאָל אַראָפּ די הגבלות און די עלילות פון לומדי תורה, עס זאָל זיך באַווייזן דער אמת.\nמיר זיינען ניט קיין פּאָליטיקער, פּאָליטיק דאָס איז ניט אונזער עסק, אונזער עסק איז נאָר מלכות שמים.\nדער באַרדיטשעווער רב הר\"ר לוי יצחק זצוק\"ל נ\"ע הי' מתפלל מוסף בר\"ה לפני העמוד, וקודם שהתחיל הקדיש אמר<sup data-n=\"452\">79</sup>: דער פּרייסישער קייסער זאָגט איך בין קייסער, דער רוסישער קייסער זאָגט איך בין קייסער, וכדומה, און איך לוי יצחק בן שרה זאָג, יתגדל ויתקדש שמי' רבא כו'.\nאונז איז נוגע נאָר מלכות שמים אָן גרענעצן. זאָל דער אויבערשטער ב\"ה העלפן מען זאָל זיין צוזאַמען בשמחה ובטוב לבב, דעם יאָר איז די כלי דער קו השמחה, און מיט דעם וועט מען אַראָפּנעמען די מניעות ועיכובים, און אין שמחה איז פאַראַן אַ מעלה לגבי מרירות, דבמרירות הוא עדיין מסופק אם ימולא בקשתו, ובשמחה הוא בטוח שכן יהי'.\nטז. אין דעם ניגון \"קול דודי דופק\"<sup data-n=\"453\">80</sup> איז דער רבי — אדמו\"ר הזקן — מנקה — סקראָבעט — אַ נשמה, ער נעמט אַראָפּ אַ סירכא<sup data-n=\"454\">81</sup>.\nפון דער לעצטער תנועה איז קענטיק, אָט אַזוי ווי מען זאָגט, זעסט איך בין גערעכט. הוד כ\"ק אדמו\"ר האמצעי האָט געזאָגט, אַז דער טאַטע — אדמו\"ר הזקן — האָט געקענט אַריינקריכן בקרבו של חסיד און אַרויסרייסן וואָס טויג ניט, מיט חסידות אָדער מיט אַ ניגון. און דער ניגון (קול דודי) — מאָנט.\nער — הכוונה על החסיד — זאָגט, וואָס האָסטו צו מיר — כסוס שאינו רוצה לילך וכשרוצים להנהיגו שטעלט ער זיך אויף די פאָרנסטע פיס —\nזאָגט מען אים אין דעם ניגון אַזוי: דער ערשטער פאַל — הוי' אלקים אמת הוא אלקים חיים<sup data-n=\"455\">82</sup>, ואמת ה' לעולם<sup data-n=\"456\">83</sup>. דער צווייטער פאַל: למה ירדה הנשמה בגוף, דער ווייטערדיקער המשך — ווייל נתאוה הקב\"ה להיות לו דירה בתחתונים. דער דריטער פאַל איז, וואָס נשמות זאָגן, אַז די כוונה פירט זיך אויס נאָר דורך אונז, דער ווייטערדיקער המשך איז, דער הרגש המקבל אין דער המשכה.\nכ\"ק אדמו\"ר צוה לנגן ניגון זה כמה פעמים ובכל פעם ביאר הכוונה של הניגון ע\"ד הנ\"ל, רק בתיבות שונות, וצוה לתפוס הניגון היטב עם הענין הפנימי שבו, ולנגנו בזמני התוועדות אנ\"ש ויפעול הרבה.\nיז. (אח\"כ המשיך הדיבור בענין יושבי אהל:) דער וואָס איז אין דער קו פון יושב אוהל, זאָל מיט קיין אַנדערע ענינים ניט פאַרנעמען זיך, עס ווילט זיך זיי עסק, אָבער דאָס זאָלן זיי גאָרניט טראַכטן, והיא לא תצלח, זיי וועלן אין דעם גאָר ניט מאַכן.",[["452","79","ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 29."],["453","80","מעשרת הניגונים של כ\"ק אדמו\"ר הזקן. וראה תוי הניגון בספר הניגונים חלק א ניגון כו (ע' 20­19)."],["454","81","ע\"ד \"סירכות הריאה\" ברוחניות — ראה לקו\"ת דרושים לר\"ה סב, ב. סה\"מ תרח\"ץ ע' רפד. וראה גם ספר השיחות תורת שלום ע' 136. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 310. קיץ ה'ש\"ת ע' 84. תש\"ה ע' 119."],["455","82","ירמי' י, י."],["456","83","תהלים קיז, ב."]]],[4301600223,"איך וויל ניט זאָגן דעם ניט, איך וויל נאָר אַז עס זאָל זיין גוט, אָבער עס איז אַזוי. און לבד זה וואָס ער דאַרף זיין אַ יושב אוהל, דאַרף ער ניט זיין אַ יושב אוהל נאָר פאַר זיך ווייל ער זאַלעוועט דעם זמן, נאָר ער דאַרף לערנען מיט דעם זולת, קובע שיעורים זיין.\nאַ איש פשוט ער לויפט אַריין אין שול, די וואַסער איז פון פאָרנט, ער טוט אַ וואַש געכער די הענט און דאַוונט מנחה, בין מנחה למעריב הערט ער אַ שיעור גמרא, דער וואָס איז ניט שייך צו גמרא, איז משניות עין יעקב, און קומט אַ היים נאָך מעריב, דערציילט ער אַ מעשה פון ר' עקיבא, פון ר' אליעזר איז דאָס פועל'ט אַ ליכטיקייט אין שטוב. אַ יושב אוהל דאַרף להאיר אור, אָט אַזוי דאַרף ער זיין כמו אַ כהן, אַז ער גייט אין גאַס ווייס ער אַז ער איז אַ כהן.\nכמו\"כ דער יושב אהל דאַרף וויסן אַז ער איז אַ יושב אהל, אַזוי דאַרף ער זיין, ווי דער וואָס גייט צינדען די לאָמפּן אין די גאַסן איז גרויסט ער זיך ניט מיט דעם, דאָס איז דאָך זיין אַרבעט, ער דאַרף אַרום גיין מיט אַ לאַנגן שטעקן אָפּ דרייען די קרענטלעך פון די לאָמפּן עס זאָל ליכטיק ווערן<sup data-n=\"457\">84</sup>. אַזוי איז אַ יושב אהל, ער דאַרף גאָר צו דעם קיינע הכנות כ\"א יאיר ממילא. כמו שמכניסין נר לבית שאין צריכים לחשוב שיאיר הנר. כן השמש, שמאיר ממילא. וכן היושב אהל צריך להאיר אור זה בלבד, אלא שהוא כמשל ההולך להדליק את המנורות, דפעולתו רק בענין הברכה<sup data-n=\"458\">85</sup>, לגלות ולהמשיך ממה שישנו בהעלם כבר, ורק מה שיש עליו דבר המונע והוא מסיר את המונע והאור נגלה ומאיר, אבל צריכים להמשיך המשכה חדשה ממקורה ושרשה כענין יהי רצון<sup data-n=\"458\">85</sup> לשנות כו' לרפאות כו'.\nיח. הייתי רוצה להעמיד בית דין של כ\"ג לאמר לחיים יחד, ונחליט ונפסק הלכה פסוקה כי ההמשכה טובה דשנה זו, שנמשכה בכתיבה דר\"ה בשנה טובה ומתוקה, וחתימה דיוהכ\"פ וגמר חתימה טובה דהוש\"ר<sup data-n=\"460\">86</sup> יומשך למטה בטוב הנראה והנגלה בלי שום מונע ומעכב, ובקרוב. והב\"ד יקבלו ע\"ע לעשות כלים טהורים נעימים ועריבים לאלקות בעבודתם, וב\"ד זה יהי' דינא דאיהו רחמי<sup data-n=\"461\">87</sup>, ברשות התורה ובכח התורה, דבעבודה דשנה זו הכלי אל ההמשכה הוא בקו של שמחה אשר בעזרתו ית' יהי' אַ סאַך צו טאָן געשמאַקע עבודות, וצריכים לזה התאחדות והתקשרות. וכמו א' כשקם משנתו ונוטל ידיו טוט ער אַ רייב דעם שטערן וואָס איז דאָס, דאָס איז ער כאַפּט זיך אַז ער האָט אַ קאָפּ, דאָס הייסט דער חיות כללי. אַזוי דאַרף יעדער זיין מקושר אל הראש, להתאחד ולהתקשר כו'.\nכ\"ק אדמו\"ר אמר לרי\"פ: דאָס איז דיין אַרבעט שרייבן אין אַלע שטעטלעך עס זאָל זיין בכל מקום משפיעים.\nושאל הרי\"פ, האם הכוונה שבכל מקום צריכים למצוא במקום ההוא מי שיש ביכולתו להיות משפיע?\nוהשיב: כן, ועי\"ז יהי' מתאחדים ומתקשרים בהראש.",[["457","84","להעיר מספר השיחות תש\"א ע' 136. שיחת יב תמוז תשכ\"ב."],["458","85","ראה ד\"ה אריב\"ל בסה\"מ תרכ\"ט בתחילתו. ובכ\"מ."],["458","85","ראה ד\"ה אריב\"ל בסה\"מ תרכ\"ט בתחילתו. ובכ\"מ."],["460","86","ראה זח\"ג לב, א. אור החמה לזח\"א רכ, א. ועוד."],["461","87","ראה תקו\"ז בהקדמה (יז, ב)."]]],[4301600224,"ושאל הרי\"פ אם הכוונה לפי שהמשפיע יותר קרוב אל הראש (והי' נראה כהסכם מכ\"ק).\nואמר כ\"ק אדמו\"ר: אַז דער עיקר איז דער דור דעכשיו שהוא עקבתא דמשיחא ממש — איז דער עיקר דער דור, ווייל די עקביים איז דער עיקר הקיום. נאָר אין די עקביים קלייבט זיך פסולת מזיעה וזוהמה כו', דערפאַר איז איצט די התגברות פון רע, לזאת דאַרף מען איצט מאיר אור זיין וועט דער רע נדחה ווערן עס זאָל זיין כמו בתחלת הבריאה דכחו לברוא רע, איז דאָך רע אויך אַ בריאה, נאָר מקומו איז געווען בתחתית הארץ<sup data-n=\"462\">88</sup> וע\"י העבודה פנימית לוקחים ומבררים ניצוצי הטוב הנבלע בהם. דער עיקר איז דער דור פון עקבות משיחא.\nגיין אויפן קאָפּ איז ניט קיין סדר, מען דאַרף גיין אויף די פיס דאָס איז דער מעמיד הגוף, און כמו\"כ איז דער מעמד כללי פון די שית אלפי שני דהוה עלמא, איז עקבות משיחא אַ עיקר. משה רבינו האָט געזאָגט די מלאכים<sup data-n=\"463\">89</sup> כלום יצה\"ר יש בכם, אבל לא אמר להם התגברו על היצה\"ר, ודור דעקבות משיחא בהם הוא התגברות על היצה\"ר איז דאָס דער עיקר הכוונה.\nדי כוונה פירט זיך ניט אויס מיט עתיק דאצילות ברדל\"א, נאָר ווי עתיק דאצילות נעשה כתר ועתיק לבי\"ע, איז דאַרף מען זיין מאורי אור.\nוזהו העבודה דיושבי אהל, אשר בהם צריך להיות עבודה פנימי', ליגן אין אַ ענין ביז ער וועט אים קלאָר ווערן אַז דער ענין וועט זיין ברור אצלו, און ער זאָל דאָס דערציילן ווי איינער דערציילט אַ ענין גשמי וואָס איז קלאָר ביי אים, עד שמתעצם הענין אצלו והוא חי בזה.\nוזהו העבודה דיושבי אהל, טאָן אין אַ ענין, אין אַ שטיקל תניא, אַ שטיקל תורה אור, וויפל דאָס איז, צען שורות סליק ענינא. תניא און תורה אור איז במקום יחידות, דער וואָס גייט ניט אויף יחידות זאָל ער זיך צוטראָגן צו אַ שטיקל תניא, תורה אור. דאָס (תניא ותורה אור) איז געבליבן ווי דער עצמי איז. אין לקו\"ת איז שייך השגה והעיון שמביא הוא להשיג הענין בהרחב ובהסבר יותר. אבל תניא ותורה אור איז געבליבן ווי דער עצמי. באגה\"ק<sup data-n=\"464\">90</sup> איתא דהלוחות היו כולו פנים. ולוחות האחרונות עם שהיו ג\"כ בבחי' פנים אבל אין זה כמו לוחות הראשונות<sup data-n=\"465\">91</sup>. דבענין החסידות הוא תניא ותורה אור כענין לוחות הראשונות. און דאָס פועל'ט ווי יחידות, וכמו שאמר לי [...] אַז אַזאַ וואָס אים איז שווער צו גיין אויף יחידות, מאיזה סיבה שתהי', איז תניא ותורה אור במקום יחידות, דאַרף ער ליגן אין דעם.\nשאל אחד, זה שתניא ותו\"א הם במקום יחידות הוא רק בעניני עבודה אבל לא בהנוגע לענין התיקונים?",[["462","88","ראה לקוטי תורה להאריז\"ל בראשית (ד\"ה ונבאר מעלת אדה\"ר). סה\"מ תרנ\"ט ע' קעו (ועם הוספות ושינויים — סה\"מ תש\"ד ע' 139 ואילך). עטר\"ת ע' תטו (ועם הוספות ושינויים — סה\"מ תרפ\"ו ע' רכח). לקוטי שיחות חכ\"ה ע' 429 הערה 52. ועוד."],["463","89","שבת פט, א."],["464","90","קונטרס אחרון ד\"ה דוד זמירות קרית להו (קסא, א). וראה מקומות שצויינו בהערה הבאה."],["465","91","ראה הגהות כ\"ק אדמו\"ר מהורש\"ב נ\"ע לד\"ה פתח אליהו שבתו\"א — תרנ\"ח (ס\"ע ב ואילך בשוה\"ג). סה\"מ תרנ\"ג ע' קפא ואילך. שם ע' רלו. המשך תרס\"ו ע' פז. סה\"מ תרפ\"ו ע' קפט. סה\"מ תרפ\"ט ע' 57 ואילך. ועוד."]]],[4301600225,"והשיב: ודאי כן, דבענין התיקונים הוא אַ ריצעפּט, וואָס אפילו די עניני התיקונים וואָס שטייען איז דאָך אויך ניט אַלעמען גלייך, דאָס דאַרף מען נאָר אויף יחידות.\nיט. דרושי דא\"ח הנאמרים בארוכה צ\"ל כן מצד האומר, אבל מצד המקבלים שאין ביכלתם לקבל [...] בדרושי כ\"ק אאמו\"ר הרה\"ק זי\"ע ישנם חילוקים<sup data-n=\"466\">92</sup>, עד רס\"ה בארוכה, מרס\"ה בקצרה, ואח\"כ ברס\"ו עוד יותר בקצרה, רק שהדרושים המה שבעים, זאַטע, דרושים מיט ריבוי אור, אבל לא באריכות כ\"כ.\nושאל אחד: אם הכוונה נאָר אין עבודה אָבער לערנען דאַרף מען אַלץ.\nוהשיב: כן. דער וואָס קאָן טאָן ממש אַלעס דאָס איז שוין אַ מתנה מלמעלה. ישנם כאלו וואָס האָבן אַ געזונטע גלגלת, דאָס הייסט ניט אין מוחין, נאָר אין גלגלת קען ער מקיף זיין אַ ענין, און ער וועט אַרויף קומען אויף דעם.\nכ. צריכים להשתדל בכל עיר ועיר, אַז די שולן זאָלן זיין אָפן כ\"ד שעות היום, די שולן דאַרפן קיינמאָל ניט זיין פאַרשלאָסן. אַ איד גייט אַריין אָנוואַרעמען זיך. און אַ גבאי וואָס לאָזט ניט האַלטן אָפן די שול, דאַרף מען אים אַראָפּוואַרפן, נאָר אָן מחלוקת, מחלוקת דאַרף ניט זיין. אָבער מען דאַרף זען אַז די שול זאָל זיין אָפן כ\"ד שעות היום. דאָס איז אַ דין, אָט אַזוי דאַרף זיין. אַ איד אַז ער דאַרף זיך אָנוואַרעמען, גייט ער אַריין אין שול וואַרעמט ער זיך אָן מיט אַ שטיקל מדרש. מיט אַ מדרש וואַרעמט זיך אָן אַ איד.\nמען זאָל מכריז זיין בכל מקום ומקום, אַז וואו נאָר עס איז דאָ אַ חסידישער מנין, זאָל ער זיין אָפן גאַנצע כ\"ד שעות.\nאויף די חסידישע מנינים בין איך דאָך דעם טאַטנס אַ זון, איך בין דאָך ניט קיין בעל דעה אויף אַלעמען, אָבער ביי חסידים בין איך דאָך דעם טאַטנס אַ קינד. איז אַלע חסידישע שולן דאַרפן זיין אָפן אַלע כ\"ד שעות היום<sup data-n=\"467\">93</sup>.\nשאל אחד: איך אפשר גם בלילה.\nוהשיב: אין כוונתי להניח הפקר ח\"ו, וצריכים לסגור על זמן השינה, ואם ישן בבית הכנסת איז נאָך בעסער<sup data-n=\"467\">93</sup>. און מ'זאָל מאַכן אז איינער זאָל זיך געפינען אין שול זיצן און לערנען וועט ער במילא היטן די שול. וואָרום אַ שול דאַרף זיין אָפן אַ גאַנצן טאָג, און דאָס דאַרף זיין ווי אַ דין פון שולחן­ערוך, כמו בענין עמידת העמוד שצריך להיות מימין הארון<sup data-n=\"469\">94</sup>, בריחוק קצת לאמצע החדר, נגד שלחן­הקריאה, אזוי דאַרף זיין דאָס וואָס די שול דאַרף זיין אָפן, אַז יעדער איד זאָל קומען דאַוונען און לערנען.\nכא. אחד הזכיר על דבר משקה שיקח מצד הפקודה, ווייל מיר לעבן אויף פקודות.\nואמר כ\"ק אדמו\"ר: די וואַרשעווער פאַרשטייען ניט קיין דיסציפּלין<sup data-n=\"470\">95</sup>. זיי",[["466","92","אולי הכוונה לאופן אמירתם. ע\"ד מאמרי כ\"ק אדמו\"ר מהורש\"ב נ\"ע — ראה גם לקמן ע' 96 ואילך."],["467","93","ראה גם לקמן ע' 61. ספר השיחות תר\"פ­תרפ\"ז ע' 38."],["467","93","ראה גם לקמן ע' 61. ספר השיחות תר\"פ­תרפ\"ז ע' 38."],["469","94","ראה הלכות בית הכנסת בהוספות לספר שער הכולל (להרא\"ד לאוואוט). ולהעיר משו\"ע אדה\"ז או\"ח סקל\"א ס\"א: והש\"ץ העומד מימין הארון."],["470","95","משמעת, ציות."]]],[4301600226,"ווייסן יע דיסציפּלין, נאָר עפ\"י השכל. אין ליובאַווויטש איז געווען פקודות, און די וואָס האָבן זיך געהאָדעוועט אויף פקודות זיינען ווי אַ קאָזאַק.\nאַ קאָזאַק בעת ער זעצט זיך אויף דעם פערד, יעמולט איז ער און דער פערד מיט דער פיקע<sup data-n=\"471\">96</sup> איין זאַך.\nאַזוי די וואָס האָבן זיך געהאָדעוועט אין ליובאַוויטש, איז די אותיות התורה — דאותיות התורה הם הסוסים — והלב, כמשל די פיקע, מיט דעם מוח (דער השגה) — איין זאַך.\nושאל אחד: א\"כ המוח בהמשל הוא הקאָזאַק.\nוהשיב: כן. המוח כשיש לו לב ואותיות התורה איז ער אַ קאָזאַק.\nושאל אחד: מפני מה הלב נמשל לפיקע.\nוהשיב: לפי שהלב מביא אל הפועל.\nכב. אח\"כ שאל אחד: מאחר דבשנה זו העיקר (הכלי) הוא קו השמחה, א\"כ יהי' עבודה בנקל יותר.\nואמר כ\"ק אדמו\"ר: באַ יושבי אהל איז ניטאָ קיין גרינג, מיר ווייסן ניט פון גרינג, מיר ווייסן נאָר פון שווער. נאָר עס איז זיס, אַ זיסע עבודה (חסר קצת), אַ זיסע עבודה, זיס אָבער שווער.\nאַ בעל עסק האָט דאָך גרינגע עבודות, ער שטייט אויף אינדערפרי און לויפט דאַוונען, ער זאָגט טאַקע גיך, אָבער ער האָט זיין עבודה, ער לויפט אין גאַס, באַגעגנט עם איינער און בעט ביי אים אַ גמילת­חסד, אַ פינף­און­צוואַנציקער. ענטפערט ער: אויב אויף אַ טאָג צוויי, גיב איך דיר. און נעמט אַרויס און גיט גלייך.\nוואָס אַ יושב אהל איז ניט דאָס זיינע עבודות.\n— ער דאַרף אויך לייען אַ גמ\"ח והדומה, אבל לא זהו עבודתו כלל —\nאון ער דאַרף האָרעווען שווער ווי דער סדר היום איז, ברכות השחר דאַרף ער ניט זאָגן במהירות נאָר במתינות, און הערן פירוש המילות, און הכוונה פון כובד ראש קודם התפלה<sup data-n=\"472\">97</sup>, או בעת התפלה.\nוואָס באַ אַ יושב אהל איז ניטאָ קיין גרינגע, וויילע מיר זיינען דאָך פראָנטאָוויקעס ווי נא שטאכי\nזיי<sup data-n=\"473\">98</sup> האָבן גענומען אַ וואָרט \"חלוץ\", בשעת מען לייענט (דעם וואָרט \"חלוץ\") אין דער תורה<sup data-n=\"474\">99</sup>, איז מיר זייער שווער דאָס וואָס זיי האָבן גענומען דעם וואָרט.\nאָבער מיר זיינען דאָך פראָנטאָ­וויקעס, און אַז מען איז אויף דעם פראָנט שטייט מען אין מס\"נ, ער דאַרף גיין נא שטאכי.\nמיט איין וואָרט: באַ יושבי אהל איז ניטאָ קיין גרינג, נאָר זיס — דאָס יע.\nכתיב \"יצא אדם לפעלו ולעבודתו עדי ערב\"<sup data-n=\"475\">100</sup>, ד\"אל יפטר אדם מחבירו אלא מתוך דבר הלכה\"<sup data-n=\"476\">101</sup>, הפירוש \"דבר הלכה\" איז \"הליכות עולם לו\"<sup data-n=\"477\">102</sup>, הילוך אין עולם. דאָס הייסט גילוי אלקות אין",[["471","96","רומח."],["472","97","ברכות רפ\"ה."],["473","98","הציונים."],["474","99","מטות לב, כא; כח; ל."],["475","100","תהלים קד, כג."],["476","101","ברכות לא, א."],["477","102","חבקוק ג, ו."]]],[4301600227,"עולם, וואָס עולם איז טבע<sup data-n=\"478\">103</sup>, ניט למעלה מן הטבע, נאָר אין טבע. והמשכת גילוי אלקות אין עולם איז ע\"י עבודה ויגיעה, וואָס מען דאַרף האָרעווען, ווייל למעלה מהטבע אין טבע איז דאָס המשכה פון ניט מציאות אין מציאות, און דאָס איז ביגיעה דוקא.\nוזהו \"יצא אדם לפעלו\", דאָס איז דער פועל פון אַ אדם. און וויפל איז דער שיעור פון האָרעווען — \"עדי ערב\", ביז עס ווערט זיס<sup data-n=\"479\">104</sup>. דברים הגשמיים זיינען בבריאתם ביטער, וכמו המים שניתן למשה<sup data-n=\"480\">105</sup>, וכן כל מה שנברא צריך תיקון, וכמאמר לעשות לתקן<sup data-n=\"481\">106</sup>, דורך עבודה דאַרף מען די גשמיות מאַכן זיס. און דאָס קומט דורך עבודה ויגיעה, קיין גרינגע איז ניטאָ, עס איז זיס אָבער שווער.\nוסיים כ\"ק אדמו\"ר: דאָס ענטפער איך דיר, קעגן דעם וואָס דו זאָגסט, גרינג.",[["478","103","ראה גם מאמרי שנה זו — סה\"מ תרפ\"ט ע' 43. ע' 205 ואילך. ע' 228."],["479","104","ראה גם סד\"ה יצא אדם לפעלו בסה\"מ אידיש ס\"ע 203. אגרות­קודש ח\"ג ע' תלב (הועתק ב\"היום יום\" א אדר א)."],["480","105","בשלח טו, כג ואילך."],["481","106","ראה ב\"ר פי\"א, ו ובפירוש (המיוחס ל)רש\"י."]]],[4301600228,"<h3>י\"ד כסלו, תרפ\"ט</h3>\n<b>בעת הקבלת פנים באולם הישיבה \"תומכי תמימים\"<sup data-n=\"482\">1</sup></b>\n[בראש השולחן ישב החתן<sup data-n=\"483\">2</sup>, מימינו כ\"ק אדמו\"ר שליט\"א, משמאלו חותן אדמו\"ר שליט\"א הרה\"ח הר\"א שניאור­סאהן<sup data-n=\"484\">3</sup>.\nאחרי שעה קלה פתח כ\"ק אדמו\"ר שליט\"א ואמר:]\nידוע<sup data-n=\"485\">4</sup> ומפורסם אשר בעת שמחת נשואין קומען נשמות האבות מן העולם האמת, ביז ג' דורות למפרע איז בכל ישראל, און פאַראַן וואָס מער און מער, וואָס אין דעם איז מדריגות שונות. ובתור הזמנה לנשמות הצדיקים הוד כ\"ק אבותינו רבותינו הק' אשר יבאו אל החופה ולברך את הזוג, וועט מען איצט ריידן אַ חסידות, וואָס אַ חלק איז פון אלטן רבין פון מיטעלן רבין, אַ חלק פון עלטער זיידן<sup data-n=\"486\">5</sup>, אַ חלק פון זיידן דער עלטער זיידע של הכלה<sup data-n=\"487\">6</sup>, אַ חלק פון",[["482","1","ע\"ד חגיגת החתונה של כ\"ק אדמו\"ר עם הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע — ראה רשימת כ\"ק אדמו\"ר מהחתונה (\"רשימות\" חוברת א' ע' 4­3. הועתק לעיל ב\"מבוא\" ע' יד ואילך). ספר התולדות אדמו\"ר מהוריי\"צ ח\"ד ע' 13 ואילך. ימי מלך ח\"א 257 ואילך."],["483","2","כ\"ק אדמו\"ר."],["484","3","הרה\"ק וכו' ר' אברהם שניאורסאהן מקישינוב. בן כ\"ק אדמו\"ר מהרי\"נ מנעזשין בן כ\"ק אדמו\"ר הצמח צדק. — ראה אודותו — ספר השיחות תר\"פ­תרפ\"ז ע' 81 הערה 55."],["485","4","נדפס בקונטרס דרושי חתונה תרפ\"ט — סה\"מ קונטרסים ח\"א לח, ב. סה\"מ תרפ\"ט ע' 80."],["486","5","כ\"ק אדמו\"ר הצ\"צ."],["487","6","כ\"ק אדמו\"ר מהר\"ש."]]],[4301600229,"עלטער עלטער זיידן של החתן<sup data-n=\"488\">7</sup>, אַ חלק פון טאַטען דעם כלה'ס זיידע, האומר שמועה בשם אומרו יהא רואה כאלו בעל השמועה עומד לנגדו<sup data-n=\"489\">8</sup>.\n[אח\"כ אמר מאמר דא\"ח ד\"ה לכה דודי לקראת כלה<sup data-n=\"490\">9</sup>].",[["488","7","כ\"ק הרה\"ק ר' ברוך שלום<sup data-n=\"e17\">*</sup> בנו בכורו של הצ\"צ (ראה שיחת חג השבועות תשי\"ג)."],["489","8","ירושלמי שקלים פ\"ב ה\"ה."],["490","9","נדפס בקונטרס דרושי חתונה תרפ\"ט — סה\"מ קונטרסים ח\"א כ, א ואילך. סה\"מ תרפ\"ט ע' 81 ואילך."],["e17","*","ראה אודותו — לקמן ע' 227. סה\"מ תרצ\"ו — חורף ה'ש\"ת ע' 253."]]],[4301600230,"<h3>י\"ד כסלו, תרפ\"ט</h3>\n<b>בעת סעודת החתונה</b>\n[באולם<sup data-n=\"491\">1</sup> עמדו שלחנות שלחנות ערוכים בכל מיני מעדני מלך וישבו העם על הסדר ואכלו ושתו לחיים ולברכה וישירו וירקדו וישמחו בשמחה של מצוה. אחר כך הלך כ\"ק אדמו\"ר שליט\"א סביב השולחנות ויחלק משקה לכאו\"א<sup data-n=\"492\">2</sup> בברכה<sup data-n=\"493\">3</sup>. בגשתו למקום עמידת תלמידי הישיבה ציוה להמשגיח ר\"א שימחאוויץ<sup data-n=\"494\">4</sup> לחלק משקה לכ\"א מהתל­מידים ויאמר<sup data-n=\"495\">5</sup>:]\n— תמימים אין התורה מתקיימת אלא במי שממית עצמו עלי'<sup data-n=\"496\">6</sup>, קיום התורה בא ע\"י היגיעה דוקא. לימוד התורה בכלל הוא ע\"י היגיעה דמי שמתיגע בא על עומק הדבר, דגם מי שיש לו שכל טוב שכל דק ובהשקפה ראשונה לוקח הענין בטוב, מ\"מ מי שאין שכלו טוב כ\"כ אבל",[["491","1","ראה לעיל ע' 53 הערה 1."],["492","2","ראה שיחת ש\"פ נשא תשמ\"ז (התוועדויות ח\"ג ע' 464): בעת סעודת הנישואין שלי, עמד כ\"ק מו\"ח אדמו\"ר ממקומו והלך בין המסובים לחלק להם משקה לומר לחיים. בראותי זאת, לא הייתי יכול להישאר לשבת במקומי כשכ\"ק מו\"ח אדמו\"ר עומד ומחלק משקה, ועמדתי ממקומי, כדי לסייע עכ\"פ, לאחוז את המשקה או להגיש את הכוסית כו'. מיד פנה אלי כ\"ק מו\"ח אדמו\"ר ורמז שאשאר לישב במקומי. וכשניסיתי להתעקש בכל זאת. . . רמז שוב [כ\"ק מו\"ח אדמו\"ר] באופן ברור שלא אקום ממקומי, כך, שבלית ברירה נשארתי לישב במקומי, \"אויף שפילקעס\". . . כמובן, עד שחזר כ\"ק מו\"ח אדמו\"ר וישב במקומו להמשיך בסעודת הנישואין."],["493","3","ראה עד\"ז — הנהגת כ\"ק אדמו\"ר מהורש\"ב נ\"ע בעת סעודת החופה של כ\"ק בנו אדמו\"ר מהוריי\"צ — ספר השיחות תש\"א ע' 104."],["494","4","משנת תרפ\"ז (לערך) ואילך שימש כמשפיע בישיבת \"תורת­אמת\" ירושלים. לחודש תשרי תרפ\"ט בא אל רבינו לריגא, והייתה סברא שיישאר בווארשא בתור משפיע בישיבת \"תומכי­תמימים\", אמנם לאח\"ז הוחלט שיחזור לירושלים לעזור בניהול הישיבה \"תורת­אמת\" (ראה אגרות­קודש חי\"א ע' צה ואילך ובהערת המו\"ל שם. תולדות חב\"ד בארץ הקודש ע' רכד­רכו. ספר השיחות תר\"פ­תרפ\"ז ע' 24 הערה 3). נזכר לקמן ע' 77."],["495","5","הבא לקמן הועתק מרשימות כ\"ק אדמו\"ר (הנ\"ל ע' 53 הערה 1). וראה שיחת ש\"פ וישלח, יד כסלו תשי\"ד."],["496","6","ברכות סג, ב. שבת פג, ב. גיטין נז, ב. זח\"ב קנח, ב (ברע\"מ). רמב\"ם הל' ת\"ת פ\"ג הי\"ב. שו\"ע יו\"ד סרמ\"ו סכ\"א. שו\"ע אדה\"ז הל' ת\"ת פ\"ד ס\"ט."]]],[4301600231,"מתיגע על השכל בא הוא אל העומק יותר, לפי שהתורה היא חכ' פי' אלקות, דגם שכל הנגלה שבתורה הוא אלקות. ובשביל זה הוא מה שבאים בגלות. הגלות הוא בישראל בכלל ולומדי תורה בפרט, ואתם תמימים בפרט (יש בזה אריכות דברים נאָר ניט דאָ איז דער אָרט פון דעם און ניט יעצט איז דער זמן דערפון), ועיקר קיום התורה הוא במי שממית עצמו עלי'. תדעו תמימים שעליכם לבטל עצמכם מכל וכל, און אויף דעם גייט איהר, תלמדו תורה ביגיעה, גם בנגלה, וכן תלמדו חסידות ולא שתשאר רק ההשכלה לבדה רק תבוא לידי פועל, הפי' במדות טובות ואז הנני מברך אתכם, איהר זאָלט גיהאָלפען וערען בכל הענינים הנצרכים לכם ותאריכו ימים ושנים כו'.\n[אח\"כ יצא בריקוד עם מנהלי הישיבה והמשגיחים.\nאחרי הפסקת זמן מה ישב כ\"ק אדמו\"ר שליט\"א על מקומו והתחיל לומר מאמר דא\"ח ד\"ה אשר ברא ששון ושמחה<sup data-n=\"497\">7</sup>. הדרוש נמשך עד חצות לילה.\nאח\"כ נט\"י כל המוזמנים לסעודה. באמצע הסעודה צוה כ\"ק אדמו\"ר לאחד התמימים לחלק משמו תשורה לכאו\"א, צילום ממכתב גכתי\"ק אדמו\"ר הזקן<sup data-n=\"498\">8</sup> בצירוף דברי הסבר<sup data-n=\"499\">9</sup> בו הוא כותב שהוא נותן את המכתב בתור תשורה לרגלי חתונת בתו תחי', אשר יהי' לסגולה לכל בית ישראל וכן ביאור<sup data-n=\"500\">10</sup> ופתשגן המכתב של אדמו\"ר הזקן.\nאנ\"ש שרו הרבה ניגונים בעזרת התזמורת, והסעודה נמשכה עד אחר שעה ו' בקר, בשירה, בזמרה ובתופים, והמחולות בשמחה וצהלה].",[["497","7","נדפס בקונטרס דרושי חתונה תרפ\"ט — סה\"מ קונטרסים ח\"א כא, ב ואילך. סה\"מ תרפ\"ט ע' 86 ואילך."],["498","8","נדפס באגרות­קודש אדה\"ז ח\"א אגרת לב (ע' פ). לעיל ב\"מבוא\" ע' טז."],["499","9","נדפס באגרות­קודש ח\"ב ע' קלא ואילך."],["500","10","נדפס בהוספות לאגרות­קודש אדה\"ז ח\"א ע' תלה. לעיל ב\"מבוא\" ע' יז."]]],[4301600232,"<h3>ליל א, י\"ט כסלו, תרפ\"ט, ריגא<sup data-n=\"501\">1</sup></h3>\nא. כ\"ק אדמו\"ר שליט\"א אמר: מה שנתחדש בדרוש וכל בניך<sup data-n=\"502\">2</sup> בווארשא יותר מהנאמר פה<sup data-n=\"503\">3</sup> שאמר אאמו\"ר שיאמר כן, שפעם<sup data-n=\"504\">4</sup> בא אחד לאדמו\"ר הצ\"צ וא\"ל: מי טרעט אַף מיר די גאַנצע",[["501","1","ההתוועדות בי\"ט כסלו נמשכה כמעט עד לפנות בוקר, וכ\"ק אדמו\"ר מהוריי\"צ ציין שאין זה רק לרגל יום הגאולה של אדמו\"ר הזקן, אלא גם \"שבע ברכות\" לחתנו כ\"ק אדמו\"ר ובתו הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע — ימי מלך ח\"א ע' 295."],["502","2","המאמר וכל בניך<sup data-n=\"e18\">*</sup> נאמר שתי פעמים, פעם הא' — ש\"פ ויצא בריגא, פעם הב' — יום ב' פ' וישלח, י\"ג כסלו בסעודת ה\"חתן­מאל\" בישיבת \"תומכי­תמימים\" בווארשא."],["503","3","בריגא. — ראה הערה הקודמת."],["504","4","מכאן עד סוף הסעיף הועתק מגוכי\"ק כ\"ק אדמו\"ר [נדפס לעיל ב\"מבוא\" ע' יט­כ], שהכין עבור \"קובץ מכתבים\" בענין \"אהבת ישראל\" שהי' אמור להופיע [בשנות תרצ\"ה­צח?]. — ראה \"מבוא\" לאגרות­קודש ח\"ג ע' 12. \"מבוא\" לאגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"א ע' 12."],["e18","*","נדפס בקונטרס דרושי חתונה תרפ\"ט — סה\"מ קונטרסים ח\"א יט, א ואילך. סה\"מ תרפ\"ט ע' 78 ואילך."]]],[4301600233,"שטיבעל, מי הערט זיין דעה ניט וכו' — (אמר כ\"ק אד\"ש: ער איז געוען אַ משכיל, אַ משיג) — והשיב לו: ואָס דאַרפסט זיך שפּרייטען איבערען גאַנצין שטיבעל אַז וואו מי טרעט, טרעט מען אַף דיר.\nואמר אדמו\"ר הצ\"צ: יעזוב רשע דרכו ואיש און מחשבותיו<sup data-n=\"505\">5</sup>, כשם שיעזוב רשע, רשע ממש צריך לעזוב את דרכו הרעה שלא יהי' עוד רשע, כן איש און אַ שטאַרקער מענש — ער האָט געטייטשט \"אָון\" לשון און שטאַרקייט<sup data-n=\"506\">6</sup> — דער וואָס איז שטאַרק באַ זיך, אַז זיין דעה איז אַ דעה, זיין השגה איז אַ השגה, זיין איך איז אַ איך, יעזוב מחשבותיו, ער דאַרף אַוועקלאָזן זיינע מחשבות, אויס איך, אַז איך בין גאָרניט. ער דאַרף זיך צוברעכן אַז ער זאָל זיין בפועל ממש ונפשי<sup data-n=\"507\">7</sup> כעפר לכל תהי'<sup data-n=\"508\">8</sup>.\nאַמאָל פלעגט מען רעדען חסידות קורץ, האָט אַמאָל<sup data-n=\"509\">9</sup> געזאָגט דער רבי<sup data-n=\"510\">10</sup> פון מעזריטשער מגיד פון בעש\"ט'ס וועגען<sup data-n=\"511\">11</sup>, אַז ואהבת לרעך כמוך<sup data-n=\"512\">12</sup> איז אַ פירוש וביאור אויף ואהבת את הוי' אלקיך<sup data-n=\"513\">13</sup>. אַז מ'האָט האָלט אַ אידען, האָט מען האָלט דעם אויבערשטען<sup data-n=\"514\">14</sup>, ווייל אַ איד האָט דאָך אין זיך אַ חלק אלקה ממעל<sup data-n=\"515\">15</sup>, איז אַז מ'האָט האָלט דעם אידען, דעם אינוועניק פון עם, איז ממילא האָט מען האָלט דעם אויבערשטען<sup data-n=\"516\">16</sup>.",[["505","5","ישעי' נה, ז."],["506","6","וכמו מרוב אונים (ישעי' נה, ז) או מצאתי און לי (הושע יב, ט). — סה\"מ שבשוה\"ג שבהערה 2."],["507","7","\"אלקי נצור\" בסוף תפלת העמידה."],["508","8","עיין כל הנ\"ל בתוספת ביאור במאמר כ\"ק אדמו\"ר שליט\"א ד\"ה וכל בניך, נאמר ב' וישלח תרפ\"ט ורשא, ונדפס בקונטרס בי\"ת<sup data-n=\"e19\">*</sup>. — הערת כ\"ק אדמו\"ר (ראה הערה 4)."],["509","9","קטע זה הועתק ב\"היום יום\" יב מנחם אב."],["510","10","כ\"ק אדמו\"ר הזקן נ\"ע. — הערת כ\"ק אדמו\"ר (ראה הערה 4)."],["511","11","ראה \"התמים\" חוברת ד ע' מה [קפח, א]. אגרות­קודש ח\"ג ע' תכו. ספר השיחות קיץ ה'ש\"ת ע' 3."],["512","12","קדושים יט, יח."],["513","13","ואתחנן ו, ה."],["514","14","להעיר משל\"ה שער האותיות ריש אות ב (צויין בהערת כ\"ק אדמו\"ר בספר השיחות ה'ש\"ת שם)."],["515","15","תניא רפ\"ב."],["516","16","מועתק בזה מ\"ש רבינו באחד ממכתביו — מיום נר ה' דחנוכה תרפ\"ט (אגרות­קודש ח\"ב ע' קלד ואילך) — בביאור הדברים שנזכרו כאן בענין \"ואהבת לרעך כמוך\": כתי' ואהבת לרעך כמוך, ונת' בי\"ט כסלו העבר, כי ואהבת לרעך כמוך הוא פירוש וביאור של ואהבת את הוי' אלקיך, אז דורך דער עבודה פון אהבת ישראל קומט מען צוא, צוא אהבת הקב\"ה.\nדהנה כתי' רעך ורע אביך אל תעזוב, איז א עובד (שתי מדרגות בחסידים, עובד ומשכיל אשר באמת שניהם אחד, דאי אפשר עובד בלא משכיל, ואי אפשר משכיל בלא עובד, רק ההפרש הוא מה בראש ובתחלה אם משכיל או עובד, והנסיון הראה, כי מי שהתחיל מעבודה (היינו קבלת עול כו') נעשה משכיל ג\"כ, ומי שמתחיל מהשכלה הדרך מסוכן, ומהם אשר ההשכלה פקעה ח\"ו, ונשארו קרח מכאן ומכאן ל\"ע) הערט אין דעם אן אז רעך ורע אביך דאס איז שם הוי'.\nשם אלקים בגימ' הטבע, וזהו בראשית ברא אלקים, דבריאת והתהוות העוה\"ז שהוא טבע, כאמור, אלקים וזהו עולם כמנהגו נוהג, הוא ע\"י שם אלקים<sup data-n=\"e20\">*</sup>, ופירוש אלקים הוא ל' כח כמ\"ש ואת אלי הארץ לקח דיא שטארקע ושם הוי' הוא למעלה מן הטבע וזהו הוי' ל' הי' הוה ויהי' כאחד דזהו למעלה מן הטבע, ולכן משם אלקים ידעו ויודעים גם מחסידי וחוקרי או\"ה כמו אלימלך<sup data-n=\"e21\">**</sup> ואף פרעה ידע מזה, הוא אמר מי הוי' אשר אשמע בקולו אבל משם אלקים ידעו.\nחסידי וחוקרי או\"ה שייכים רק לידיעה של שכל אנושי ולא יותר, ולכן הנה ש' אלקים שהוא בגימ' הטבע הם משיגים, ובכל השגתם באים לידי זה, שבהכרח הוא שהטבע יש לה מנהיג שהוא למעלה מן הטבע, אבל בזה אין להם שום השגה כלל, ואין הם חוקרים בזה כלל, כמבואר במורה נבוכים, כוזרי ועוד.\nכל התעסקותם של החוקרים הוא בהיש לאחר שנמצא, וכמו טבעי וסגולות סמי הרפואה, ההרכבה וההפרדה, המנוחה והתנועה, אופני הצמחים וסגולתם, וכן בכל דבר יש וממשי, לחקור עליו באופן מציאותו והרכבתו, דכל זה הוא בחקירת היש לאחר שנמצא במציאות יש, שהוא טבע. אבל איך נולד היש מהאין בזה הם רק מאמינים.\nוטעם אמונתם, אינה אמונה טהורה, כ\"א אמונה מוכרחת, דהלא הכל מודים כי יש מיש הוא שקר גמור, הלא איפוא מוכרח הוא שהיש מקורו אין, א\"כ הרי כל החקירות וההבנה צריכה להיות בהתהוות היש מאין.\nוהאמונה דנש\"י הוא בש' הוי' היינו למעלה מן הטבע, ואין זה אמונה כ\"א הרגש, גיפיל, א איד דער הערט און ביי אים לייגט זעך אפ אין נפש דער ענין פון למעלה מן הטבע.\nוזהו רעך ורע אביך שהוא שם הוי' כמ\"ש באברהם (עיין שמ\"ר ר\"פ כ\"ז) כי ידעתיו למען אשר יצוה (ער ועט צואנייף בינדין) את בניו ואת ביתו אחריו (אז) ושמרו את דרך הוי', אז א איד זאל דער הערין דעם גילוי פון שם הוי' שהוא למעלה מן הטבע, וזהו ואהבת את הוי', האבין האלט דעם למעלה מן הטבע עד שיהי' אלקיך אין א פנימית, לעבין מיט למעלה מן הטבע.\nוהכלי לזה הוא אהבת ישראל שהם מדות טובות, וארעם דורך מדות טובות ואס זיינען עפ\"י תורה, קאן מען צוא קומען צו געטלעכקאייט, ואס דאס איז דער גאנצער נייס פון ירידת הנשמה בגוף, אז א חומרי וגשמי זאהל צוא קומען צוא אלקות און עצמות א\"ס ב\"ה, העכער ויא א נשמה ואס זיא איז למעלה אין גן עדן קודם ירידתה למטה להתלבש בגוף.\nא נשמה אין א גוף גשמי און איז מקיים מצות ד' בגשמיות און האט גוטע מדות כמו שהם עפ\"י תורה, איז דאס העכער ויא די נשמה איז גיוען איידער זי איז אראפ גיקומען למטה.\nחשבון קצר וחריף, כל הנשמות נבראו קודם שנברא העולם, דבריאת העול' הם בדיבור כבי' כמ\"ש ויאמר אלקים, והם העשרה מאמרות שבהם נברא העולם ומלואו, והנשמות נבראו במחשבה כמאמר ישראל עלו במחשבה, דמחשבה קודם לדיבור גם במעלה ומדריגה.\nשטייט א נשמה 5 טויזינד יאהר און וארט ביז זיא ועט זוכה זאיין בגורל, אייף אראפ קומען אין דער פליישיקער גראבער פינשטערער ועלט, אן טאן זיך אין א לבוש פון בשר גידים ועצמות, זאיין אין שכנות מיט א נפש הטבעי ובהמי מאה ועשרים שנה וכמ\"ש והיו ימיו מאה ועשרים שנה.\nאון די ק\"כ שנה ואס די נשמה איז אין א גוף גשמי ועוסק בתורה (גם בעלי עסקים פרק א' שחרית ופרק א' ערבית) ומקיים מצות ד' בהנהגה טובה של מדות טובות, מעלים את הנשמה למדריגה עליונה יותר מכמו שהיתה הנשמה קודם בואה לעולם.\nעד כמה צריך האדם החי על פני אדמה זו, לייקר ולחבב כל שעה ושעה ממש, ולהיות כל עניניו במדות מדודים וספורים שיהיו מאירים ובהירים באמת, ע\"כ כל אדם צריך להשתדל במדות טובות."],["e19","*","סה\"מ שבשוה\"ג שבהערה 2."],["e20","*","כ\"ה באגרות­קודש שם. ובהעתקה אחרת: שם אלקים בגימ' הטבע, וזהו בראשית ברא אלקים, דבריאת והתהוות העוה\"ז שהוא טבע, נאטור, הוא ע\"י שם אלקים אלקים. וזהו עולם כמנהגו נוהג."],["e21","**","כ\"ה באגרות­קודש שם. ואוצ\"ל: אבימלך. — ראה גם מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' תב. סה\"מ עטר\"ת ע' שס. תרצ\"ז ע' 149. וש\"נ."]]],[4301600234,"ב. אַ חסידישער איד דאַרף דעם באָרד ניט שערן, מאַכן אַ שפּיץ בערדל אַ פראַנצוסקי בערדל, פע, דער זיידע<sup data-n=\"517\">17</sup> זאָגט אַז עס איז אַ איסור דאורייתא<sup data-n=\"518\">18</sup>, און ער איז דער מרא דאתרא ביי חסידים. איר אַלטע וואָס איר זייט געווען ביי דעם זיידן, ביי דעם טאַטן, ביי די פעטערס, ביי די שוועסטער­קינדער — איר האָט אַלע געזען גילוי",[["517","17","כ\"ק אדמו\"ר הצ\"צ."],["518","18","ראה לעיל ע' 35. וש\"נ."]]],[4301600235,"אור, ווי אַזוי זייט איר מחלל את השם, איך וויל אייך גאָר ניט זען אַזוי, מילא די יונגע וואָס האָבן נאָך קיין אור ניט געזען, זיי דאַרף מען מקרב זיין, אָבער איר אַלטע ווי ווערט דאָס בא אייך רעכט תירוצים באנק וכו', דער זיידע דער מרא דאתרא האָט דאָך אָבער גע'אסר'ט (ובכה הרבה באמרו הדברים האלה)<sup data-n=\"519\">19</sup>.\nג. אמר לחיים להתמימים במדינתינו, ואמר: וואָס ווינטשן? מיר זאָלן זיין באיחוד איז פאַרשפּאָרט, עס איז ניטאָ אַ רגע<sup data-n=\"520\">20</sup> וואָס איך טראַכט ניט וועגן זיי און זיי וועגן מיר. דער אויבערשטער זאָל געבן עס זאָל אַראָפּ אַלע העלמות וכו'.\nד. צוה לשלוח טעלעגראם לכמה עיירות מרוסלאנד<sup data-n=\"521\">21</sup>.\nשאל אותו שמעון יצחק<sup data-n=\"522\">22</sup> איך לחתום. ואמר: ער זאָל דערמאָנען זיין נאָמען וועט זיין אַ רחמנות אויף זיי ד.ה. ניט אויף זיי נאָר אויף [...], שרייבט ראדסטוועניק, אַלע אידן שומרי תורה זיינען מיר שוועסטער­קינדער און חסידים זיינען מיר ברידער און תמימים זיינען ממש פון איין טאַטן און פון איין מאַמען.",[["519","19","מועתק בזה דברי רבינו באחד ממכתביו — מיום א' ב' שבט תרפ\"ט (אגרות­קודש ח\"ב ע' קנג) — שהם כנראה המשך הדברים שנזכרו כאן: בחג הגאולה — י\"ט כסלו — שנה העברה, כנהוג באו בלא ע\"ה, הרבה בע\"ב וחסידים מקומים ואורחים יחיו, ובסעודת מצוה, אחרי אמירת חסידות, מצאתי לנכון, לדבר עניני התעוררות בדבר הרבצת תורה, ותורה תמימה.\nומדי דברי, על דבר תורה תמימה, נגעתי בענין הנהגת צעירי אגודת צעירי ישראל יחיו, ואופן הלימוד בבית הספר \"תורה ודרך ארץ\", וכמובן אשר בקרתי בסכינא חריפא, לאמר טוב תורה ודרך ארץ, מדרך ארץ ותורה, כי בכל השילובים הראשון גובר, אבל הטוב האמיתי הוא \"תורה תמימה\" תורה ויראת שמים, והראתי לדעת כי דבר זה תורה ודרך ארץ טוב הוא רק עבור אלו שעלולים להיות ח\"ו גרוע מזה, ולהם הוא מעלה, אבל לא הכל (ניט אלע) צריכים להביט במבט כזה, והארכתי במאמר הרמב\"ן בענין נבל ברשות התורה, וציירתי ציורים אמיתים מהחיים ההוים, שיוכל להיות גם בקרב ההולכים בדרכי התורה והמצוה, ומתנהגים עפ\"י שו\"ע, ועם זה הם מזוהמים בדברים המותרים, ובארתי מאמרי הרמב\"ם ז\"ל בפרק הרביעי מהשמונה פרקים.\nלא אכחד כי דיבורי עשה רושם עז, המתונים ראו במבט ישר, ותרגמו פתגם הטוב והמעולה הנ\"ל כמשמעו, ומהם אשר מצאו עלבון להאגודה.\nכעבור איזה חדשים איזה מהתלמידים שי' מתור' ודרך ארץ עזבו את בית הספר ויתחילו ללמוד בסדר הראוי להם, וצעירי אג\"י יחיו התועדו ויחליטו לעשות להם קביעות שיעורי לימוד בעניני מוסר, לאט לאט פרקו אותות הכבוד בערב ש\"ק ושער זקנם צמח."],["520","20","ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 119."],["521","21","בימי מלך ח\"א (קה\"ת, אה\"ק, תשמ\"ט) ע' 295: בתחילת ההתוועדות פנה הרבי למזכירו הר\"ר יחזקאל פייגין וביקשו לשגר מברק לרוסטוב, שבה מצוי אוהל אביו, אדמו\"ר מהורש\"ב.\nהרבי נקב בשמו של האיש אליו לשגר את המברק והחל להכתיב את הנוסח:\n\"להניח פדיון על ציון אבי יעווא זשעלאניע איספאלענע (= רצונו התבצע)\".\nמילים אלו אמר הרבי ברוסית, ולכך הוסיף עוד מספר מילים באידיש כשהוא מציין כי ברוסית ייטיב לתרגם [ר' שמעון יצחק] וויטנבערג<sup data-n=\"e22\">*</sup>."],["522","22","ראה הערה הקודמת ובשוה\"ג."],["e22","*","עסקן חרדי וציר בית הנבחרים בלטבי', חסיד חבד\"י נלהב. ויחד עם הרב ח. מ. א. חדקוב ע\"ה הקים את התשתית של החינוך האורתודוקסי בלטבי'. נהרג על קידוש השם במחנה עבודה גרמני באפריל 1945. — ימי מלך שם."]]],[4301600236,"ה. אחד ביקש שיאמר דא\"ח, ואמר כ\"ק אדמו\"ר: מען איז מיר מכריח צו ריידן חסידות, אויף ריידן חסידות דאַרף מען האָבן די כותלי החדר, אַ נשמה איז מלובש אין אַ גוף און אַ גוף אין לבושים און די לבושים אין כותלי החדר, און דאָס איז די הכנות צו ריידן חסידות. נאָר מען איז מיר מכריח איז אָן אַ אישור און אָן אַ יאַרליק<sup data-n=\"523\">23</sup> כו'.\nו. מקדשין את החג. פאַראַן דער חילוק פון שבת ביז יו\"ט, שבת איז מיקדשא וקיימא<sup data-n=\"524\">24</sup> און יו\"ט דאַרף האָבן ב\"ד זאָלן מקדש זיין<sup data-n=\"525\">25</sup>. י\"ט כסלו איז ווי שבת און מען האָט דאָס מקדש געווען, נאָר מען דאַרף עס אויך מקדש זיין.\nאמר אחד ששמע מאיש זקן מראדמיסלא<sup data-n=\"526\">26</sup> ששמע מחותנו ר' זלמן מאיר רפאל'ס<sup data-n=\"527\">27</sup> אַז דער אלטער רבי האָט געזאָגט: איך האָב מקדיש געווען דעם טאָג פון י\"ט כסלו אַזוי ווי יוה\"כ, אַז וואָס אַ איד וועט בעטן וועט ער אויסבעטן.\nויען כ\"ק אדמו\"ר: עס איז נשקשה. ואח\"כ חזר הדברים כמה פעמים בהמשך הלילה.\nז. אמר לסוחר אחד שבהליכתו מקאנטאר לקאנטאר<sup data-n=\"528\">28</sup> יחשוב לכה\"פ בקיצור שנתאווה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"529\">29</sup>.\nאמר בדרך צחות: מען דאַרף אַביסל אַ טראַכט טאָן אַז נתאווה הקב\"ה להיות לו ית' דירה בתחתונים, איי אַז איר שיקט מיר צו אַ אוטא און איך פאָר אין עם דאַרף איך טראַכטן נאָר חסידות, נאָר איר דאַרפט אַ וויילע אַ טראַכט טאָן אַז נתאווה, און מיט דעם מאַכט מען אַ כלי צו אלקות.\nודיבר עוד להנ\"ל אודות שבת, שלא יהי' במסחרו שום חילול שבת ושגם בטלפון לא ידבר בשבת, מען דאַרף וויסן אַז א. ענטפערט ניט שבת, ניט א. ניט ב. און ניט ס. ממילא וועט ש. אויך ניט ענטפערן.\nאמר א. הנ\"ל אַז די געשעפטן זיינען ?לאָה.\nאמר לו כ\"ק אדמו\"ר: דער אויבער­שטער וועט העלפן אַז עס וועט ווערן פון ?לאָה ווייס. [והוסיף כ\"ק אדמו\"ר:] א. האָט געדאַרפט געבן 100 צערוואָ­ניצעס<sup data-n=\"530\">30</sup> אויף תומכי­תמימים און ער האָט ניט געגעבן דעריבער איז ?לאָה, איך האָב עס געוואוסט פריער, ר' יוחנן",[["523","23","תווית."],["524","24","ראה ביצה יז, א."],["525","25","ראה ברכות מט, א."],["526","26","הישיש [ר' נחום<sup data-n=\"e23\">*</sup>] מראדמיסעל. חותנו ר' זלמן בן ר' מאיר רפאל'ס מווילנא מחסידי אדה\"ז. אביו [שהי' גם גיסו של ר' זלמן הנ\"ל] הי' מחסידי אדה\"ז שבשקלאוו. ואדמו\"ר הצ\"צ אמר שאביו הי' ממנין הבינונים שעשה אדה\"ז ממתנגדי שקלאוו. רשימת רבנו משנת תרס\"ח — אגרות­קודש ח\"ז ע' טז. יגדיל תורה ניו יארק שנה ג חוברת לא ע' שכז ואילך."],["527","27","אודות ר' מאיר ב\"ר רפאל — ראה בית רבי חלק א פכ\"ו (עג, א). כרם חב\"ד גליון 4 חלק א ע' 35 ואילך. וראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 54."],["528","28","ממשרד למשרד."],["529","29","תנחומא נשא טז. ועוד. תניא פל\"ו."],["530","30","שם מטבע לפנים ברוסיא."],["e23","*","ראה שמועות וסיפורים ח\"ג ע' 159. לשמע אזן (הוצאת תש\"נ) ע' קיז [ושם, שהי' חתנו של גיסו של ר' מאיר רפאל'ס]. ועוד."]]],[4301600237,"לבר אחתי' האָט געזאָגט<sup data-n=\"531\">31</sup>, און איך האָב ניט געזאָגט, נאָר איצטער וועט דער אויבערשטער העלפן, די פאראגעס זייט איר שוין אַריבער נאָר מען דאַרף געבן מעשר און מאַכן אַ כלי צו אלקות.",[["531","31","בבא בתרא י, א. וראה גם לעיל ע' 34."]]],[4301600238,"<h3>ליל ב' כ' כסלו, תרפ\"ט, ריגא</h3>\nא. כ\"ק אדמו\"ר שליט\"א שאל: פאַרוואָס עסט מען ניט. החסיד ר' הלל<sup data-n=\"532\">1</sup> אמר לפני הצ\"צ שמאכילת שלמים במקדש הי' ניזונים כל השנה, והצ\"צ הסכים לזה.\nואח\"כ אמר לאחד: מען דאַרף זיין שטענדיק בהתאחדות עם התורה, במשה כתיב<sup data-n=\"533\">2</sup> כי מן המים משיתיהו שרק לפי שעה לצורך יצי\"מ וקי\"ס ומ\"ת האָט מען אים אויף אַ וויילע אַרויסגענומען פון די מים וואָס דאָס איז תורה. וכן ישנם כאלו שצריכים להיות תמיד בהתאחדות עם התורה.\nובקש אחד ברכה ע\"ז, ואמר לו: מיר זיינען ניט קיין בעטלערס, מיר זיינען יאָ בעטלערס נאָר פאַר כלל ישראל אויסבעטן כל טוב, אָבער פאַר זיך דאַרף מען האָרעווען מען דאַרף זיך צוברעכן \"כתית\"<sup data-n=\"534\">3</sup> צו רייבן.\nעס איז דאָ צייטן ווען מען דאַרף ניט גיין אין גאַס, ד. ה. ניט נאָר גיין אין גאַס און זיין אַ עוצם עיניו, נאָר ניט גיין טאַקע. גיין און מאַכן קונצן איז דאָך בליטות, טויג דאָך ניט. אויב מען מוז גיין אין גאַס דאַרף אָבער זיין שעות קבועות וואָס אין יענער צייט גייט ער ניט, און אויב מען גייט דאַרף מען גיין אין די גאַסן וואָס אין רוב בני אדם מצויין שם.\nב. אח\"כ שמע שמדברים בפנות הבית, ואמר: ריידן דאַרף מען ניט, מען דאַרף שווייגן און זאָגן לחיים, דעם וואָרט \"לחיים\" קען מען זאָגן, ושיהי' לחיים כמשמעו געלעבט און אין דער שטיל, וכמו שרואים שמי שהוא חולה ר\"ל, איז אַז ער לעבט איז מיט אַ רעש: ער חליפּעט און שיפעט. און אַ געזונטער חריפּעט ניט, ער לעבט שטיל.\nמען דאַרף זאָגן לחיים דער אויבערשטער זאָל געבן אַז מען זאָל דערהערן למעלה מן הטבע אין טבע<sup data-n=\"535\">4</sup>.\nג. אח\"כ קרא לשמש אחד ואמר לו: באַ אונז אין פט\"ב פלעגט מען רופן<sup data-n=\"536\">5</sup> אַ \"ש?מש\" — \"שמש\"<sup data-n=\"537\">6</sup>, וויילע אַ שמש דאַרף",[["532","1","ראה אודותו בהנסמן לעיל ע' 30 הערה 10."],["533","2","שמות ב, י."],["534","3","לשון הכתוב — תצוה כז, כ. וראה ד\"ה וקבל היהודים תרפ\"ז (סה\"מ תרפ\"ז ע' קכד). ד\"ה הנ\"ל תשמ\"א (סה\"מ מלוקט ח\"ו ע' קל ואילך)."],["535","4","ראה גם מאמרי שנה זו — סה\"מ תרפ\"ט ע' 43. ע' 205 ואילך. ע' 228."],["536","5","ראה ספר השיחות תר\"פ­תרפ\"ז ס\"ע 103 ואילך. אגרות­קודש ח\"ב ע' תסז. אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ח ע' עא. ע' קעד. ח\"י ע' קיח. חי\"ב ע' רלג. חי\"ג ע' תלד. חי\"ד ע' שלג. חי\"ח ע' רעא. חכ\"א ע' רצ."],["537","6","להעיר מזוהר חדש בראשית (במהנ\"ע) טו, א: דעל כך מתקרי שמשא ש?מפּשפּא דמשמש לכולא. וראה אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ח שם."]]],[4301600239,"מאיר זיין אור. אַ שמש דאַרף ניט פאָלגן די בע\"ב, נאָר די בע\"ב דאַרפן אים פאָלגן.\nאַ שמש דאַרף ניט נאָר געבן אַ סידור, ער דאַרף אַ סידור אויך געבן, נאָר ער דאַרף געבן אויך אַ תהלים, אַ משניות, אַ עין יעקב, ער דאַרף מאַכן אַ \"חברה­משניות\" צי עין יעקב צי וואָס עס זאָל ניט זיין.\nאַ שמש דאַרף זען אַז זיין מנין זאָל זיין אָפן כ\"ד שעות<sup data-n=\"538\">7</sup>.\nפעם א' הי' אצל הצ\"צ פינצטער אמר \"קראו לשמש ויאיר אור\", ומקרא מלא דיבר הכתוב<sup data-n=\"539\">8</sup> \"קרא לשמש ויזרח אור\".\nצוה לקחת משקה, ואמר: עס דאַרף זיין מרפא ארעא כמו המטר דמרפא ארעא.\nושאל אחד: הרי צ\"ל חרישה מקודם?\nוהשיב: ודאי כן הוא.\nואמר אחד: וואָס טוט מען מיט דעם געזונט.\nואמר: אודאי שא\"צ ליקח אַז מען פילט אַז דאָס איז מזיק לבריאות. אָבער אין אַלע ענינים קוקט מען דאָך ניט אַזוי פיל אויף דעם געזונט, עס איז דאָך פאַראַן ענינים וואָס שאַטן אויף אַ אמת צום געזונט און מען טראַכט גאָר ניט אַזוי פיל, און דאָ האַלט מען זיך אָפּ.\nווען עס פאַלט מחשבות זרות אין דאַוונען איז עס דאָך אַ גרויסע קשיא: אין עניני העולם אַז מען רעט דברים בטלים פאַלט ניט קיין מחשבות זרות און דוקא אין דאַוונען פאַלט אַריין מחשבות זרות.\nוכן בכל הענינים: ער קומט אַהיים אַ פאַרהאָרעוועטער פון געשעפט, און זאָגט: שוין לאַנג ניט געווען באַ חיים'ן, באַ יענעם באַ דעם, מיט אַ וויזיט — מען דאַרף אַריין גיין. און אויף דעם איז דאָ צייט, און אויף קובע זיין עתים לתורה איז ניטאָ קיין צייט.\nמיר זיינען אַזעלכע חכמים מען האָט שוין אַלץ אויסגעלערנט טיפער און נאָך טיפער, מען דאַרף אָבער עס זאָל זיין אינעווייניק און נאָך אינעווייניקסטער נאָך מער האָרעווען נאָך מער צובראָכן, אָבער יענעם זאָל דאָס אָנרירן קען זיין אַז עס איז צו פיל.\nד. אמר לרי\"ב, דער אויבערשטער זאָל העלפן אייערע תלמידים זאָלן מקדש זיין ש\"ש ברבים, איר האָט זיך געלאָזן שווימען אויף די הויכע גראָז וואָס וואַקסט אין בלאָטע, איר פאַרשטייט דאָך ווי הויך איז די גראָז אויף בלאָטע, איז נאָר איר שווימט. דער אויבערשטער זאָל געבן אַז איר זאָלט אייערע אויספירן, און דעם לא טוב זאָל מען אַוועקוואַרפן אין אַלע שוואַרץ­יאָר אין ארץ גזרה.\nלא טוב<sup data-n=\"540\">9</sup> האָבן מיר אַלע. שעיר לעזאזל<sup data-n=\"541\">10</sup> איז געווען אַן עבודה אין בית המקדש<sup data-n=\"542\">11</sup>. וויבאַלד אַ נברא<sup data-n=\"543\">*11</sup> איז דאָ",[["538","7","ראה גם לעיל ע' 51."],["539","8","\"א­ל אדון\" בתפלת שחרית דשבת. — מצינו בכמה מקומות הלשון \"דכתיב\", על נוסח התפלה — ראה הערת כ\"ק אדמו\"ר בהערות ותיקונים לתניא מו, ב. בסה\"מ תש\"ט ע' 150."],["540","9","קטע זה הועתק ב\"היום יום\" כד ניסן."],["541","10","אחרי טז, ה ואילך."],["542","11","ביאור ענין \"שעיר לעזאזל\" ע\"ד החסידות — ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' לז ואילך (ועם הגהות — אוה\"ת יוהכ\"פ ע' א'תקסו ואילך). תק\"ע ע' קעז ואילך. סה\"מ תרע\"ח ע' לו ואילך. פר\"ת ע' קפב. ועוד."],["543","*11","אוצ\"ל: וויבאלד בא א נברא."]]],[4301600240,"לא טוב, דאַרף מען עס<sup data-n=\"544\">12</sup> אַוועקשיקען אין ארץ גזרה.\nה. הערט אידן, מאָרגן וועל איך מיט אייך ניט ריידן די רייד וואָס איך רייד היינט, זאָל עס נחקק ווערן בפנימיות הלב:\nדער טאַטע וואָס הערט איצטער דברי הרב פון אל\"ף ביז תי\"ו גיט ער יעצט דורך מיר איבער.\nמען<sup data-n=\"545\">*12</sup> זאָל זיך אויסלערנען משניות בעל פה כל חד לפום שיעורי' דילי', און געהן אין גאַס און חזר'ן משניות, דערמיט וועט מען זוכה זיין צו מקבל זיין פני המשיח.\nחסידים דאַרפן לערנען חסידות: סתם חסידים — יום שני, יום חמישי ויום השבת, תמימים — שעה אחת בכל יום.\nאותיות התורה ווערן אָנגערופן \"סוסים\"<sup data-n=\"546\">13</sup>, אותיות התורה זיינען אַ תשועה, אָבער באַ אַ משכיל איז \"שקר<sup data-n=\"547\">14</sup> הסוס לתשועה וברוב חילו לא ימלט הנה עין הוי' אל יראיו\" קיין ענין ניט, נאָר פנימיות ועצמיות א\"ס ב\"ה.\nאותיות כשהן לעצמן טראָגט אַרויס אַז מען מאַכט אַ ברכה \"אשר בחר בנו\" ו\"אשר נתן לנו תורת אמת\" איז דאָך אותיות טראָגט אַרויס, אָבער אַז מען מאַכט דערפון מושכלות איז \"שקר הסוס לתשועה\", מען דאַרף האָבן קבעומ\"ש.\nו. אמר לכל ההמון: הערט אידן איך וויל אייך זאָגן ווער איך בין. איך בין אַ ליטוואַק, אַ ליטוואַק גלויבט ניט אויף באָרג<sup data-n=\"548\">15</sup>. איר זייט אַלע געקומען אַהער מיט השגחה פרטית, קיינער האָט אייך ניט גערופן, קיינער האָט אייך ניט געשיקט קיין בילעטן. איר געהערט אודאי צו אַ אגודה פון \"חברה ש\"ס\" \"חברה עין יעקב\", תורת הבעש\"ט האָט אונז געלערנט דעם ענין פון הוכחה, אַז אַלע חסרונות זאָל מען זען אין זיך<sup data-n=\"549\">16</sup>. אַז מען זעט אין יענעם אַ חסרון שפּיגלט זיך אָפּ אַליין. מען זעט אַמאָל אין שפּיגל אַ חי' רעה און דאָס זעט אויף יענעם אַ חסרון. איך באַשולדיק אייך ניט, נאָר איך בעט בלשון בקשה, אַז איר זאָלט זען קובע זיין עתים לתורה, קיין טאָג זאָל ניט דורכגיין ניט געלערנט, פון דעם טיפסטן ענין ביז דעם פשוט'ן, אַלע דאַרפן לערנען כל חד לפום שיעורא דילי'.\nז. אמר לאחד: מאַכט אַ חדר מיט מס\"נ. איר זייט ניט קיין קבצן ניט קיין אָרימאַן מ'גייט ח\"ו ניט קלייבן וכו', פאַרקויף אַלץ וואָס דו האָסט און מאַך אַ חדר מיט מס\"נ.\nח. לחיים, דער אויבערשטער זאָל העלפן בזכות פון רבי'ן אַז עס זאָל נתעורר ווערן די נקודת פנימיות הלב אַז וואו מ'גייט און וואו מ'שטייט זאָל מען דערהערן רצונו ית', אין בעל הנס מכיר בניסו<sup data-n=\"550\">17</sup> מיינט ניט אַז דאָ גיט מען אייך",[["544","12","כ\"ה ב\"היום יום\" שם. וברשימה אחרת: דארף מען אים."],["545","*12","קטע זה ושלאח\"ז הועתק ב\"היום יום\" כא כסלו."],["546","13","תו\"א בשלח סב, ג. לקו\"ת שה\"ש ב, ד ואילך. מאמרי אדה\"ז הנחות הר\"פ ע' א. אוה\"ת ויחי ח\"ו תתשמג, ב ואילך. ובכ\"מ."],["547","14","תהלים לג, יז­יח."],["548","15","ראה גם ספר השיחות: תרצ\"ו — חורף ה'ש\"ת ע' 112. תש\"ה ע' 13; אגרות­קודש כ\"ק אדמו\"ר שליט\"א ח\"ח ע' רסו. ע' רצט. ח\"ט ע' קיג. ועוד. לקמן ע' 170."],["549","16","ראה גם לעיל ע' 16. ע' 37."],["550","17","נדה לא, א. וראה אוה\"ת (יהל אור) לתהלים ע' קנד. ד\"ה כימי צאתך מארמ\"צ תשל\"ח (סה\"מ מלוקט ח\"ה ע' שז ואילך)."]]],[4301600241,"אַ זאַך וואָס איז ווייט פון אייך, דאָס שטייט אין אייערע ד' אמות אָבער איר שטופּט אַוועק פון זיך און שלעפּט בלאָטע.\nט. אַז מען זאָל זיך דערמאָנען די צייט ווען היינו המסובים אצל הר סיני כו'.\nהתחיל אחד לבכות, ואמר כ\"ק אדמו\"ר: טרערן איז וויילע מען איז מפריד בין הדבקים, אָבער באַ דעם וואָס עס איז איין המשך וויינט ניט, מען דאַרף זיין תכלית הדביקות עס איז איין המשך ממש.\nאַ בעל עסק אַ סוחר וויל ניט די געלט נאָר דעם שכל, נאָר אַז ער פאַרדינט איז עס אַ הוכחה אַז זיין חכמה איז אַ חכמה, און פאַרקערט ח\"ו איז אַ הוכחה אַז עס איז ניט קיין חכמה.\nפאַראַן אַ איד וואָס זאָגט אז מאה אלף פונט איז זיין טעקושטשי שטשיאט<sup data-n=\"551\">18</sup> איז אַ חכמה אויף יענעמס איז אַ נאַרישקייט. אַ חסידישע ביסל משקה איז אַ מאה אלף רו\"כ אויפן אייגענעם טעקושטשי שטשיאט<sup data-n=\"551\">18</sup>. אַז דוד המלך האָט דערזען אַז איינער וויל אַביסל געלט האָט ער אים געמאַכט אַ ממונה על האוצרות. אַז מען זעט אַז אַ איד וויל נתקרב ווערן צו אלקות, נאָר עס פעלט עפּעס, דאַרף מען עם געבן, און ער זאָל נתקרב ווערן — ניט נאָר א. נאָר אַלע אידן דאַרפן.\nי. לחיים, דער אויבערשטער זאָל אַייך העלפן אַז די בראַנפן זאָלן אַריין אין אַ פנימיות, די פנימיות פון אַ אידן איז זייער טייער ווען איר וואָלט וויסן אייער אינוועניג ווי טייער דאָס איז — אפילו די וואָס גאָלן זיך איז אויף זיי אַ רחמנות (ה' לאוין)<sup data-n=\"553\">19</sup> — אָבער זיי זיינען טייערע אידן דער אינוועניג דער נקודת היהדות, אפילו די וואָס דאַוונען שבת מיט דעם ערשטן מנין שבת כדי נאָך דעם איך ווייס ניט וואָס [לא רצה לאמרו בפה], ער וועט זיך אויסהיטן ניט שרייבן, פון אַנדערע מלאכות, אָבער עס איז פאָרט חילול שבת, נאָר אינדערפרי גאַנץ פרי לויפט ער דאוונען — ווי וועט ער שבת ניט דאַוונען מיט אַ מנין? עס איז דאָך שבת, און דער לויפן דאַוונען איז זייער אַ טייערע זאַך.\nדער אויבערשטער זאָל אויף זיי רחמנות האָבן און זאָל זיי העלפן אַז זיי זאָלן ניט דאַרפן מחלל שבת זיין.\nיא. איצט איז עקבות משיחא, פאַר אַ סטאַנציע<sup data-n=\"554\">20</sup> הויבט זיך אָן פיל וועגן איז דאָ איין ליניע<sup data-n=\"555\">21</sup> אַ גלייכע ליניע און ווי עס קומט נעענטער צום סטאַנציע הויבט זיך אָן פיל ליניעס, און דאָ איז ערשט אַ סכנה ער זאָל זיך ניט אַריינפאָרן אויף אַ וועג וואָס עס קען ח\"ו זיין אַ קאַטאַסטראָפע<sup data-n=\"556\">22</sup>, דאַרף מען זיך זייער היטן גיין מיט די גלייכע וועג.\nאַזוי אויך איז פאַר משיח'ן דוכט זיך אַז עס איז דאָ פיל וועגן, אָבער דער אמת איז אַז מען דאַרף זיך היטן די איין וועג, דעם דרך הישר בכדי מען זאָל ניט זיין קיין מסוכן.",[["551","18","חשבון עובר ושב."],["551","18","חשבון עובר ושב."],["553","19","ראה לעיל ע' 35. וש\"נ."],["554","20","תחנה."],["555","21","קו."],["556","22","אסון."]]],[4301600242,"יב. מיין מחותן<sup data-n=\"557\">23</sup> איז אַ מקובל, איז ער מסביר<sup data-n=\"558\">24</sup> דעם ענין פאַר וואָס די חתונה<sup data-n=\"559\">25</sup> איז אין כסלו ווי ער איז מסביר. נאָר איך זאָג אַז כסלו איז אַ חודש השלישי פון פנימיות התורה<sup data-n=\"560\">26</sup>.\nיג. איך בין ניט גענאַרט באַ זיך אין עלמא דין ועלמא דאתי איז איין זאַך, ווער עס איז זוכה איז עולה נשמתו אין ג\"ע התחתון און ווער עס איז זוכה מער איז עולה נשמתו לג\"ע העליון, די נשמות וועלכע זיינען איצט געווארן זיינען ניט נתהווה געוואָרן איצט נאָר עלה ברצונו ית' פון פריער.\nואת ערובתם יקח<sup data-n=\"561\">27</sup>, איך בין ניט איך (באַ דיר איז דו), איך גיב אַוועק מיין בשר מיין נפש מיין רוח נשמה חי' יחידה פאַר אייך, אייך קען מען רופן אויף חתונה און מיך אַוועק שיקן פאַר אייך, איך בין אַ משפך אַז עס פאַרגיסט זיך איז די לייקע שולדיק, אַז עס פאַרגיסט זיך ניט איז אַ מעלה פאַר דער לייקע, אַז מען זאָל מיך פרעגן וואָלט איך אפשר געזאָגט גיב מיר ניט די מעלה ניט דעם חסרון, נאָר איך בין אַ טאַטנס אַ קינד איך האָב אמונה פשוטה אַז איר וועט מיר ניט פערוואַרפן<sup data-n=\"562\">28</sup>, אייער",[["557","23","הרה\"ג והרה\"ח וכו' המקובל מוהר\"ר לוי יצחק ז\"ל שניאורסאהן — אביו של כ\"ק אדמו\"ר. נולד ח\"י ניסן תרל\"ח — נסתלק כ' מנחם­אב תש\"ד. ראה אודותו ספר \"תולדות לוי יצחק\" (קה\"ת, אה\"ק, תשד\"מ)."],["558","24","ראה מכתבו מיום ו' כסלו תרפ\"ט ומכתבו מיום ח' כסלו תרצ\"א — נדפסו בלקוטי לוי יצחק אגרות­קודש ע' רה. ריז."],["559","25","של כ\"ק אדמו\"ר והרבנית הצדקנית מרת חי' מושקא נ\"ע ז\"ל."],["560","26","ראה שיחת ש\"פ וישב, כא כסלו תשי\"ד: \"כ\"ק מו\"ח אדמו\"ר האט געזאגט אויף דער חתונה דעם טעם פארוואס די חתונה איז בחודש כסלו, האט ער געזאגט: \"דער מחותן — ער האט געמיינט דעם טאטען — איז דאך א מקובל וועט ער דאס מסביר זיין עפ\"י קבלה, אבער איך זאג אז דער טעם וואס די חתונה איז בחודש כסלו דוקא, וויילע חודש כסלו איז דער חודש השלישי דער זמן פון מתן תורה\".\nד.ה. אז אזוי ווי אין די חדשי הקיץ וואס בכללות איז דאס — א ענין פון מלמעלה למטה — מדריגת הצדיקים<sup data-n=\"e24\">*</sup>, איז בחודש השלישי פון חדשי הקיץ וואס דאס איז חודש סיון, געווען מתן תורה פון גליא דתורה, וואס איז שייך ביותר צו עבודת הצדיקים, אזוי איז בחדשי החורף וואס זיינען בכללות מלמטה למעלה, מדריגת בעלי תשובה, איז חודש השלישי וואס דאס איז חודש כסלו, דער זמן פון התגלות פנימיות התורה\".\nוראה גם לקוטי שיחות ח\"א ע' 75. ספר השיחות תשמ\"ט ח\"א ע' 78. תנש\"א ח\"א ע' 163. תשנ\"ב ח\"א ע' 147. ע' 158. ח\"ב ע' 483. ובכ\"מ."],["561","27","ע\"פ שמואל­א יז, יח."],["562","28","ראה שיחת ש\"פ וישב, כא כסלו תשי\"ד: ידוע וואס ער [כ\"ק מו\"ח אדמו\"ר] האט געזאגט אויף דער חתונה בשנת תרפ\"ט: \"איך בין א משפך, א לייקע — א משפך איז דאס וואס דורך אים גיסט מען — און בשעת ס'פארגיסט זיך א טראפן לחוץ מאנט מען ביי דעם משפך, נאר פאר זיך ארט מיר ניט, אפילו מ'זאל אלעמען איינלאדן פאר דער חתונה און מיר ניט ארט מיר אויך ניט, נאר איך האף אז חסידים וועלן מיר ניט פארלאזן\".\nפון דעם איז מובן גודל האחריות וואס ס'ליגט אויף אונז, ווארום בשעת חסידים פירן זיך ניט כדבעי, הייסט דאך יעמאלט אז מ'פארגיסט לחוץ, און דאס איז נוגע אויך צום משפך, פארשטייט זיך דאך דער גודל האחריות, און מצד דעם וואס מ'האט ניט געפאלגט און ניט געווען מקושר כדבעי, האט געטראפן וואס עס האט געטראפן בשנת תש\"י, וואס דאס איז אונזער שולד.\n(כ\"ק אדמו\"ר שליט\"א בכה מאד, ולבסוף סיים:) און אעפ\"כ איז דאך אויך מפיהם אנו חיים, פון די השפעות וואס ער איז אונז משפיע און וויבאלד אז די השפעות גשמיות נעמט און מ'וויל, וואס ער איז דאך משפיע על תנאי צוליב רוחניות, איז אז מ'טוט די מעשה ווערט מען במילא נתחייב אין דעם תנאי, וואס דער תנאי איז התקשרות, און התקשרות מיינט ניט נאר היטן די תקנות אזוי ווי אמירת תהלים כו', נאר אויך לערנען זיינע חסידות וואס יעמאלט ווערט נמשך די השפעות בגשמיות, און ס'וועט זיין ווי די גמרא (ברכות לב, ב) זאגט \"מלאכתם מתברכת\"."],["e24","*","ראה סד\"ה ביום השמע\"צ שנה זו (סה\"מ תרפ\"ט ע' 70). וש\"נ."]]],[4301600243,"קאַפיטל תהלים איז מיר נוגע אין נפש<sup data-n=\"563\">29</sup>.\nדער טאַטע איז אין היכל מלך און זאָגט דעם הפרש פון הפשטה און שלילה כו'.\nואח\"כ אמר: איר ווערט נתפעל שטאַרק מען דאַרף ניט שטיין אַזוי ווייט, יעדער איד וואָס האָט געזען דעם טאַטן דאַרף ניט דורכגיין אַ וואָך<sup data-n=\"564\">30</sup> וואָס מען זאָל ניט זען פאַר זיך דעם טאַטנס תמונה, דער טאַטע שטייט מאחורי הפרגוד און זעט יעדערן'ס תמונה בפנימיותו.\nיעדערער פון אונז וואָס וויל זיין מקושר צו דעם אויבערשטן און די עבדי הוי' איז דא תרעא לעלאה<sup data-n=\"565\">31</sup>, תמימים איז אַ ענין פאַר זיך חסידות איז אַ ענין פאַר זיך, און סתם וועלט איז פאַר זיך, תנאי ההתקשרות איז ווער עס איז קובע עתים לתורה.\nאיך בין אַ צובראָכענער יתום, נאָר איך בין ניט קיין יתום, איך זע זיך מיט דעם טאַטן ווען ער וויל און ווען איך וויל, וואָס בכלל איז דאָס איין זאַך.\nדער אויבערשטער זאָל געבן אַז די שלשלת פון 180 יאָר זאָל איר זכות מגין זיין אַז איר וועט קומען אַ היים און אַ קוקט טאָן אויף אייערע בני בית זאָלן זיי פון אייך לעבן.",[["563","29","אולי הכוונה להמנהג לומר הקאפיטל תהלים של שנות אדמו\"ר."],["564","30","ברשימה אחרת: א זאך."],["565","31","ראה זח\"א ח, א."]]],[4301600244,"<h3>אור ליום ג' ה' טבת. פ\"ט. ריגא<sup data-n=\"566\">1</sup>.</h3>\nנכנסתי ע\"פ הקריאה לחדר כק\"ש. אמר שחפץ הוא למסור לי פ\"ש מאחי ליב<sup data-n=\"567\">2</sup> נ\"י (הדר בלנינגראד). על שאלתי, אם קבל מכ' ממנו, ענני: \"שמעתי מאמר דא\"ח ביחד עמו מאדנ\"ע<sup data-n=\"568\">3</sup>. וזה הדבר: בלילה הזה, ראיתי<sup data-n=\"569\">4</sup> את אדנ\"ע. מטפחת­המשי בידו ובפנים צוהלים עד למאד. בפעם האחרונה הי' כן מראהו בשנת תרס\"ח. ואמר לי: מז\"ט, פאַר דער היטל<sup data-n=\"570\">5</sup>. זיי קאָנען אַריינגיין. פתחתי הדלת ונכנסו כמה אנשים, וביניהם אחיך. מעט מעט קרב — או קרבתי אליו — וחבקתיו בידו אחת. אאדנ\"ע שאלני: ווער איז דער יונגערמאַן? אבל כעבור רגעים אחדים, אמר: אַ! איך קען דאָך דיר<sup data-n=\"571\">6</sup>.",[["566","1","מרשימות כ\"ק אדמו\"ר."],["567","2","הוו\"ח ר' ישראל ארי' ליב שניאורסאהן (תרס\"ו<sup data-n=\"e25\">*</sup>—תשי\"ב). ראה אודותו — ספר השיחות תר\"פ­תרפ\"ז ע' 125, ובהערה 10. וש\"נ."],["568","3","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["569","4","ע\"ד \"חזיונות\" רבותינו נשיאינו — ראה גם ספר השיחות: תר\"פ­תרפ\"ז ע' 69, ובהנסמן שם בשוה\"ג; תרצ\"ו — חורף ה'ש\"ת ע' 11 הערה 4. וש\"נ."],["570","5","הכוונה בזה — ראה לקמן קטע המתחיל בפעם הא'."],["571","6","להעיר, שכ\"ק אדמו\"ר מהורש\"ב נ\"ע לא ראהו מעולם (וראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 125 ובהערה 11)."],["e25","*","ראה רשימת הרב\"ש (קה\"ת, תשס\"א) ע' סח."]]],[4301600245,"אמר דא\"ח \"שחורה אני ונאוה\" (קוטב הענין: ירידת הנשמה בגוף<sup data-n=\"572\">7</sup> הוא עצם הנשמה<sup data-n=\"573\">8</sup>. והראי' באור דמל' ורדל\"א<sup data-n=\"574\">9</sup>. ואף שיש להקשות ממקום פלוני צריך לעיין במאמר תקס\"ו (או תקס\"ב), ענין דנסיון<sup data-n=\"575\">10</sup>, שהדבר אינו במציאות, וכחלוק שבין נסיון וברור<sup data-n=\"576\">11</sup>. ד' צדיק יבחן וכמשל היוצר שאינו בוחן וכו'<sup data-n=\"577\">12</sup>). וצריך לשאול אצל אחיך עד\"ז.\nאחר הדא\"ח נגשתי אל אאדנ\"ע<sup data-n=\"568\">3</sup> ושאלתיו ע\"ד איזה דבר, ונעלם ממני כל החזיון.\nראיתיו ברור — עד להפליא.\nבאיזה עיר או מקום הי' זה — א\"י<sup data-n=\"579\">13</sup>.\nפני אחיך לא ראיתי. כובעו הי' מוטה מעט הצדה, ולעס בשפתיו. א\"י אם פפירוסה, צפרניו, או איזה דבר אחר.\nזהו פעם הב' שרואה אני את אאדנ\"ע אחרי החתונה<sup data-n=\"580\">14</sup>.\nבפעם הא' הייתי ג\"כ לבוש בהטעל, אבל אז לא אמר לי מז\"ט. ההטל היא של אאזנ\"ע<sup data-n=\"581\">15</sup>, חפצתי ללבוש כובע של אאדנ\"ע. אבל. . . כך הוא הדבר שלבשתי את של אאזנ\"ע.\nבפעם הא' — לא דבר דא\"ח. הי' כעין מסיבה. דבר ע\"ד נתיב לא ידעו עיט<sup data-n=\"582\">16</sup>.",[["572","7","בדרושי שחורה אני ונאוה (בלקו\"ת ועוד) מבואר ש\"שחורה אני\" קאי על ירידת הנשמה בגוף, שדוקא עי\"ז תתעלה בעילוי גדול יותר — \"ונאוה\"."],["573","8","אולי הכוונה שאף שיורדת רק הארת הנשמה בלבד, מ\"מ, נעשית העלי' גם בשרש ועצם הנשמה כמו שהיא למעלה (המשך ר\"ה תרפ\"ד ותש\"ט בתחלתו). או, אולי הכוונה במ\"ש \"ירידת הנשמה בגוף הוא עצם הנשמה\" דגם עצם הנשמה יורדת למטה, רק שהיא בהעלם, וע\"י עבודת הנסיונות מגלים עצם הנשמה. — ראה סה\"מ פר\"ת ע' קט [וכ\"ה בסה\"מ ה'ש\"ת ע' מ]: \"ירידת הנשמה למטה. . ה\"ז ירידה צורך עלי'. . כמו\"כ הו\"ע הנסיון בכדי שיתגלה בחי' יחידה שבנפש שישנה בנפש רק שהיא בהעלם, והלא העיקר הוא ההתגלות שז\"ע העבודה שיהי' התגלות הכחות והתגלות העצם. . וע\"ז הו\"ע הנסיון שיהי' התגלות בחי' יחידה שבנפש כו'\"."],["574","9","בהמשך ר\"ה הנ\"ל: \"והנה להבין כל זה כו'\", ומתחיל לבאר החילוק דספירת המלכות משאר הספירות, ששרשה מרדל\"א."],["575","10","ראה לקו\"ת ראה יט, סע\"ב: \"ותכלית ירידתה היא בשביל הנסיונות כו'\". ועד\"ז סהמ\"צ להצ\"צ קפה, סע\"ב. סה\"מ תרנ\"ז ע' נב. סה\"מ פר\"ת ע' קז. וראה תניא אגה\"ק סי\"א (קטז, ב): \"עיקר בריאת האדם בעוה\"ז הוא בשביל לנסותו בנסיונות אלו\"."],["576","11","ראה סה\"מ פר\"ת שם. תרפ\"ט ע' 206. וש\"נ."],["577","12","בסה\"מ פר\"ת שבהערה 8, מביא מ\"ש בב\"ר פנ\"ה, ב: \"היוצר הזה כשהוא בודק את הכבשן שלו אינו בודק את הכלים המרועעים. . ומה הוא בודק בקנקנים ברורים שאפילו הוא מקיש עליו כמה פעמים אינו שוברו, כך אין הקב\"ה מנסה את הרשעים אלא את הצדיקים, שנאמר (תהלים יא, ה) ה' צדיק יבחן\". וממשיך בסה\"מ פר\"ת שם: \"ועפ\"ז הוא מ\"ש הרמב\"ן ע\"פ [וירא כב, א] והאלקים נסה את אברהם וז\"ל ודע כי ה' צדיק יבחן, כשהוא יודע בצדיק שיעשה רצונו וחפץ להצדיקו יצוה אותו בנסיון כו' עכ\"ל. והיינו בכדי להצדיקו לגלות עצם פנימיות נקודת נפשו. וכמו כללות ענין ירידת הנשמה למטה. . בכדי שתבוא לבחי' רעו\"ד שזה יש בנשמה בעצם. . שיתגלה בחי' יחידה שבנפש שישנה בנפש רק שהיא בהעלם. . העיקר הוא ההתגלות כו'\"."],["568","3","כ\"ק אדמו\"ר מהורש\"ב נ\"ע."],["579","13","= איני יודע."],["580","14","של כ\"ק אדמו\"ר עם הרבנית הצדקנית מרת חי' מושקא נ\"ע זי\"ע בי\"ד כסלו שנה זו (תרפ\"ט)."],["581","15","כ\"ק אדמו\"ר מהר\"ש."],["582","16","איוב כח, ז. וראה זח\"ג רנו, סע\"ב. תקו\"ז ת\"ל (עג, ב). פרדס שער יב (שער הנתיבות) פ\"ג (נתיב הא'). ד\"ה וירד העיט באוה\"ת לך ח\"ד תשז, א ואילך. ד\"ה הנ\"ל תרנ\"ח (סה\"מ תרנ\"ח ע' יז ואילך). סה\"מ ה'ש\"ת ע' 10, ובהערת כ\"ק אדמו\"ר שם."]]],[4301600246,"צא מאיצטגנינות שלך<sup data-n=\"583\">17</sup>. שעיט שהוא הטבע. טבעי גם נתיב \"לא\" איני יודע. ופשיטא שנתיב הל\"ב לא יֵדַע<sup data-n=\"584\">18</sup>. ונתיב הל\"ב זהו ציצית<sup data-n=\"585\">19</sup>. ופעולתם נראה בזה שאין הולכים אל הזונה, טפחו לו ציציותיו<sup data-n=\"586\">20</sup>. קיין השגה העלפט נט וכו' ועוזרים לו הציציות. אברם אינו מוליד אברהם מוליד<sup data-n=\"587\">21</sup>. ששכל הנעלם<sup data-n=\"588\">22</sup> השגה בנפש לחודי' אינו מוליד אבל שכל הנעלם כשה\"א<sup data-n=\"589\">23</sup> — מחדו\"מ. הבפועל ממש — אז יש תולדות.\nאם<sup data-n=\"590\">24</sup> הי' לי מסנ\"פ על יהדות, איני חפץ לדבר עד\"ז. כי הרי כל דבור פועל וזהו נוגע לרבים. אבל עתה נצרך למס\"נ אויף דעם אויבערשטען, זאַך שטעלען. ע\"ע הי' ההו\"א מס\"נ נגד הגפ\"ו, ועתה. . . כי אין המצב יכול להשאר כמו שהוא עתה. . .\nכשבאו<sup data-n=\"591\">25</sup> לאסור את הרבי — (אדה\"ז. הכותב) — התחבא<sup data-n=\"592\">26</sup> בבית החיים. שאלו את הרבנית<sup data-n=\"593\">27</sup> אַיֵהו. וענתה שא\"י. הכוה על הלחי, והיפילו שן אחת. כשהלכו חזר אדה\"ז לביתו, ובלילה בא לשם שמואל מונקעס<sup data-n=\"594\">28</sup>. בדפקו על הדלת, שאלו אדה\"ז: מי שם? — שמואל! — ער דאַרף זיך אויסקלבען באַ נאַכט! — איך האָב ניט געואסט אַז באַם רבי'ן אז אויך דאָ נאַכט! — ווייסט, מען איז מיר געקומען אַרעסטרען? — איך ווייס. — עס אז דאָך אַ סַכנה. — וואָס זאָל איך אייך זאָגען. באַ מיר קומט אויס, אַז איר דאַרפט פארען. — עס אז דאָך אַ סַכנה. — אויב<sup data-n=\"595\">29</sup> איר זיינט אַ רבי, וועט אייך קיין קויל נט נעמען. און אויב ניט, זיינט",[["583","17","שבת קנו, ב. פרש\"י לך לך טו, ה. וראה ב\"ר פמ\"ד, יו\"ד."],["584","18","בדרושים שבהערה 16 מבואר ש\"נתיב לא ידעו עיט\" קאי על נתיב הל\"ב (משא\"כ נתיב ה\"לא\" ידעו עיט, כמרומז בכתוב \"נתיב לא — נתיב הל\"א — ידעו עיט\"), והחידוש כאן, שגם נתיב הל\"א לא ידעו עיט, ועפ\"ז מתפרשת תיבת \"לא\" בשתים: (א) נתיב ל\"א, (ב) \"לא (לשון שלילה) ידעו\"."],["585","19","כי, ל\"ב חוטי הציצית רומזים על ל\"ב נתיבות חכמה (בחיי ויקהל לה, לה. ר\"ח שער הקדושה פ\"ו (קמב, א). לקו\"ת קרח נב, ד ואילך. ובכ\"מ)."],["586","20","ראה מנחות מד, א."],["587","21","ב\"ר ופרש\"י שבהערה 17."],["588","22","ענינו של אברם (תו\"א ר\"פ לך לך. ובכ\"מ). — ולהעיר, שענין זה הובא ונתבאר בדרושי חתונה שנה זו (ד\"ה כל הנהנה פרק ט (סה\"מ תרפ\"ט ס\"ע 97 ואילך))."],["589","23","כ\"ה בכתי\"ק, ולכאורה הכוונה כשניתוסף ה\"א (אברהם), ששכל הנעלם (אברם) נמשך במחשבה דיבור ומעשה (ג' הקוין שבציור אות ה')."],["590","24","הבא לקמן הוא המשך הדברים שאמר רבינו, כנראה, באותו מעמד, אלא שלכאורה זהו ענין בפ\"ע (ולכן יש הפסק ריוח)."],["591","25","ראה גם לקמן ע' 150. שיחת י\"ט כסלו תרצ\"ב. שיחת ש\"פ חיי שרה תשי\"א (התוועדויות תשי\"א ח\"א ע' 93). בית רבי חלק א פרק טו (כח, א) ובהערות שם."],["592","26","בשיחת ש\"פ חיי שרה שבהערה הקודמת, שאדה\"ז התחבא תחילה באמרו, שיש לקיים מש\"נ (ישעי' כו, כ) \"חבי כמעט רגע עד יעבור זעם\". ובבית רבי שבהערה הקודמת: כוונת רבינו לא הי' לברוח לגמרי כאשר הסוף הוכיח. רק אמר שמתחלה צריך לברוח כמו ויברח יעקב. חבי כמעט רגע כו'. וע\"ד מארז\"ל ידחה מפני השעה כו' שבעת שמתעוררים דינים על האדם צריך להסתתר בזו השעה ואז נמתקים ממנו וכמארז\"ל בת דינא בטל דינא כו'."],["593","27","הרבנית הצדקנית מרת סטערנא."],["594","28","ראה אודותו — לקמן ע' 149 ואילך. ע' 259. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 80 הערה 59. וש\"נ."],["595","29","ראה גם שיחת כ' מנ\"א תש\"י (התוועדויות תש\"י ע' 171). שיחת ש\"פ חיי שרה שבהערה 25. שיחת שמחת בית השואבה תשכ\"ג."]]],[4301600247,"איר דאָך ווערט<sup data-n=\"596\">30</sup>. . . — אדה\"ז נשען בראשו על ידו. ואח\"כ אמר לש\"מ: צי דו ביסט גערעכט, ווייס איך ניט, נאר — גיי געזונט.\nבבוקר טבל א\"ע. קרא לאחיו מהרי\"ל<sup data-n=\"597\">31</sup>, אדמו\"ר האמצעי ולר' אברהם<sup data-n=\"598\">32</sup>, ויצוום שיצומו. ואמר להם שהיום \"יקחוהו\", בערב באו לתפסו. התפלל מנחה ואח\"כ נסעו.",[["596","30","כאן הושמטו תיבות אחדות."],["597","31","הרה\"ק ר' יהודה ליב מיאנאוויטש. בעמח\"ס שארית יהודה. ראה אודותו בית רבי חלק א פרק כד. רשימת כ\"ק אדמו\"ר בהוספות לספר שארית יהודה — הוצאת קה\"ת צח, א — וש\"נ."],["598","32","בנו השני (של אדה\"ז) — ר' חיים אברהם ראה אודותו לעיל ע' 33 הערה 30. וש\"נ.\nולהעיר, שבעת הברית מילה נקרא רק אברהם (ע\"ש ר' אברהם המלאך, וע\"ש זקנו אבי אמו) ומצד החולי, שסיבתו היתה התרעומת של זקנו שנקרא חיים אברהם, הוסיפו לו גם השם חיים (רשימת היומן של רבינו מיום כ' מ\"ח תרנ\"ו (סה\"מ תש\"ט ע' 90)).\nאבל ראה ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז) ע' 6 מה שסיפר הרה\"ק ר\"א מסטראשעלע: \"בהיותי על הברית מילה של הרה\"ק רח\"א שמעתי בשם רבנו הזקן אשר קרא שם בנו חיים אברהם — אברהם על שם רבו הרה\"ק ר\"א בן הרב המגיד. אבל אין חפצו במלאכים, הוא חפץ בעבודה של נשמה ולכן קראו חיים אברהם. אברהם אבינו נקרא תחלה אברם ואח\"כ אברהם, רבי בן רבי הגם שנק' מתחלה מ\"מ נקרא מלאך, אבל חיים אברהם הוא נשמה, חיים של אברהם\"."]]],[4301600248,"<h3>פורים תרפ\"ט</h3>\nדיבר הרבה אודות ביאת המשיח בקרוב, ואמר: באַ מיר איז איצט די ברכה איך זאָל בענטשן מיט אריכות ימים [...], וואָס איך ווייס אַז זיי ווילן די ברכה, ווייל געוויס בקרוב ממש וועט זיין ביאת המשיח, און טאַקע ניט דער משיח וואָס מיט קויפן ערד אין ארץ ישראל והדומה, רק דער משיח וואָס מיר וואַרטן, וואָס אַלע וועלן זיין דאָרטן און דער טאַטע אויך.\nואח\"כ בהמשך הדברים אמר לר' מרדכי דיסנער<sup data-n=\"599\">1</sup> שביקש ברכה: איך בענטש דיך און דיינע קינדער. דיינע קינדס קינדער וועט שוין דער טאַטע בענטשן, און טאַקע בעוה\"ז.\nיעדערער זאָל זיך דערמאָנען ווי ער איז געווען אין די 10 מינוט וואָס ער איז געשטאַנען באַ דעם טאַטן, און ווי איז ער איצט, און אַז ער וועט זיך דאַרפן ווייזן פאַר'ן טאַטן.\nואח\"כ דיבר ההפרש שבין חנוכה לפורים, איך שפורים הי' המס\"נ באופן נעלה, חנוכה האָט מען מלחמה געהאַלטן<sup data-n=\"600\">2</sup>, מתתי' ובניו זיינען געגאנגען אויף מס\"נ אָבער זיי האָבן אויך מלחמה געהאַלטן. פורים האָט מרדכי גאָרניט געטאָן, מ'איז אַ יאָר געשטאַנען אין",[["599","1","ר' מרדכי חפץ מדיסנא. שו\"ב בריגא. ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 18 ובהערה 39. נזכר לעיל ע' 41. וש\"נ."],["600","2","ראה שבת כא, ב. מגילת אנטיוכס. שמו\"ר פט\"ו, ו. רמב\"ם הל' חנוכה פ\"ג ה\"א­ב."]]],[4301600249,"מס\"נ<sup data-n=\"601\">3</sup>. וואָס האָט ער אָבער געטאָן — קיבץ כ\"ב אלף תלמידים<sup data-n=\"602\">4</sup>, און וואָס האָט ער געלערנט — הלכות קמיצה<sup data-n=\"603\">5</sup>, וואָס דאָס איז אַ חוקה ניט על פי שכל (אין דעם איז אויך פאַראַן שכל ווי ס'דאַרף זיין די מצוה כו'), וזה הי' המס\"נ שלהם שזה הנחת עצמותו לגמרי.\nאחד התחיל לשאול ולומר לו מה שמבין הכוונה בזה (ומובן שאמר לפי הבנתו). ואמר: אַ טאַטנס אַ קינד וואָס האָט אונטער זיך 8 עטאַזשן<sup data-n=\"604\">6</sup> — אפילו ער זאָל אַליין גאָר ניט צוגעבן — פאַרשטייט אַנדערש, און בפרט כו'.\nבעת איך בין געזעסן<sup data-n=\"605\">7</sup> אין ג.פ.או. (ל\"ע) איז מיר געווען בעסער איידער איצט. בשעת מען איז מיר געקומען פאָטאָגראַפירן, והי' ביום הש\"ק, והייתי מעוטף בהטלית, און בעת מען איז צו מיר צוגעגאַנגען זאָגן אַז מ'וויל מיר פאָטאָגראַפירן, האָב איך אַ מאַך געטאָן מיטן האַנט<sup data-n=\"606\">8</sup>.\nיעמאָלט איז באַ מיר געווען דער טאַטע און דער זיידע און האָט געזאָגט דער מאמר: הודו להוי' כי טוב. און יורדי הים באניות<sup data-n=\"607\">9</sup>, און. . . <sup data-n=\"608\">10</sup>.\nאון בכלל בין איך דאָרטן געווען אַ טפח העכער<sup data-n=\"609\">11</sup> פון דער ערד.\n(נתן לאחד — אַ בעה\"ב אַ געפּוצטער — חתיכת דג משלו בידו הק', ואמר:) איר מעגט נעמען פון מיין האַנט, איך האָב זיך געוואַשן.",[["601","3","כ\"ה בתו\"א מגילת אסתר צז, א: מסרו עצמן למות כל השנה כולה. וראה לעיל ע' 14 הערה 27."],["602","4","אסת\"ר פ\"ח, ז. פ\"ט, ד. פ\"י, ד. וראה סה\"מ תרפ\"ז ע' קיב ואילך. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ס\"ע 119 ואילך. ספר השיחות קיץ ה'ש\"ת ע' 161."],["603","5","מגילה טז, א. אסת\"ר פ\"י שם. וראה ספר השיחות ספר השיחות תרצ\"ו — חורף ה'ש\"ת שם. ולהעיר מאגרות­קודש כ\"ק אדמו\"ר שליט\"א חי\"ח ע' רנז."],["604","6","שמונה קומות. אולי הכוונה לזה שרבינו הוא דור השמיני בדורות נשיאי תורת החסידות: הבעש\"ט, הרב המגיד וכו'. — ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 32."],["605","7","בשנת תרפ\"ז. בכ\"ז — ראה גם שיחת קיץ תרצ\"ד (רשימות כ\"ק אדמו\"ר — מארינבאד תרצ\"ד)."],["606","8","כ\"ק אדמו\"ר סיפר סיפור זה בשיחת י\"ב תמוז תשי\"א, ולאח\"ז הוסיף:\nמאורע זה הוא דבר פלא, וע\"פ שכל אין לו מקום לגמרי:\nאנשים אלה — אינם צריכים להתפעל מ\"טלית\", ואינם מתפעלים מ\"טלית\", ואדרבה: הם אסרו את הרבי בגלל היותו רב, רבי, שמתכסה בטלית!. . . אלא מאי — מצד העצמיות של הרבי (שעמד בביטול עצמי ובתוקף עצמי) נפעל גם במציאות כזו שהניצוץ האלקי שבה נסתר ונעלם לגמרי עד לאופן שחתיכה נעשית נבילה<sup data-n=\"e26\">*</sup> (אלא שאעפ\"כ נשארה מציאות הני­צוץ)<sup data-n=\"e27\">**</sup>, שכאשר מציאות זו רואה עצמות ומהות*<sup data-n=\"e28\">***</sup> כפי שיושב מעוטף בטלית מעל הראש. . . אזי אין אצלם נתינת מקום כלל (לא מצד השכל, כיון שאצלם גופא הרי זה ענין שאינו שייך לשכל) לנסות לבלבל, כיון שכאן מתבטלת מציאותם (זייער מציאות ווערט דא אויס מציאות), ולא זו בלבד שאינם מבלבלים, אלא עוד זאת, שמסתלקים מהמקום, בראותם שאין להם מה לעשות כאן (מ'האט דא ניט וואס צוטאן)!. . .\nוראה גם שיחת י\"ב תמוז תשכ\"א."],["607","9","ע\"ד מאמר יורדי הים באניות — ראה גם ספר השיחות: תר\"פ­תרפ\"ז ס\"ע 174; תרצ\"ו — חורף ה'ש\"ת ע' 13."],["608","10","הזכיר עוד מאמר שלישי, ואינני זוכר. — המניח."],["609","11","ראה לעיל ע' 13 הערה 14."],["e26","*","חולין ק, א. קח, א. סה\"מ תרס\"ה ע' קד."],["e27","**","סה\"מ תרס\"ה שם. וראה סה\"מ עת\"ר ע' קג ואילך. המשך תער\"ב ח\"ב ע' תשע."],["e28","***","ראה לקוטי שיחות חלק ב ע' 511­510."]]],[4301600250,"ופנה אל כולנו ואמר: הלוואי וואָלט באַ אייך געווען די הענט נאָך מקוה פונקט ווי באַ מיר פאַר מקוה.\nכ\"ק אדמו\"ר אמר לאחד: וואָס זאָגסטו ניט קיין לחיים, והשיב: איך וויל לאָזן איך זאָל קענען הערן חסידות, ואמר כ\"ק אדמו\"ר: דו רעכנסט אַז עס וועט זיין חסידות? אַז איך דאַרף זאָגן חסידות דאַרף מיר דער טאַטע זאָגן: זאָלסט זאָגן דעם מאמר. יעמאָלט ווייס איך אַז איך וועל פּאַקן אַ אידן<sup data-n=\"610\">12</sup>. און אַז אָן דעם קען זיין השכלה, קען זיין התקשרות, קיין אידן וועל איך שוין ניט פּאַקן<sup data-n=\"610\">12</sup> — וואָס דאָס דאַרף דאָך זיין דער עיקר פון זאָגן חסידות. דער וואָס זאָגט חסידות צוליב השכלה זאָל שטום ווערן (ח\"ו) ווער עס הערט חסידות צוליב השכלה זאָל טויב ווערן (ח\"ו).",[["610","12","ראה שיחת ש\"פ נצבים תש\"י (התוועדויות ע' 216): כ\"ק מו\"ח אדמו\"ר אמר פעם שיש הפרש בין אמירת מאמר שנתעצם עמו, האט ער געוואוסט אז מיט דעם מאמר וועט ער כאפן א אידן. . . , לאמירת מאמר שלא נתעצם עמו, שאף שאמר גם מאמר זה, לא הי' בזה הענין של כאפן א אידן."],["610","12","ראה שיחת ש\"פ נצבים תש\"י (התוועדויות ע' 216): כ\"ק מו\"ח אדמו\"ר אמר פעם שיש הפרש בין אמירת מאמר שנתעצם עמו, האט ער געוואוסט אז מיט דעם מאמר וועט ער כאפן א אידן. . . , לאמירת מאמר שלא נתעצם עמו, שאף שאמר גם מאמר זה, לא הי' בזה הענין של כאפן א אידן."]]],[4301600251,"<h3>ה' אייר, תרפ\"ט<sup data-n=\"612\">1</sup></h3>\nישנם המתאוננים לאמר: שנופלים להם מחשבות רעות שאינם לפי ערך מהותם כלל, ויש להם צער גדול מזה, ונופלים ברוחם ומפריע אותם גם בעבודתם הקטנה, כלומר שמפני צערם ונמיכות רוחם אינם יכולים ללמוד ולהתפלל ובפרט לעסוק באיזה עבודה.\nהנה בכגון דא עצת תורת החסידות הוא, אל ישים לבו לזה, ואל יפול לב אדם עליו, בטעם כי אמרו רז\"ל<sup data-n=\"613\">2</sup> משביעין אותו תהי צדיק, ומבואר בדא\"ח<sup data-n=\"614\">3</sup> דהשבעה הוא ענין השובע, שמשביעין ונותנים כח בהנה\"א על הנה\"ב לזככו ולבררו, עד אשר גם הוא יבוא לאהבה את הוי' והוא ענין ואהבת את הוי' אלקיך בכל לבבך<sup data-n=\"615\">4</sup>, בשני יצריך<sup data-n=\"616\">5</sup> דגם הנה\"ב בא לאהבה את הוי'.\nוהנה הדרכים והאופנים לגלות כח זה שבנה\"א להתגבר על נה\"ב אם שהעיקר הוא ע\"י עבודה במוח ולב, שהוא ענין לימוד דא\"ח והתבוננות בהענין להבינו כל חד לפום שיעורא דילי' ולהביאו בפועל בעבודה דתפלה שהוא ענין הקרבן בפרטי המדרי' הנה\"ב שור, כשב, עז (כמבואר בקונטרס התפלה, תר\"ס<sup data-n=\"617\">6</sup>) שאז בעת התפלה הוא זמן מסוגל להתעורר ברחמים על נפשו, ומתחנן לפני הוי' כי הוא ית' יחוס וירחם.\nאמנם לא כל אדם ביכלתו להגיע לזה מפני סיבות שונות, ישנו מבוא",[["612","1","כ\"ק אדמו\"ר מציין לרשימה זו במפתח ענינים למאמרי כ\"ק אדמו\"ר מהוריי\"צ נ\"ע — ערך מחשבות זרות: מכ' ה' אייר פ\"ט."],["613","2","נדה ל, ב. תניא פ\"א."],["614","3","קיצורים והערות לתניא ס\"ע נז ואילך. ע' קסה ואילך (בהוצאת קה\"ת, תשמ\"ט). סה\"מ תרח\"ץ ע' רלה ואילך. ד\"ה פדה בשלום תש\"כ (סה\"מ תש\"כ ע' 39 ואילך)."],["615","4","ואתחנן ו, ה."],["616","5","משנה ברכות נד, א. ספרי ורש\"י עה\"פ."],["617","6","פרק ח (ע' 20). וראה גם ספר השיחות תורת שלום ע' 10. סה\"מ עת\"ר ע' רלט. תרפ\"ג ע' קעא. ה'שי\"ת ע' 113. לקמן ע' 73."]]],[4301600252,"והקדמה ע\"י עבודה בפועל, לפעול ולעשות טוב. והם בשני תנועות: א) הגדרה, ב) פעולה, ושניהם צריכים להיות בקבלת עול.\nהקבלת עול היא דבר השוה לכל נפש<sup data-n=\"618\">7</sup>, ובכל ענין, כי יהי' מי שיהי' ומה שיהי' גם הנעלה ביותר בהשגה והבנה טובה, גם הפשוט בידיעה והבינוני הנה לכולם כאחד הקבלת עול מעלה ומגביה למדרי' ומעמידו על בסיס האמת.\nכן הקבלת עול הוא הנותן את פריו הטוב והמעולה בכל דבר, הן בלימוד התורה הנגלית ודא\"ח, הן בקיום המצות בעשה ול\"ת, והן במדות והנהגה.\nהקבלת עול הוא המסירה ונתינה בכח ועוז ובתוקף גדול, מבלי התחשב עם כל דבר בעולם, הוא ההחלט הגמור להיות דוקא כמו שהסכים בעצמו, ולא בשום אופן אחר, והוא נקודת הקשה עורף למעליותא, שהוא הנצב היינו הבית יד של להט להב נקודת היהדות.\nנקודה זו ישנה בכל אחד מישראל, והיא בחי' יחידה שבנפש, דחמשה שמות נקראו לה<sup data-n=\"619\">8</sup>, נפש (מעשה) רוח (מדות דבור) נשמה (השגה הבנה, מוחין כח פנימי אור בכלי) חי' (רצון, מקיף) יחידה (עונג, מקיף דמקיף)<sup data-n=\"620\">9</sup> ונקראת יחידה יחיד הוי'<sup data-n=\"621\">10</sup>, התקשרות עצם בעצם, עצם הנשמה בעצמות א\"ס ב\"ה, וכמאמר<sup data-n=\"622\">11</sup> כי אתה אבינו, כמשל התקשרות הבן בהאב שהוא עצמותו.\nוהעומק רום של היחידה מתגלה בהעומק תחת של העשי' בפועל וכמאמר<sup data-n=\"623\">12</sup> חבוקה ודבוקה בך טוענת עולך יחידה ליחדך, דלהיות דעצם הנשמה היא חבוקה ודבוקה בך, לזאת היא טוענת (מקבלת) עולך (עול התורה והמצות, במס\"נ עד כי) יחידה ליחדך במס\"נ בכח ובפועל.\nהפועל הוא בשני אופנים כוללים: א) ההגדרה. ב) פעולה.\nא) ההגדרה.\nענינו לכבוש רצונותיו ותאוותיו בכל אשר יחפוץ ויתאווה להם בכל הענינים החומרים והיינו לשלול את החומריות והגסות הן במדות מחשבה דבור והן במעשה, וגם באכילה ושתי'.\nב) פעולה.\nענינו לעשות ולקיים בפועל ממש לקבוע זמני לימוד בנגלה ודא\"ח, כל אחד לפי מהותו, לקיים המצות עשה וזהירות שמירת הל\"ת.\nוהכל בדרך קבלת עול בכפי' והכרח דוקא, ובכן אלו שנופלים להם מחשבות לא טובות, או גם רעות, ידעו אשר רעמי רעש הכלי תותח של השונא הוא היצה\"ר המפיל מחשבות הללו להוריד ח\"ו את האדם ולהשפיל אותו, לאמר לו, האם גם אתה חפץ לגשת אל הקדש.\nאשר על כן יאזרו בגבורה ותעצומות עוז לדחות את המחשבות הללו",[["618","7","קונטרס התפלה פרק טו (ע' 29 ואילך). וראה תניא רפמ\"א. קונטרס העבודה פ\"ב."],["619","8","ב\"ר פי\"ד, ט. דב\"ר פ\"ב, לז. בכמה מקומות (ודפוסים) הוא בשינוי סדר. אבל כ\"ה (כבפנים — נרנח\"י) בעץ חיים שער מב (שער דרושי אבי\"ע) בתחלתו. שער הגלגולים בתחלתו. ובכ\"מ."],["620","9","ראה סה\"מ תרס\"ח ע' קמג. פר\"ת ע' רעט. ד\"ה והי' כאשר ירים משה תש\"ל (סה\"מ תש\"ל ע' 180 ואילך). ובכ\"מ."],["621","10","ראה גם סה\"מ תרצ\"ו ע' 57, ובהנסמן שם הערה 30."],["622","11","ישעי' סג, טז."],["623","12","סדר הושענות (יום ג')."]]],[4301600253,"להרחיקם בתכלית הריחוק, ויתחזקו בכל המיני חיזוק להתקרב אל האור כי טוב, ומפתן המבוא הלזה הוא השקידה בפעולת התיסדות שיעורי לימוד, וכתיב<sup data-n=\"624\">13</sup> וצדקה תרומם כו' דהצדקה והחסד שהאדם עושה עם זולתו בזה שמקרבו אל הפועל טוב אשר ראשיתו\nהוא הלימוד בשיעור לרבים היא פועלת ישועות בנפשו שעולה בעילוי אחר עילוי.",[["624","13","משלי יד, לד. וראה תו\"א בראשית א, ב. ועם הגהות — אוה\"ת שם ח\"ו תתרכו, ב ואילך."]]],[4301600254,"<h3>שקידה</h3>\n<b>תרפ\"ט<sup data-n=\"625\">1</sup></b>\nבענין השקידה הרבה טועים לחשוב כי השקידה היא רק בזמן בלבד, וע\"פ חשבון דשכל אנושי כן הוא כי ט\"ו הוא יותר מכמו י\"ב, וי\"ז הוא מרובה מכמו ט\"ו.\nאבל אמת הגמור הוא כי השקידה האמיתית היא ברוחניות, היינו המסירה והנתינה, די איבערגעגעבענקייט אל ענין הלימוד. והמסירה ונתינה היא בדרך ממילא שומרת את הזמן.\nובעומק יותר ענין השקידה הוא החיות בהלימוד די לעבעדיקייט אין דעם, כמאמר העולם ער לעבט אין דעם, או כמו שאומרים דאָס איז זיין לעבן, והיינו דגם שהוא בזמן לא מרובה, אבל הוא בחיות, ניט נאָר די צייט איז עיקר נאָר די לעבעדיקייט — דער אינטערעס דאָס איז דער עיקר.\nזאת אומרת אשר השקידה האמיתית היא מסודרה באופן כזה שגם זמני המנוחה הנק' אָפּרוהען ושמירת הסדר באכילה ושתי' המה נכנסים בענין השקידה.\nוכן הוא עפ\"י דרכי העבודה של תורת החסידות, אשר נודע כי תורת החסידות אינה ענין של מפלגה<sup data-n=\"626\">2</sup> כמו שתופסים העולם לאמר זה חסיד וזה מנגד.\nאלא החסידות היא פנימית התורה וחיותה, וכוללת שני ענינים עיקרים<sup data-n=\"627\">3</sup>: א) הבנת כל הלכה בשרשה ומקורה העצמי ברוחניות, היינו בספירות ומדריגות בכל עולם ועולם לפי ענינו כמבואר בדא\"ח (ונזכר בד\"ה ויעבר, פקודי רפ\"ט<sup data-n=\"628\">4</sup>). ב) ענינו בעבודה, היינו דמכל דבר הלכה הגם שהיא חכמה ושכל אלקי, ודין התורה, מ\"מ צריכים למצוא מזה ענין בעבודה בהנהגת האדם בחיי עולם זה<sup data-n=\"629\">5</sup>.",[["625","1","רשימה זו הגיע לידינו עם הגהות בכי\"ק רבינו. ובראשה: שיחה.\nכ\"ק אדמו\"ר מציין לרשימה זו במפתח ענינים למאמרי כ\"ק אדמו\"ר מהוריי\"צ נ\"ע — ערך שקידה: מכ' כללי בקופיר פ\"ט."],["626","2","ראה גם אגרות­קודש ח\"ח ע' תרי. ח\"י ע' דש. לקמן ע' 163."],["627","3","הועתק ב\"היום יום\" יא אדר שני (בשינויים)."],["628","4","נדפס בסה\"מ תרפ\"ט ע' 153 ואילך."],["629","5","ב\"היום יום\" שם: ב) הבנת ענין כל הלכה בעבודה, היינו שהגם שהיא חכמה ושכל אלקי ודין התורה, מ\"מ צריך למצוא בזה ענין בעבודה בהנהגת האדם בחיי עולם זה."]]],[4301600255,"ועל דרך דוגמא בענין הקרבנות, כתיב אדם<sup data-n=\"630\">6</sup> כי יקריב מכם קרבן לה', שפירושו הוא אדם כי יקריב, בכדי דער מענטש זאָל ווערן נענטער צו ג­טליכקייט, מכם קרבן להוי', פון אייך אַליין איז דאָס אָפּהיינגיק איר זאָלט ווערן נעענטער לה', דורכדעם וואָס איר וועט מקריב זיין אייער שור וכו' דאָס הייסט דעם יצר הרע (כמבואר בקונט' התפלה תר\"ס<sup data-n=\"631\">7</sup>).\nובזה יובן מה שהקשו המפרשים הלא רוב הקרבנות באים על החטא, וא\"כ מה מועיל הבאת הקרבן מן הבהמה, אלא שהכוונה העיקרית היא<sup data-n=\"632\">8</sup>, דמי שמביא הקרבן צריך לידע אשר לפי חטאיו הי' ראוי שיעשו בו כל המעשים שעושים עם הבהמה, אלא שבחסדי השי\"ת ובחמלתו הבהמה היא חליפתו.\nוזהו ענין הוידוי דברים שצריך להיות בהובאת הקרבן<sup data-n=\"633\">9</sup>, והוא התשובה והחרטה על כל הענינים הלא טובים שעשה, אשר עי\"ז הוא עוזב את רצונותיו הקודמים, וכתיב<sup data-n=\"634\">10</sup> ומודה ועוזב ירוחם.\nוכמו שהוא בענין הקרבנות הנה כן הוא בכל דבר הלכה שלומדים צריכים למצוא ענין טוב בזה בהנוגע לבירור המדות.\nולזאת חיי האדם בהנהגותיו היומים במדות בני אדם, באכילה ושתי' ושמירת הבריאות, בחיי המשפחה בחינוך אנשי ביתו בניו ובנותיו ובאהבת רעים ואופני הלימודים וסדרם כאשר הם ע\"פ תורת החסידות הם חיים אמיתים, אשר הם יסוד לחיים נעימים נצחיים בעולמות העליונים.\nדהנה כתיב<sup data-n=\"635\">11</sup> נעשה אדם בצלמנו כדמותנו, שהאדם שלמטה הוא בצלם ודמות אדם העליון, וכתיב<sup data-n=\"636\">12</sup> זאת התורה אדם, דתומ\"צ הם בדוגמת ציור האדם שהוא נפש ורמ\"ח אברים ושס\"ה גידים, כמו\"כ בתומ\"צ, תורה היא שכל אלקי, רמ\"ח פיקודין רמ\"ח אברים<sup data-n=\"637\">13</sup>, שס\"ה לא תעשה שס\"ה גידים<sup data-n=\"638\">14</sup>, וענינם מבואר במקומם בדא\"ח.\nהאדם מורכב מנפש וגוף, דהגוף לבדו נקרא בשר אדם, והנפש לבדה נקראת נשמת אדם<sup data-n=\"639\">15</sup>, והגם שהנשמה קודם התלבשותה בגוף יש לה כל הכוחות והחושים דהשגה ראי' ושמיעה, אבל הם רק ברוחניות, והגוף אף שיש בו כל הכלים אל ההשגה וההבנה, ראי' שמיעה, אבל הם מתים וכאילו אינם. ורק בהתחברות הנשמה והגוף אז הוא אדם חי, בעל ידיעה והשגה, רואה שומע ומדבר.\nוכשם שהוא באדם החיצון, כלומר",[["630","6","ויקרא א, ב. וראה ד\"ה תשורי מראש אמנה שנה זו (סה\"מ תרפ\"ט ע' 209). וש\"נ. סה\"מ תרצ\"ו ע' 117. תרצ\"ז ס\"ע 201 ואילך. תרח\"ץ ע' רלב. תש\"ט ע' 28 (השני)."],["631","7","פרק ח (ע' 20). וראה לעיל ע' 70 ובהערה 6."],["632","8","ראה רמב\"ן ויקרא א, ט. רקאנטי ויקרא שם, ג. ועוד. וראה רש\"י וירא כב, יג ד\"ה תחת בנו (מב\"ר פנ\"ו, ט)."],["633","9","ראה רמב\"ם ריש הל' תשובה. וראה גם זח\"ג רמ, א."],["634","10","משלי כח, יג."],["635","11","בראשית א, כו. וראה של\"ה ט, א. י, א. לקו\"ת ויקרא ד, ב. ובכ\"מ."],["636","12","חוקת יט, יד. וראה זוהר ח\"ב קיז, ריש ע\"ב. ח\"ג כט, ב (ברע\"מ). תו\"א ר\"פ תרומה (עט, ג). לקו\"ת ויקרא ג, א. ובכ\"מ."],["637","13","מכות כג, סע\"ב. זוהר ח\"א קע, ב."],["638","14","זוהר שם."],["639","15","ושניהם יחד דוקא נק' \"אדם\" — ראה סה\"מ תרנ\"ג ע' רלה. הגהות כ\"ק אדמו\"ר מהורש\"ב נ\"ע לד\"ה פתח אליהו שבתו\"א — תרנ\"ח (ע' ב). סה\"מ תרפ\"ו ע' ד. ע' קפח."]]],[4301600256,"באדם הגשמי החיוני החי על פני האדמה ונקרא בשם מדבר, כן הוא באדם הפנימי, שהוא האדם הרוחני החי על פני האדמה עפ\"י התורה והמצוה.\nמצוה בלא כוונה כגוף בלא נשמה<sup data-n=\"640\">16</sup>, אשר מזה מובן דכוונה בלא קיום המצוה בפועל הוא כנשמה בלא גוף, ומצוה בכוונה הוא בחיות פנימי באדם החי<sup data-n=\"641\">17</sup>.\nוהתורה נקראת עוז<sup data-n=\"642\">18</sup> שנותנת עוז להאדם<sup data-n=\"643\">19</sup> הלומד בתורה ע\"מ לשמור לעשות ולקיים, כי העיקר ותכלית הוא הקיום בפועל, וכמאמר<sup data-n=\"644\">20</sup> גדול תלמוד שמביא לידי מעשה.",[["640","16","לקוטי תורה להאריז\"ל פ' עקב. וראה תניא פל\"ח (נ, א)."],["641","17","ראה גם סה\"מ תרפ\"ו ע' ד."],["642","18","ראה שהש\"ר פ\"א, ג (א). פ\"ב, ג (ג). מדרש תהלים עה\"פ ח, ג. וראה זבחים קטז, סע\"א. ויק\"ר פל\"א, ה. יל\"ש בשלח רמז רמד."],["643","19","תו\"א יתרו סז, סע\"א ואילך. ובכ\"מ."],["644","20","קידושין מ, ב."]]],[4301600257,"<h3>י\"ג תמוז, תרפ\"ט</h3>\n<b>קטע</b>\nניט מיט בחירה ורצון בין איך אַוועק געפאָרן פון רוסלאַנד<sup data-n=\"645\">1</sup>, און ניט מיט בחירה ורצון בין איך דאָ, און ניט מיט בחירה ורצון מאַך איך איצטער די נסיעה<sup data-n=\"646\">2</sup>.",[["645","1","ראה לעיל ע' 4 ובהערה 6."],["646","2","לארץ הקודש ולארצות הברית. ראה לעיל ב\"מבוא\" ע' יח ואילך."]]],[4301600258,"<h3>כ\"ב תמוז, תרפ\"ט<sup data-n=\"647\">1</sup></h3>\n<b>על גבול הלטבי</b>\nכ\"ק אדמו\"ר אמר בשם זקנו מהר\"ש נ\"ע ששמע בשם אדמו\"ר הזקן, שבעת הפרידה צריך לומר יברכך וכו', ואח\"כ כשנראה במעוף עין צ\"ל ג\"כ יברכך וכו'.",[["647","1","ביום זה התחיל רבינו את מסעו המפורסם לארץ הקודש, ואח\"כ לארצות הברית. — ראה לעיל ב\"מבוא\" ע' יח ואילך."]]],[4301600259,"<h3>אור ליום ד' ט' באב תרפ\"ט<sup data-n=\"648\">1</sup></h3>\nרושם רע ומדאיב עשה עלי לילה זה, הטיול של הצעירים וצעירות בקול רעש של שמחה והמולה, רבים קונים מים ופירות, אוכלים ושותים ומטיילים וכו'.\nנזכרתי אשר בהיותי ילד קטן בן שש או בן שבע<sup data-n=\"649\">2</sup> [הי'] אז בליובאוויטש ר' לוי יצחק סלאנים<sup data-n=\"650\">3</sup> ז\"ל מחברון, שאלתיו איך",[["648","1","מיומנו של רבינו."],["649","2","בשנות תרמ\"ו­תרמ\"ז."],["650","3","במק\"א כותב רבינו: \"אנכי ראיתי את הרל\"י רק פעם אחת בבואו אחר הסתלקותו של הוד כ\"ק אאזמו\"ר הרה\"ק מוהר\"ש זצוקללה\"ה נבג\"מ זי\"ע, בערך בשנת תרמ\"ד או תרמ\"ה, כי ישב אז בליובאוויטש משך איזה חדשים\" (\"יגלה אור\" למכתבי אדמו\"ר מהורש\"ב אל הרה\"ג ר' שניאור זלמן סלאנים — כפ\"ח גליון 899 ע' 45 ואילך).\nהר\"ר שניאור זלמן בן הרה\"ח ר' מרדכי דוב — אחיו של ר' לוי יצחק — סלאנים הגיע לליובאוויטש בקיץ תרמ\"ה וחזר לאה\"ק אחרי חג הפסח תרמ\"ו (\"יגלה אור\" שם). ובמק\"א איתא דהר\"ר שניאור זלמן הי' בליובאוויטש בשנת תרמ\"ז (רשימת היומן של רבינו יו\"ד כסלו תרס\"ז — \"התמים\" חוב' ב' ע' עט [פז, א]. סה\"ש תרצ\"ו­חורף ה'ש\"ת ע' 260)."]]],[4301600260,"הוא ט' באב בירושלים, וענה לי, ט' באב בירושלים כמו י\"ט כסלו בליובאוויטש. לפי הבנתי אז הקטנה כי כשם שי\"ט כסלו בליובאוויטש הוא שמחה גדולה כן ט' באב בירושלים הוא אבילות גדולה, ינחמנו ה' בגוא\"צ בב\"א. אבל עתה הנני רואה כי טעיתי, כי ט' באב בירושלים הוא ר\"ל כמו י\"ט כסלו בליובאוויטש כפשוטו ואוי לעינים שרואות כך, והשי\"ת ינחמנו וישלח לנו גואל צדק בב\"א ויהפוך לשמחה של תורה ומצוה."],[4301600261,"<h3>מוצאי תשעה באב — יהפך לשמחה — תרפ\"ט<sup data-n=\"651\">1</sup></h3>\n<b>בישיבת \"תורת אמת\" בעה\"ק ירושלים ת\"ו</b>\nאיך וויל פאַרברענגען מיט די תלמידים — איז אַ הקדמה כללית צו דעם:\nהגם \"תורת אמת\" איז דאָך נתיסד מכבר בשנת תער\"ב<sup data-n=\"652\">2</sup> ובתחלת ההתיסדות האָט מען געשיקט תלמידי \"תומכי­תמימים\" להיות כזריעה ונטיעה, מ'זאָל וויסן דכוונת ההתיסדות היא להאיר אור, און ב\"ה עס איז שוין דאָ פון \"תורת אמת\" משגיחים ומשפיעים, מ\"מ געפין איך פאַר נויטיק אין דעם ערשטן מאָל זעהן זיך מיט אייך, צו מבאר זיין בכלל די כוונה פון התיסדות \"תומכי­תמימים\" — איך וועל איבערזאָגן דברי הרב ממש.\nזונטאָג ט\"ו אלול תרנ\"ז, האָט דער טאַטע (אאמו\"ר) אַריין גערופן עטלעכע חסידישע בע\"ב<sup data-n=\"653\">3</sup> (דאָס איז געוועזן בזמן חתונתי<sup data-n=\"654\">4</sup>) וועגן אַ התיסדות פון אַ ישיבה, האָט ער געזאָגט:\nדי התיסדות הישיבה איז ניט נאָר צוליב תורה, קיין תורה פעלט ניט ב\"ה, עס איז דאָ אַ סאך ישיבות<sup data-n=\"655\">5</sup>, און בכלל אין דעם געגענט פעלט ניט קיין תורה, נאָר די כוונה איז להאיר אור, מ'זאָל לערנען נגלה און לערנען חסידות, און דאָס זאָל זיין אויסגעקאָכט צוזאַמען<sup data-n=\"656\">6</sup>,",[["651","1","בשעה תשע מוצאי תשעה באב נסע רבינו לישיבת \"תורת אמת\"."],["652","2","ראה אגרות­קודש אדמו\"ר מהורש\"ב ח\"ב ע' תקצז­תקצח. ספר תולדות חב\"ד בארץ הקודש ע' קפא ואילך. וש\"נ."],["653","3","ראה גם אגרות­קודש ח\"א ע' שא. ח\"י ע' שסה."],["654","4","החופה הייתה ביום ועש\"ק יג אלול, וביום א טו אלול הי' סעודת החופה — ראה אגרות קודש ח\"י שם. ספר השיחות תש\"א ע' 104. ועוד."],["655","5","ראה קונטרס עץ החיים פרק כב: יסוד אגודתינו אינו להגדיל ולהרחיב עסק התורה הנגלית כ\"א זאת היא תכלית יסוד אגודתינו, אשר הבחורים העוסקים בתורה הנגלית יהיו יהודים (אידען) יראים ושלימים עם ה' ותורתו. וראה ספר השיחות תר\"פ­תרפ\"ז ע' 99. לקוטי שיחות חלק יד ע' 316 ואילך."],["656","6","ראה שיחת כ\"ק אדמו\"ר מהורש\"ב נ\"ע שמח\"ת תרנ\"ט בשעת הקפות — בקשר לקריאת שם הישיבה \"תומכי תמימים\" — נעתקה באגרות­קודש ח\"י ע' שסח."]]],[4301600262,"מ'זאָל האָבן מיט וואָס צו גיין אין מאַרק, איך מיין ניט למעט בדמות שאר הישיבות, נאָר אין דער התיסדות איז די כוונה להאיר אור.\nובעוד פעם שפּעטער אמר אאמו\"ר: די פנימי' פון ברכת התורה איז ווי ס'שטייט ונתן לנו תורת אמת וחיי עולם נטע בתוכנו, תורה זאָל מאיר זיין אין עולם און מאַכען פון עולם — תורה, מאיר זיין אין עולם און מאַכען פון עולם — אלקות.\nדי \"תמימים\" אין רוסלאנד וואָס זיינען זינט התיסדות \"תומכי­תמימים\" שוין עטלעכע און דרייסיג יאָר, זעהט מען יעצט זייערע כחות אין תוקף מס\"נ על התורה, הגם אַז מ'הויבט זיך אָן דערמאָנען אויף זייער מצב דוחק ולחץ הן בכותלי ביהמד\"ר און הן בכלל אין רוסלאַנד איז זייער מצב מחריב די האַרץ, אָבער דאָס איז דאָך אַלץ אַז מ'שטייט למטה אויף דער ערד. אָבער אַז מ'הויבט זיך אויף אַ טפח העכער<sup data-n=\"657\">*6</sup> זעט מען אַז מצד די כוונה פון ירידת הנשמה בגוף און ירידת התורה אין בריאת העולמות בכלל — איז זייער תוקף במס\"נ אַ ענין גדול.\nכאָטש זייערע יסורים איז דאָך זייער שווער צו טראָגן, זייער מיעוט חלב­ודם, ניט קיין געגעסענע ניט קיין אויסגעשלאָפענע, אָבער דאָס אַלץ איז אַז מ'איז אויף דער ערד, אָבער אַז מ'הויבט זיך אויף אַ טפח העכער, איז זייער מס\"נ אַ ענין גדול מאד.\nזייערע כחות אין תוקף מס\"נ בתלמידי תלמידיהם, אַז קינדער פון 12­10 יאָר גייען בשמחה לבית האסורים פאַר לערנען און מ'איז זיי מייסר בכמה ענינים זיי זאָלן זאָגן ווער האָט מיט זיי געלערנט, זאָגן זיי: בשום אופן ניט. כאָטש שטעך זיי און טו זיי כל מיני יסורים ר\"ל, דאָך זאָגן זיי ניט<sup data-n=\"658\">7</sup>.\n\"תורת אמת\" איז דאָך אַ המשכה און סניף פון \"תומכי­תמימים\"<sup data-n=\"659\">8</sup>, לכן איז די תלמידים שהיו בתחלת ההתיסדות ועליהם נתוספו עוד הרבה כן ירבו, אַז מ'זאָל ווינטשן דעם תוקף פון מס\"נ דאַרף מען ניט, דער אויבערשטער זאָל העלפן אַז דער דוחק ולחץ זאָל אַראָפּגיין און ס'זאָל ניט זיין קיין מניעות ועיכובים אויף תורה ומצות, וואָס מניעות ועיכובים האָט יעדערער, ניט נאָר אין רוסלאַנד. אין גלות איז דער גאַנצער כדור הארץ. עס איז דאָ נסיונות מניעות ועיכובים און מ'דאַרף דאָס דורכגיין, וואָס דער כללות עוה\"ז \"והיו ימיו מאה ועשרים\"<sup data-n=\"660\">9</sup>, איז נאָר אַ דורכגאַנג, נאָר מ'דאַרף וויסן אַז די כוונה איז להאיר אור בעולם און מאַכן פון עולם — תורה.\nאון אַזוי ווי איך בין דער מנהל כללי פון אַלע ישיבות<sup data-n=\"661\">10</sup> און ווי דער טאַטע (אאמו\"ר) האָט מיר איבער געגעבן בחייו בעלמא דין ובחייו בעולם העליון, איז ער דורך מיר אייך מצוה ומזהיר, אַז איך קאָן נאָר פירן ישיבות שענינן הוא",[["657","*6","ראה לעיל ע' 13 הערה 14."],["658","7","ראה גם ספר השיחות תר\"פ­תרפ\"ז ע' 162."],["659","8","ראה מקומות שבהערה 2. וש\"נ. אגרות­קודש ח\"א ע' נז ואילך.\nולהעיר שתחילה נקראה ישיבה זו בשם \"תומכי תמימים\" (אגרות­קודש ח\"א ע' נא­נב), ורק אח\"כ נשתנה שמה ל\"תורת אמת\" (אגרות­קודש שם ע' סח)."],["660","9","בראשית ו, ג."],["661","10","ראה גם לעיל ע' 5."]]],[4301600263,"להאיר אור, און ווייל אויף \"תורת אמת\" איז דאָך דער אור מקיף און אור זכות נשיאינו — זאָל דאָס אייך געבן כחות להאיר אור בעולם.\nבאמת האָט מען געדאַרפט פאַרברענ­גען בפרטיות, נאָר מסתמא פאַרברענגט דאָך דער משפיע ומנהל ר' אלטער<sup data-n=\"662\">11</sup> לעתים תכופות, במילא איז דאָך די יסודות הענינים ידוע, און מיר זיינען דאָך מוגבל בזמן דאַרף מען ריידען חסידות און פון די ווערטער זאָל בלייבן אַ רשימה ביי מיר און ביי אייך.\nהגם שעפ\"י מה שמסר לי המשפיע אַז מ'לערנט חסידות און ס'איז פאַראַן אַזעלכע וואָס זיינען שייכות צו עבודת התפלה, וואָס תפלה מיינט מען ניט נאָר אַרויס פון דער שלילה פון ניט דאַוונען, נאָר עבודה שבלב זו תפלה, דאָך דאַרף מען זאָגן אַז די כוונה איז להאיר אור בעולם, ניט אַז דער עולם זאָל פאַרשלעפּן נאָר מאַכן פון עולם — תורה.\n[אחרי השיחה אמר מאמר דא\"ח ד\"ה אתה הראת לדעת כו'<sup data-n=\"663\">12</sup>.\nלפני שיצא מאולם הישיבה ביקש כ\"ק אדמו\"ר שכל תלמידי הישיבה יתאספו סביבו, ואמר:]\nזייט אַלע געזונט, איך פאָר אַוועק, נאָר מ'גייט ניט פאַנאַנדער, דער מקום איז ניט תופס מקום ממילא גייען מיר זיך ניט פאַנאַנדער, אחד מכם יהי' לרבבה להאיר אור.\nדער אויבערשטער זאָל העלפן אַז דער כח פון נשיאינו וואָס ער גיט אונז דעם כח אין עבודה אלקית בלימוד ועבודה שבלב, זאָל אייך העלפן אַז ס'זאָל זיין \"וידגו לרב בקרב הארץ\"<sup data-n=\"664\">13</sup>, אַז ס'זאָל זיין \"ותורה אור\"<sup data-n=\"665\">14</sup>.\nזייט געזונט, אַ גוטע נאַכט.",[["662","11","הרה\"ח ר' אלטער שימחוביץ. ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 24 הערה 3. לעיל ע' 54 הערה 4."],["663","12","נדפס בסה\"מ תרפ\"ט ע' 227 ואילך."],["664","13","ויחי מח, טז."],["665","14","משלי ו, כג."]]],[4301600264,"<h3>יום ב', י\"ג מנחם­אב, תרפ\"ט<sup data-n=\"666\">1</sup></h3>\n<b>בדרכו מכותל המערבי<sup data-n=\"667\">2</sup></b>\n\"לא אמר אדם לחבירו צר לי המקום שאלין בירושלים\"<sup data-n=\"668\">3</sup>, חז\"ל כיוונו בזה רק על מושג של \"מקום\" אבל לא על מושג של \"זמן\", שכן במקום אפשר להצטופף ראש על יד והמקום לא צר, ואילו מה שנוגע לזמן הרי כמה ששוהים בירושלים לא מספיק הזמן. במשך עשתי עשר יום שהנני נמצא בירושלים נוסף לי",[["666","1","נדפס בספר התולדות אדמו\"ר מהוריי\"צ ח\"ד ע' 37."],["667","2","ביומנו של רבינו: 30.6 [בוקר] הנני נוסע לכותל המערבי בלוית דודי רמ\"ה<sup data-n=\"e29\">*</sup> שי' ועוד. ומגן של שוטרים. שם הנני אומר תהלים וקורא פ\"נ. התעכבנו שמה עד שעה השמינית."],["668","3","אבות פ\"ה מ\"ה."],["e29","*","הרה\"ח ר' משה הכהן הארענשטיין חתנו של כ\"ק אדמו\"ר מהר\"ש. נזכר לקמן ע' 96."]]],[4301600265,"בע\"ה רבות והרבה עלה בידי, הייתי בכל מקום, כלומר הייתי במקומות רבים שבתור התחלה זה מספיק, הנני יוצא את ירושלים ברושם חזק מאד, ירושלים עשתה עלי רושם עז, יתן השי\"ת כי משיח צדקנו יתגלה בקרוב ולא יעבור זמן כזה שיספיק לקרר את ההרגשות האלה.\nיום ג', י\"ד מנחם­אב תרפ\"ט\nתל­אביב\nמר<sup data-n=\"669\">1</sup> רוקח מברך אותי בשם הקהל העברי ומפאר את כל אשר עשיתי לטובת אחינו בני הגולה, ואמר אשר בעת המאסר (תרפ\"ז) היתה שערורי' גדולה והעריכו אז מחאה נמרצת בשם הקהלה, ומתאר את גודל השמחה בהודע מהחופש שניתן לי, כל קהל תל אביב מאושר מהכבוד הגדול שעשיתי להם בבואי לתל אביב עיר העברים בכל מרחבי תבל היודעת לערוך כבוד לפועל חרוץ וחורף נפשו בעד עמנו ותורתו ומקוה הנהו אשר מעתה הגאון הגדול בכביר פעולותיו יעבוד גם בעד התפתחות ארצנו ונחלתנו, ומתכבד הנהו להרהיב לבקר את העירי' אשר שם יוכל כבוד האורח להודע כל ארחות חיי היהודים בארץ העברים ויושאר לזכרון נצחי הנה עוד מקוים הם ליהנות עצה ותושי' בהנהגה טובה.\nעניתי:\nעיר ישראל הראשונה היא עיר הקודש ירושלים אשר שם איוה אלקי ישראל למושב לו, וכל צפייתנו כי ירחמנו הא­ל יתברך ויקויים היעוד<sup data-n=\"670\">2</sup> ובא לציון גואל, יקר לי מאד הרגש הזך והיחס החשוב שמראים לי, הנני יודע להעריכו ולחבבו במאד מאד.\nמבין הנני אמיתית דבר זה, כי כל הכבוד הגדול שעושים לי בא ממקור האהבה והחיבה יתירה אשר בני הארצות החפשיות בעניני הדת רוחשים לאחינו היושבים בעמק הבכא בגלות המר, ואנכי כאחד הסובלים מרודפי הדת, לזאת שמוני ליתד לתלות בי ילקוטי התהלה ונאומי הברכה.\nאנכי הנה מנעורי מסרתי כל כחותי בשביל טובת אחינו שי' הרוחנית אבל במצבי האי­נורמלי נעשיתי עסקן ציבורי אמנם כל זה מפני ההכרח אבל כל מגמתי הוא שעבוד מוחי ונפשי רק לאותן העבודות ולאותם הענינים שיש להם יחס אך ורק באהלי תורה ובאופן הישן נושן.\n[כן דיבר כ\"ק אדמו\"ר על הכבוד לבקר את העירי' ו\"דברים אחדים אודות הגזע אשר הוא משפיע לטוב\"<sup data-n=\"671\">3</sup>. בהמשך השיחה אמר להם כ\"ק אדמו\"ר שהמפלגה שלו היא \"חזוק התורה והמצוה\", כשהי' ברוסי' חשב שבקרב עמנו כבר אין מפלגות, כי בזמן שהראש מקבל מכה חזקה מזדעזעים כל האברים",[["669","1","מכאן עד התחלת החצאי­ריבוע הוא מיומנו של רבינו, ושם: בשעה 10 בא ממלא מקום ראש העירי' מר רוקח, עוזרו ומזכירו וחבר העירי' ממפלגת היראים. [ההמשך בפנים]."],["670","2","ישעי' נט, כ."],["671","3","יומנו של רבינו."]]],[4301600266,"ולא מרגישים רק את הראש, ואולם כשיצא את רוסי' ראה לצערו כי עוד קיימות מפלגות בישראל, אז נזכר במפלגה שלו \"חזוק התורה והמצוה\"]."],[4301600267,"<h3>יום ג', י\"ב אלול, תרפ\"ט</h3>\n<b>ניו יארק</b>\n[בבואי<sup data-n=\"672\">1</sup> למעוני התקבץ המון רב בהמגרש אשר סביב הבית וחכו שאצא אל הגזוזטרא להגיד להם ברכת עליכם שלום.\nבהחדר הגדול אשר על יד חדרי חיכו כחמישים רבנים וכערך זה בע\"ב נכבדים לקבל שלום.\nבשעה חצי השני' יצאתי אל החדר השני וקבלתי ברכת שלום.\nאחרי כן יצאתי אל הגזוזטרא ועמדתי אצל המעקה, במעמד רבנים זקנים וישישים יחיו וכרגע נשקט כל ההמון אשר היו בערך כאלפים איש כן ירבו.\nואלה הדברים אשר הגדתי להם לאמר:]\nהשי\"ת<sup data-n=\"673\">2</sup> האָט אונז אידין בעהייליגט מיטין טיטול גוי אחד בארץ<sup data-n=\"674\">3</sup> לשון יחיד, די אַלע פּאַרטייען אין אַלע לענדער זאיינען דורכגיבונדן מיט אַ שנירעל פון אהבת התורה.\nעס פרייט מיר די האַרץ זעהען אויף דעם 2­טן זייט ים אַ קיבוץ אידן כן ירבו, מיט דער טרייער וואַרעמקייט פון דעם אַלטן היים מקומי התורה.\nדאָס גיט די גרויסע האָפענונג אַז השי\"ת וועט העלפן און מיר וועלן אין געכן זעהען די הרחבת הרבצת התורה בארצות הברית אין דעם גייסט פון דער אַלטער היים.\nאיך ווינטש אייך אַלעמען בתוך כלל אחב\"י שי' אַ כתיבה וחתימה טובה.",[["672","1","מכאן עד סוף החצאי­ריבוע — מיומנו של רבינו מיום יג אלול תרפ\"ט שכ': \"תמול בבואי למעוני\" [ההמשך בפנים]."],["673","2","ברשימה הנ\"ל לא נעתק מה שאמר אז. והועתק כאן מרשימה אחרת בכי\"ק רבינו [ה­פאקסימיליא נדפס לעיל ב\"מבוא\" ע' מג].\nבזכרונות הר\"י דזייקאבסאן מיום זה (נעתק בספר תולדות חב\"ד בארצות הברית ע' מג): אחרי זמן קצר ונתאספו הרבה אנשים יצא כ\"ק אדמו\"ר על המרפסת פארטש מהקומה הראשונה ואמר את דבריו באגריסונג \"סדנא דארעא חד הוא כו'\"."],["674","3","שמואל­ב ז, כג. דברי הימים­א יז, כא."]]],[4301600268,"<h3>ב' דר\"ה, תר\"ץ</h3>\nכ\"ק<sup data-n=\"675\">1</sup> אאזמו\"ר הרה\"ק הרמ\"מ זצוקללה\"ה נבג\"מ זי\"ע בר\"ה תר\"ה<sup data-n=\"676\">2</sup> אמר בסעודת ליל א' דר\"ה, יש לי הוכחו' מן התו' נביאי' וכתובים כי הנשמות למעלה במדרי' מן המלאכים וכש\"כ מן מלך, כי כל תוקפו של מלך הוא שיש לו שר<sup data-n=\"677\">3</sup>, והשר הוא א' מן השבעים שרי מעלה שהם מזלות. אַ נשמה וערט ניט נתפעל פון אַ מזל.\nובשנה ההיא הי' בפ\"ב<sup data-n=\"678\">4</sup>, והי' במאסר אַרעסט איזה ימי' כנודע, וחפצו אשר ישאר לדור בפ\"ב, ואח\"כ נתבטל הדבר, ואיזה ימים קודם סליחות בא חזרה לליובאַוויטש אחרי היותו בפ\"ב כשלשה חדשים.",[["675","1","מיומנו של רבינו מיום ב, ג תשרי. ושם לפנ\"ז: תמול בסעודת יו\"ט ספרתי כי: [המשך בפנים]."],["676","2","ראה — בשינויים — רשימת רבינו בספר השיחות תורת שלום ע' 80­79. ע' 260 (בהוצאת קה\"ת, תשנ\"ג)."],["677","3","ראה ספר השיחות שם ע' 204. ובכ\"מ."],["678","4","= בפטרבורג."]]],[4301600269,"<h3>א' דחוהמ\"ס, תר\"ץ</h3>\nקודם<sup data-n=\"679\">1</sup> התפלה חזרתי המא' בסוכות תשבו<sup data-n=\"680\">2</sup>.\nאמרתי להם ג' דברים<sup data-n=\"681\">3</sup>:\nא) בשם הוד כ\"ק אאמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע דאיך אפשר לומר דעיקר השכל הוא השתוממות, דשכל אנושי הוא קאַלט, הגבלה און ניט אמת (ורק גורם לאמת). אלא דתירץ דהעיקר הוא הנמשל, דהמשל אינו אמת, וכמו מלך תועה ביער ואבד גם עבדיו ומשרתיו, שאינו במציאות, והוא רק משל, ובהיות כי שכל אנושי הוא משל, ויש בו מקורו שהוא הגרעין האמת שבו. ובמקורו בשכל אלקי העיקר הוא ההשתוממות, ולכן גם בשכל אנושי הוא כן.\nב) ונוזלים מן לבנו\"ן<sup data-n=\"682\">4</sup>, לבנו\"ן הוא<sup data-n=\"683\">5</sup> ל\"ב נו\"ן, פנימי' חכ' ופנימי' בינה. וי קאן זאיין מזל, נאר עס רינט און מיא ווייס ניט פון ואַנען.\nוהגדתי להם ביאור בענין ריבוי האור ומיעוט הכלי' דתהו<sup data-n=\"684\">6</sup> וענין התרגשות הכחות.",[["679","1","מיומנו של רבינו."],["680","2","דיום ב' דחג הסוכות — נדפס בספר המאמרים קונטרסים ח\"א עח, ב ואילך."],["681","3","אולי ביאורים בהמאמר."],["682","4","שה\"ש ד, טו."],["683","5","ראה מאורי אור מערכת ל אות ז וביאיר נתיב שם. לקו\"ת האזינו עא, ד. אוה\"ת שה\"ש ח\"א ע' קעט. סה\"מ ה'ש\"ת ע' 63. תש\"ב ע' 136."],["684","6","ראה ד\"ה בסוכות הנ\"ל פ\"ו­ז (סה\"מ שם פא, א­ב)."]]],[4301600270,"<h3>שמחת תורה תר\"ץ<sup data-n=\"e1\">*</sup> </h3>\n<b>ניו יארק </b>\n<b>מהדורא תנינא עם הוספות וביאורים<sup data-n=\"685\">1</sup></b>\nא. אין דער עלית הנשמה פון רבינו הבעש\"ט נ\"ע בשנת תק\"ז. איז ער געווען אין היכל המשיח, האָט מורנו הבעש\"ט גיפרעגט באַ משיח'ן, אימתי קאתי מר, האָט משיח געענטפערט, לכשיפוצו<sup data-n=\"686\">2</sup> מעיינותיך חוצה<sup data-n=\"687\">3</sup>.\nשאלה ותשובה, איז דאָס אַ געוויסע השכלה און השגה געביידע, אין יעדער געביידע איז פאַראַן דער עצם הבנין, און דער תוך פון דעם בנין, וואָס אַזוי איז אויך אין דער השכלה געביידע, די שאלה איז דער בנין, אין שכל וועלט הייסט דאָס די השכלה, און די תשובה הייסט דער תוך, די בעלייכטונג פון דעם בנין, וואָס אין שכל וועלט הייסט דאָס די השגה, וואָס די ביידע — השכלה און השגה — שטאַרקן און בעלייכטען איינע די אַנדערע.\nהשכלה איז דער גרונדשטיין און דער וואָרצל פון השגה, און השגה איז די רעזידענץ פּאַלאַץ פון השכלה.\nמיט דעם וועט מען פאַרשטיין די טיפקייט פון דעם מאמר החכם, שאלת חכם חצי תשובה, או שאלות החכמה חצי החכמה.\nדי צוויי נוסחאות א) שאלת חכם חצי תשובה<sup data-n=\"688\">4</sup> — די פראַגע ווי אַ קלוגער פרעגט איז דער אופן פון דער פראַגע אַליין אַ האַלבער ענטפער. ב) שאלות החכמה חצי החכמה<sup data-n=\"689\">5</sup> — די וויסענ­שאַפטליכע פראַגעס זיינען אַליין אַ האַלבער טייל פון וויסענשאַפט. —\nאיז דייטלעך קלאָר אַז די צוויי נוסחאות איז דאָס צוויי בעזונדערע השכלה אינהאַלטן, וואָס יעדע איינע פון זיי האָט אַ ברייטע פערשטאַנדיקע ערקלערונג מיט אַ געוויסע בעדייטונג, אָבער איצטער וועלען מיר זיך ניט פערטיפן אין דעם, מיר וועלין מער ניט ווי לערנען פירוש המלות.\nאין דעם וואָרט אַז שאלת חכם חצי תשובה, איז פאַראַן אַ מעלה און אַ",[["685","1","רבינו כתב ב' מהדורות משיחה זו. מהדורא קמא יצא לאור בקונטרס בפ\"ע — נ.י. תר\"ץ. המהדורא תנינא — בהוספות וביאורים — יצא לאור בשנת תרצ\"ז, ונדפס בלקוטי דיבורים חלק ב רפו, ב ואילך. בהוצאה זו ניתוספו הערות וציונים מהמו\"ל."],["686","2","ע\"פ משלי ה, טז. ראה לקמן סעיף לב (ע' 112)."],["687","3","אגרת הבעש\"ט הידועה — נדפסה בסוף ספר בן פורת יוסף; בספר המכתבים מהבעש\"ט ז\"ל ותלמידיו (לבוב תרפ\"ג, וכותב המו\"ל שהעתיקה מן המכתב — כת\"י חתנו של הבעש\"ט הרה\"צ וכו' ר' יחיאל — החתום בעצם כי\"ק של הבעש\"ט); בספר גנזי נסתרות (ירושלים, תרפ\"ד) ח\"א סימן סה. כתר שם טוב (הוצאת קה\"ת) בתחילתו. מגדל עז (כפר חב\"ד, תש\"מ) ע' קכג­קכד. ועוד."],["688","4","מובא בספר ר\"ש בן גבירול<sup data-n=\"e30\">*</sup>. — הערה בלקו\"ד שם."],["689","5","מובא במבחר הפנינים שערי החכמה. — הערה בלקו\"ד שם."],["e1","*","ביומנו של רבינו כ' שבסעודת יום שמחת תורה דיבר \"בדבר הקשר מהסוחרים על לימוד התו', כי טוב סחרה\", ולאחר הפסקה, אמר השיחה בענין \"אימתי קאתי מר\"."],["e30","*","מהדורת דוקס ע' צג."]]],[4301600271,"חסרון, די מעלה איז, וואָס עס איז אַ חצי תשובה, און דער חסרון איז, וואָס עס איז מער ניט ווי אַ חצי תשובה, אָבער דאָס בעווייזט אויף דער התאחדות פון השכלה והשגה, השכלה איז דער מקור האור דהשגה, און השגה בעלייכט די השכלה.\nאַז דער בעש\"ט נ\"ע האָט געפרעגט משיח'ן, און משיח האָט געענטפערט, הייסט דאָס אַז אין דעם ענין פון ביאת המשיח, איז שאלת הבעש\"ט נ\"ע די השכלה, און תשובת משיח די השגה.\nדי השכלה איז, אימתי קאתי מר, ווען קומט משיח און די השגה, וואָס הייסט דער פאַרשטאַנד, איז לכשיפוצו מעיינותיך חוצה, וואָס עס האָט אַ צווייענדיקע בעדייטונג, א) אַז עס וועלין זיך צושפּרייטן דיינע קוועלין אין דרויסן ב) און אַז דיינע דרויסנדיקע קוועלין וועלין זיך צושפּרייטען.\nווי געזאָגט, אַז אַ שאלה ותשובה, איז די שאלה דער בנין, און די תשובה איז די בעלייכטונג פון דעם בנין, איז דעם בעש\"ט'ס נ\"ע שאלה, די השכלה פון דעם בנין ביאת המשיח בב\"א און די תשובה פון משיח'ן, די בעלייכטונג אין דעם בנין ביאת המשיח בב\"א, דאָס מיינט דעם פאַרשטאַנד.\nפאַרשטאַנד האָט אַ יסוד אויף וואָס ער איז געבויט, און אַ שרש פון וואַנען ער וואַקסט.\nדער טייטש פון יסוד און שרש איז, אין יעדער זאַך איז פאַראַן דער גוף פון דער זאַך, ווי איידיל אַ גוף רוחני כמו סברת השכל, זאָל ניט זיין, איז דער חיות השכל איידעלער, יסוד איז דער גרונדלאַגע וואָס האַלט דעם גוף און שרש איז דער מקור פון דעם חיות.\nאין שכל איז אויך פאַראַן אַ יסוד און אַ שרש דאָס הייסט, אַז אין יסודי השכל איז פאַראַן אויף צוויי אופנים, א) יסוד איז דער גרונד פון דעם שכל, דער יסוד איז נידעריקער, און דער פאַרשטאַנד איז העכער כמשל הבנין וואָס דער יסוד איז למטה והבנין על גבו. ב) שרש איז דער וואָרצעל פון דעם שכל, דאָס הייסט אַז דער יסוד איז העכער און דער פאַרשטאַנד איז נידעריקער.\nב. אונזער חסידות'שער פאַרשטאַנד איז געבויט אויף חסידות, דאָס הייסט אַז דער יסוד איז שכל עצמי, און דער שרש איז חיות אלקי גלוי, ניט דער טבע'דיקער אלקות.\nאַלע אידן ווייסין מיט אַ הכרה עצמית, אַז הוי' אחד<sup data-n=\"690\">6</sup>. דער וואָרט אחד איז אַ ר\"ת<sup data-n=\"691\">7</sup>, מיט צוויי אינהאַלטן אין דער בעדייטונג פון וואָרט אחד.\nדער וואָרט אחד זאָגט אַרויס דעם מיין פון דעם אויבערשטנ'ס ב\"ה איינצלהייט, אַז דער אויבערשטער ב\"ה איז איינער.\nאין חסידות פרעגט מען<sup data-n=\"692\">8</sup>, דער ריכטיקער אויסשפּראַך אויף בעצייכענען און בעטאָנען איינצלהייט איז דער וואָרט יחיד, און ניט אחד, דער וואָרט אחד בעטאָנט איינער, אָבער עס שליסט ניט אויס אַז מעהר איז ניטאָ, דער וואָרט אחד זאָגט אַז ער איז דער ערשטער, ווי עס שטעהט<sup data-n=\"693\">9</sup> ויהי ערב ויהי בקר יום אחד, אָבער דער וואָרט יחיד",[["690","6","ואתחנן ו, ד."],["691","7","סמ\"ק הובא בבית יוסף או\"ח סימן סא (ד\"ה כתב סמ\"ק). שו\"ע ודאדה\"ז או\"ח שם סעיף ו."],["692","8","ראה תו\"א וארא נה, ב ואילך. אמרי בינה שער הק\"ש פ\"ח. סהמ\"צ להצ\"צ קכד, א­ב. ובכ\"מ."],["693","9","בראשית א, ה."]]],[4301600272,"בעצייכנט איינצלהייט, האָט מען דאָך גידאַרפט זאָגן הוי' יחיד, פאַר וואָס זאָגט מען הוי' אחד.\nחסידות ערקלערט<sup data-n=\"692\">8</sup> דעם אונטערשייד פון דער בעדייטונג וואָס מיינט דער וואָרט יחיד, צו דער בעדייטונג וואָס מיינט דער וואָרט אחד. יחיד איז איינציג און איינצלהייט, אָבער אחד איז פאַראיינציגט, דאָס הייסט אַז עס איז פאַראַן זאַכן וואָס זיי זעהען אויס אַז יעדע איז אַ זאַך פאַר זיך, און עס איז דאָ איין זאַך וואָס פאַראיינציגט זיי, כמו אלף אחד, טויזנד איינצלהייטן באַהעפטן זיך אין איינעם, וואָס ער בעהעפט די אַלע טויזנד אייצנלהייטן.\nאָט דער אחד איז אַ אחד המנוי, אַ אחד וואָס ער קומט פון צאָהל, און ווערט בעצייכנט מיט צאָהל, דער אחד פון הוי' אחד איז אַ אחד המחבר וואָס בעהעפט אַלץ, וויילע אַלץ קומט פון אים, און דאָס איז דער טייטש הוי' אחד דער בעשעפער פון אַלץ און דער פאַראיינציקער פון אַלץ, אין קורצע ווערטער הייסט דאָס, ער איז אַלץ, אַלץ איז ער<sup data-n=\"695\">10</sup>.\nדער אינהאַלט ער איז אַלץ, אַלץ איז ער, ווערט אָנגידייט אין דעם ראשי תיבות פון דעם וואָרט אחד, און בהיות ווי עס איז דאָך פערשידן דער אינהאַלט פון דעם וואָס \"ער איז אַלץ\" ביז דעם אינהאַלט פון דעם וואָס \"אַלץ איז ער\", דערפאַר איז אין דעם ר\"ת פון דעם וואָרט ווערט געלייענט ישר והפוך.\nדי דריי אותיות פון דעם וואָרט אחד איז יעדער אות האָט אַ בעזונדער בעדייטונג<sup data-n=\"691\">7</sup>, דער אות אלף בעדייטעט אין סוף ב\"ה אלופו של עולם — דער אומבעגרעניצטער, גילויבט איז ער, דער האַר פון אַלע וועזנהייט, דער אות ח' בעדייטעט, די ערד מיט די זיבן הימלען, דער אות ד' בעדייטעט, די פיר זייטן פון דער וועלט.\nאחד, ער איז אַלץ, א' אין סוף ב\"ה האָט בעשאַפן, ח' די ערד און די זיבן הימלען, ד' אויך די פיר זייטן פון דער וועלט.\nאחד, אַלץ איז ער, ד' די פיר זייטן פון דער וועלט, ח' און די ערד מיט די זיבן הימלען זיינען בטל ומבוטל פאַר דעם א' אין סוף אלופו של עולם, און דערפאַר זאָגט מען הוי' אחד, און ניט הוי' יחיד, וויילע דער וואָרט אחד בעטאָנט דעם ענין האחדות, דאָס הייסט די געטליכקייט איז מלובש בלבוש הטבע, טבע'דיקע געטליכקייט.\nג. דער יסוד החסידות איז שכל עצמי, און דער שרש החסידות איז חיות אלקי גלוי, דערפאַר איז חסידים פאַרשטייען אַ זאַך ריין קלאָהר, די עצם זאַך איז באמת, אָהן שפּאַקולן און אָהן אַ שלייער, נאָר דער חסידות'שער פאַרשטאַנד איז מיט ריינעם חסידות'ן שכל.\nדער יסוד החסידות איז שכל עצמי, און דער שרש החסידות איז חיות אלקי, וואָס יסוד איז דער גרונד אויף וואָס די זאַך האַלט זיך, איז דאָך דער יסוד אונטער דער זאַך, וועלכע שטייט אויף אים, און שרש איז דער וואָרצעל פון וואַנען די זאַך וואַקסט, איז דער שרש העכער פון דעם, וואָס עס קומט פון דעם אַרויס.",[["692","8","ראה תו\"א וארא נה, ב ואילך. אמרי בינה שער הק\"ש פ\"ח. סהמ\"צ להצ\"צ קכד, א­ב. ובכ\"מ."],["695","10","ראה גם ד\"ה קמתי אני תרס\"ו (המשך תרס\"ו — קה\"ת, תנש\"א) ע' תקסח. ספר השיחות תורת שלום ע' 64. סה\"מ ה'ש\"ת ריש ע' 141. אגרות­קודש ח\"ג ס\"ע תקלט. ספר השיחות: תר\"פ­תרפ\"ז ע' 229; תש\"א ע' 47. תש\"ג ע' 25. ד\"ה והניף ידו דאחש\"פ תשי\"א (סה\"מ תשי\"א ע' 42). לקוטי שיחות חלק כה ע' 166 הערה 61."],["691","7","סמ\"ק הובא בבית יוסף או\"ח סימן סא (ד\"ה כתב סמ\"ק). שו\"ע ודאדה\"ז או\"ח שם סעיף ו."]]],[4301600273,"דער יסוד החסידות איז שכל עצמי, אין שכל איז פאַראַן פערשידענע שכלים, עס איז פאַראַן שכל אנושי, מענשליכער שכל און עס איז פאַראַן שכל אלקי, געטליכער שכל. שכל אנושי איז אַ שכל הנקנה, און שכל אלקי איז אַ שכל עצמי, וואָס דער מציאות המהות פון שכל עצמי איז גאָר אַ אַנדער מהות מציאות פון שכל אנושי.\nזייענדיג מיט דעם טאַטען, פורים תרס\"ג<sup data-n=\"697\">11</sup>, אין וויען (עסטרייך)<sup data-n=\"698\">12</sup> האָט דער טאַטע גערעדט ביים טיש וועגען לימוד התורה לשמה, לשם התורה, מען ווערט פאַראיינציגט מיט דער תורה, ביז ער — דער לערנער און די תורה — ווערען איין זאַך, זיין סגנון הלשון ווערט אַ תורה לשון און זיין שכל ווערט אַ תורה שכל.\nדער זיידע<sup data-n=\"699\">13</sup> האָט דערציילט דעם טאַטען<sup data-n=\"700\">14</sup> אַז צו בר מצוה האָט אים זיין זיידע<sup data-n=\"701\">15</sup> געזאָגט, אַז מען בעדאַרף לערנען תורה לשמה, וואָס די הכנה צו דעם איז, קלאָר זיין בבלי וירושלמי, תוספתא ספרא וספרי, ווי דער רמב\"ם איז קלאָר געווען<sup data-n=\"702\">16</sup>.\nדער לובלינער גאון<sup data-n=\"703\">17</sup> האָט מיר דערציילט<sup data-n=\"704\">18</sup> אַז ווען ער איז געקומען קיין ליובאַוויטש צום זיידן<sup data-n=\"699\">13</sup> אין יאָר תרי\"ד — באַ דעם לובלינער איז געווען אַ סדר, אַז ווען ער פלעגט קומען קיין ליובאַוויטש פלעגט ער בריינגען אַ ענין אין לערנען, אין וועלכן ער פלעגט זיך מפלפל זיין מיט'ן זיידען — האָט ער געבראַכט אַ טיפן פלפול מיט אַ סך חידושים.\nקומענדיג אין ליובאַוויטש האָט ער איבערגעטראַכט דעם פלפול מיט די חדושי תורה און איז געווען זייער צופרידען, וויסענדיג אַז מיט דעם וועט ער פאַרשאַפען דעם זיידען אַ גרויסן נחת רוח, און באַ אַ חסיד איז דאָך איינע פון די גרעסטע זאַכען, ווען מען קען גורם זיין אַ נחת רוח דעם רבי'ן, וואָרום אַ חסיד ווייסט אַז עלמא עילאה כגוונא דעלמא תתאה<sup data-n=\"706\">19</sup>, דער וואָס איז מקושר",[["697","11","ע\"ד פורים תרס\"ג — ראה גם ספר השיחות קיץ ה'ש\"ת ע' 38­37."],["698","12","בחורף תרס\"ג (יד שבט<sup data-n=\"e31\">*</sup> — ח' ניסן<sup data-n=\"e32\">**</sup>) הי' כ\"ק אדמו\"ר מהורש\"ב נ\"ע עם כ\"ק בנו אדמו\"ר מהוריי\"צ נ\"ע בוויען. ע\"ד תקופה זו, ושיחות­קודש שנאמרו אז — ראה ספר השיחות תר\"פ­תרפ\"ז ע' 23. וש\"נ. וראה גם לקמן ע' 240. שיחות סוכות תרצ\"ג (ברשימות כ\"ק אדמו\"ר)."],["699","13","כ\"ק אדמו\"ר בעל צמח­צדק. — הערה בלקו\"ד שם."],["700","14","כ\"ק בנו אדמו\"ר מוהר\"ש. — הערה בלקו\"ד שם."],["701","15","כ\"ק רבינו הזקן בעל התניא. — הערה בלקו\"ד שם."],["702","16","ראה גם לקמן ע' 218."],["703","17","הרב ר' שניאור זלמן פראדקין, בעהמ\"ח שו\"ת \"תורת חסד\". אדר תק\"ץ — ה' ניסן תרס\"ב. ראה אודותו ספר \"הגאון מלובלין\" ירושלים, תשל\"ז."],["704","18","בכ\"ז — ראה גם לקמן ס\"ע 217 ואילך. ספר השיחות תש\"ד ע' 17."],["699","13","כ\"ק אדמו\"ר בעל צמח­צדק. — הערה בלקו\"ד שם."],["706","19","ראה זוהר ח\"א לח, א. שם רה, ב."],["e31","*","נסע לוויען ביום יב שבט, והגיע לשם ביום יד שבט — אגרות­קודש אדמו\"ר מהורש\"ב ח\"ג ע' שעח­שעט. רשימת היומן של רבינו מיום כג סיון תרס\"ג (\"מבוא\" לקונטרס ומעין ע' 53). ובהערת כ\"ק אדמו\"ר שם: ע\"פ מ\"ש כאן צריך לתקן ב\"חנוך לנער\" [ע' 12, שכתוב שם: אחרי חנוכה נוסע לווינא\". וכ\"ה במכתב רבינו משנת תרפ\"ה (הועתק ברשימות כ\"ק אדמו\"ר — ילקוט — חוברת ט ע' 4)]. בספר השיחות תש\"א ע' 88, שהגיע לוויען ביום ג' פ' ויחי ז' טבת."],["e32","**","אגרות­קודש אדמו\"ר מהורש\"ב ח\"ג ע' שפח."]]],[4301600274,"צום רבי'ן בעלמא תתאה איז ער זוכה צו זיין מקושר צום רבי'ן בעלמא עילאה, און זיין נעבען רבי'ן בעלמא עילאה איז שוין גאָר עפּעס אַנדערש.\nווען איך בין אַריין געגאַנגען צום רבי'ן — האָט דערציילט דער לובלינער — און מיר האָבען אָנגיהויבען צו ריידן אין לערנען און איך האָב פאָרגעלייגט מיין פלפול, האָט דער רבי אַ שמייכל געטאָן, און האָט מיר געזאָגט אַז איך זאָל זאָגען מיינע חדושי תורה, איך בין געווען זייער צופרידען, זעהענדיג ווי דער רבי הערט די תורה וואָס איך האָב געזאָגט.\nווען איך האָב אָפּגעזאָגט, זאָגט מיר דער רבי, עס איז גוטע תורה מיט גאָר פיינע סברות, נאָר די נקודה פעלט, ד.ה. אַז דער יסוד פון דער הנחה וואָס איך האָב מחדש געווען איז ניט אמת, און דער רבי זאָגט מיר אַז עס איז דאָ אַ משנה מפורשת פאַרקערט פון דער הנחה.\nאיך בין אַזויפיל צורודערט גע­וואָרען, דערציילט דער לובלינער, אַז איך האָב געפרעגט, רבי, אין וועלכן סדר, אין קדשים — האָט מיר דער רבי געענטפערט, איך האָב איבערגעטראַכט און זאָג, רבי איך ווייס ניט, אפשר וועט איר מיר זאָגען אין וועלכער מסכת, אין בכורות<sup data-n=\"707\">*19</sup> — האָט מיר דער רבי געענט­פערט, איך האָב איבערגעטראַכט די מסכת בכורות און האָב ניט געפונען, ביז דער רבי האָט מיר אָנגיהויבן זאָגן דעם לשון המשנה און האָט אנגעהויבן מפרש זיין, האָב איך זיך געכאַפּט מיין טעות, דאַמאָלסט — האָט געזאָגט דער לובלינער — האָב איך געזעהען און געפיהלט וואָס הייסט לימוד התורה לשמה.\nד. איהר — האָט דער טאַטע געזאָגט צו די מסובים, פון וועלכע אַ גרויסער טייל זיינען געווען פּוילישע און אונגאַרישע<sup data-n=\"708\">20</sup> — ווייסט ניט ווער איז געווען דער לובלינער, דער לובלינער איז געווען אַ גאון, אַז מיט דורות פריהער וואָלט מען אים אויך געהאַלטען פאַר אַ גאון, און דער גאון האָט געלייגט אַ הנחה שכלית אין אַ תורה שכל און האָט אַ טעות געהאַט.\nדער טעות פון לובלינער גאון איז אַ טעות אין דער נקודה, די סברות זיינען געווען גוטע, נאָר אין דער נקודת ההנחה האָט ער אַ טעות געהאַט, און הגם אין דער נקודת ההנחה האָט ער אַ טעות געהאַט, אָבער די סברות השכל זיינען געווען גוטע פיינע סברות.\nדי עדות פון זיידען אַז די סברות זיינען געווען פיינע איז גענוג, דער זיידע איז געווען דער אמת'ער מבין וואָס הייסט סברות שכלים, דאָס זעט מען אין זיינע תשובות, אין די הוספות והגהות אויף די מאמרים פון תו\"א און לקו\"ת<sup data-n=\"709\">*20</sup> און אויך אין די הונדערטער מאמרים, וועלכע זיינען נאָך בכתב­יד.\nאיינמאָל זייענדיג ביים טאַטען<sup data-n=\"710\">21</sup> ביחידות, האָט דער טאַטע דערמאָנט דעם רבי'ן<sup data-n=\"701\">15</sup> און האָט געזאָגט, אַז דער",[["707","*19","ראה לקמן ע' 218 הערה 77."],["708","20","ראה ספר השיחות שבהערה 11."],["709","*20","המאמרים שבספר \"תורה אור\" ולקו\"ת על ה' חומשי תורה ושה\"ש הם של רבינו הגדול בעל התניא, וההגהות וביאורים על המאמרים הם של כ\"ק אדמו\"ר בעל צמח צדק<sup data-n=\"e33\">*</sup>. — הערה בלקו\"ד שם."],["710","21","כ\"ק אדמו\"ר מהר\"ש."],["701","15","כ\"ק רבינו הזקן בעל התניא. — הערה בלקו\"ד שם."],["e33","*","ראה בארוכה אגרות­קודש ח\"ד ע' תקס ואילך."]]],[4301600275,"רבי איז געווען אַ עצמי<sup data-n=\"712\">22</sup>, און האָט גלייך פערטייטשט וואָס איז דאָס אַ עצמי, אַ עצמי איז אַ שכלי, וואָס זיין שכל איז אַ שכל עצמי, אין שכל אלקי גופא איז פאַראַן כמה חלוקי דרגות, למשל, אין חכמת התורה, וואָס דאָס איז דאָך שכל אלקי, איז אין דעם פאַראַן חלוקי מדריגות, לבד זאת וואָס אין שכל איז פאַראַן קטנות וגדלות, קליין און גרויס, אַ קליינער שכל און אַ גרויסער שכל, און עס איז פאַראַן חכמה און שטות, אַ קלוגער שכל און אַ נאַרישער שכל, איז אַ חוץ דעם זיינען פאַראַן חלוקי דרגות פון בעלי השכלה און בעלי השגה אין חכמת התורה, וואָס דאָס איז שכל אלקי.\nדער טאַטע<sup data-n=\"710\">21</sup> האָט מיר יעמאָלט מסביר געווען דעם ענין פון חלוקי דרגות אין שכל אלקי על דרך די ג' חלוקים אין אמת, אין אמת זיינען פאַראַן דריי דרגות כוללים<sup data-n=\"714\">23</sup>: א) שפת אמת<sup data-n=\"715\">24</sup>, ב) אמת, ג) אמת לאמתו<sup data-n=\"716\">25</sup>. אַלע דריי דרגות זיינען אמת, פונדעסטוועגן איז דער אמת פון דער מדריגה שפת אמת ניט דער אמת ווי אין דער מדריגה פון אמת עצמה, און דער אמת פון דער מדריגה פון אמת עצמה, איז ניט דער אמת פון דער מדריגה אמת לאמתו.\nדי דריי דרגות אין אמת, האָט געזאָגט דער טאַטע, זיינען דריי וועלטן מיט כמה וכמה מדרגות חלוקות זה מזה, וואָס בכללות איז דאָס אין ספירות די ג' ענינים, חב\"ד חג\"ת נה\"י, און אין עולמות איז דאָס אצי' בריאה יצירה.\nה. פאַר די וואָס לערנען אונזערע<sup data-n=\"717\">*25</sup> חסידות — האָט געזאָגט דער טאַטע<sup data-n=\"718\">26</sup> — איז איבעריג מבאר צו זיין, אַז חב\"ד חג\"ת נה\"י און אצילות בריאה יצירה, איז אין עולמות דער עולם האצילות, און אין ספירות די ג' ספירות חב\"ד, זיינען די מדרגה פון אמת לאמתו. דער עולם הבריאה און די ג' ספי' חג\"ת, זיינען די מדרגה פון אמת, און דער עולם היצי' און די ג' ספי' נה\"י זיינען די מדרגה פון שפת אמת.\nאָבער פאַר אַנדערע חסידים, אויך פאַר אונזערע חסידים, וועלכע לערנען קיין חסידות ניט — הגם אויב מען לערנט קיין חסידות ניט מיט וואָס זיינען זיי אונזערע חסידים, דאָס איז אַ ענין פאַר זיך, אָבער עס זיינען פאַראַן אַזעלכע, וועלכע לערנען ניט קיין חסידות און זיי זיינען אויך אונזערע, וואָס מיר מוזען פאַר זיי זאָרגען ביחוד, דאָס וואָס איך זאָג ביחוד, ווייל באמת דאַרף דאָך באַ אידען ניט זיין קיין חלוקים, מען דאַרף זאָרגען פאַר אַלע אידען, אָבער מכל מקום זיינען פאַראַן חלוקים, ווי עס איז ע\"פ תורה. — דאַרף מען יאָ געבען צו פאַרשטיין.\nמיט חסידות דאַרף מען זיך ניט אָנוואַרפען און אָנשלאָגען. דער רבי האָט געזאָגט, אַז מיט דריי זאַכען דאַרף",[["712","22","ראה ספר השיחות תורת שלום ע' 166. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 2. וש\"נ. לקמן ע' 89. וראה לעיל ע' 26."],["710","21","כ\"ק אדמו\"ר מהר\"ש."],["714","23","ראה המשך תרס\"ו ע' תלח. סה\"מ תרח\"ץ ע' קסו ואילך. וש\"נ."],["715","24","משלי יב, יט. וראה תניא פי\"ג. לקו\"ת בהר מ, א. וראה גם ספר השיחות תרצ\"ו­חורף ה'ש\"ת ע' 126."],["716","25","ע\"פ מרז\"ל שבת י, א. וראה אוה\"ת יתרו ע' תתצד ואילך. סה\"מ תרכ\"ז ע' רצא ואילך. המשך תרס\"ו ס\"ע תלא ואילך. ע' תלו ואילך."],["717","*25","תורת החב\"ד. — הערה בלקו\"ד שם."],["718","26","כ\"ק אדמו\"ר מהורש\"ב."]]],[4301600276,"מען זיך ניט אָנשלאָגען, מיט אַ שדוך, מיט אַ עצה און מיט אַ גמילות חסד, נאָר מצד אהבת ישראל דאַרף מען לייגען די גרעסטע השתדלות אין אַלע זאַכען, אַז יענעם זאָל ווערען בעסער.\nאמת, מיט חסידות דאַרף מען זיך ניט אָנשלאָגן אָבער אַרויסהענגען אַ שילד, דאַרף מען. יענער דאַרף זעהען וואָס פאַר אַ סחורה עס איז דאָ, און אַז יענער זעט די סחורה, קען באַ אים ווערן אַ חשק, נאָר היות עס איז פאַראַן סחורה וואָס ניט יעדער ווער עס זעט זי פאַרשטייט די גוטסקייט, דאַרף מען געבן צו פאַרשטיין.\nאין אמת זיינען פאַראַן דריי דרגות, אמת לאמיתו, אמת און שפת אמת. אַלע פאַרשטייען אַז די העכסטע מדרגה איז אמת לאמתו און די נידעריגסטע איז שפת אמת, אָבער ניט אַלע פאַרשטייען ווי אמת קען זיך טיילען אין חלקים, און מיט וואָס זיינען די מדריגות אין אמת אָפּגעטיילט איינע פון דער צווייטע.\nדי נידעריגסטע דרגא פון אמת וואָס הייסט שפת אמת איז העכער ווי די העכסטע און איידעלסטע מדריגה פון מציאות. כל מציאות וועלכע זאָל ניט זיין האָט ניט קיין קיום עצמי, און די נידעריגסטע מדרגה פון אמת — שפת אמת — האָט אַ קיום עצמי, ווי עס שטייט (משלי י\"ב י\"ט) שפת אמת תכון לעד, טייטשט רש\"י, תתבסס ותתקיים ד. ה. אַז מזמן לזמן ווערט דאָס בעסער און שטאַרקער.\nו. אמת איז אַ מדרגה, וועלכע איז העכער פון דער מדרגה פון שפת אמת. פאַר מדת האמת איז משה רבינו איבערראַשט גיוואָרן. עס שטייט (שמות ל\"ד ח') וימהר משה ויקוד ארצה וישתחו, פרעגט די גמרא (סנהדרין דקי\"א א') מה ראה משה — די גמרא איז אַ ביסעל מוקשה, וואָס איז די פראַגע, וואָס האָט משה געזעהען.\nדי קשיא אויף דער גמרא'ס פראַגע איז, וואָס עפּעס דוקא אין דעם ענין פרעגט די גמרא וואָס האָט משה געזעהען, אַז משה האָט געזעהען דעם סנה, און דער אויבערשטער דערציילט די גרויסע פאַרוואונדערונג פון משה רבינו, בשעת ער האָט דערזעהען דעם סנה ווי ער ברענט אין אַ פלאַם פייער און ווערט ניט פאַרברענט, פונדעסטוועגען פרעגט ניט די גמרא וואָס האָט משה געזעהען.\nאויך אין פאַרשידענע זמנים ווי קי\"ס, מ\"ת, הקמת המשכן, פרעגט ניט די גמרא, וואָס האָט משה געזעהען, נאָר באַ דעם גילוי פון י\"ג מדות הרחמים, אָט דאָ פרעגט די גמרא, וואָס האָט משה געזעהן.\nאיך ווייס, מען וועט מיר ענטפערן אַז ע\"פ פשוט, ווייל דאָ שטייט וימהר משה וגו' משה האָט געאיילט, פרעגט די גמרא וואָס פאַר אַ זאַך האָט ער געזעהען צוליעב וועלכער ער האָט געאיילט און ויקד ארצה וישתחו, אָבער דעם פשט אַליין דאַרף מען פאַרשטיין, און חסידות גיט דאָס צו פאַרשטיין.\nמשה רבינו איז אין דער מדרגה פון חכמה דאצילות. אין זהר<sup data-n=\"719\">27</sup> אויפן פסוק<sup data-n=\"720\">28</sup> ויהי אור שטייט, דא חכמה, חכמה איז אור ליכטיקייט, ווען עס איז ליכטיג זעהט זיך יעדער זאַך ריין קלאָר, בשעת מען זעט אַ זאַך קלאָר, ד.ה. ווען מען",[["719","27","בסה\"מ תרפ\"א ע' רמא מציין רבינו: זח\"א טז, ב. וראה סה\"מ תרצ\"ו ע' 63 ובהערה שם."],["720","28","בראשית א, ג."]]],[4301600277,"ווייס און מען פאַרשטייט דאָס וואָס מען זעט, יעמאָלט איז מען במנוחה און במתינות, אָבער ווען מען איז אייליג, איז דאָס אַ הוראה אַז מען איז אין התפעלות.\nמשה רבינו באַ אַלע גרעסטע פּאַסירונגען איז ער געבליבען רוהיג, נאָר באַ דעם גילוי פון י\"ג מדות הרחמים, איז ער געוואָרען אייליג, דאָס וואונדערט די גמרא וואָס האָט משה געזעהען, וואָס האָט אים געבראַכט צו דעם וימהר משה ויקד וישתחו.\nז. אַלע ווייסען אַז עס איז פאַראַן אַ גרויסער אונטערשייד צווישען קידה און השתחוי'. עס זיינען פאַראַן דריי אופנים<sup data-n=\"721\">29</sup>: א) קידה, בויגען זיך. ב) כריעה, קניען. ג) השתחואה, בוקען זיך. וואָס די דריי אופנים, הגם זיי זיינען איין און די זעלבע זאַך, וואָס בעווייזט אויף דעם ענין הביטול, נאָר אין ביטול גופא זיינען פאַראַן דרגות, וואָס יעדער דרגא האָט אַ שיעור המוגבל.\nעס איז נויטיג צו זאָגען, אַז יעדער פועל וואָס מען טוט קומט דאָך ע\"פ הכרח חיוב שכלי, ד. ה. אַז יעדער פועל האָט אַ טעם פאַר וואָס עס איז אַזאַ פועל, איז במילא מובן, אַז יעדער שעור אין ביטול האָט אַ טעם מיוחד, וואָס דער טעם איז דער הכרח שכלי פון דעם ביטול.\nדי דריי אופני ביטול, איז קידה הייסט הרכנת הראש, איינבויגן די קאָפּ, וואָרום בכלל זיינען אַלע מדרגות ביטול ניכר אין דעם הרכנת הראש. ביטול הייסט אַוועק לייג. באַ אַ מענטשן איז דער ענין פון אַוועק לייג ניכר נאָר אין קאָפּ, און דאָ זיינען פאַראַן די שיעורים אין די אופני הביטול.\nדער אופן הא' אין ביטול איז קידה, וואָס אין דעם ביטול פון קידה איז דער גוף האדם בלייבט במקומו, עס איז מער ניט, וואָס ער בויגט איין די קאָפּ. דער אופן הב' אין ביטול איז כריעה, אין דעם פאַל ביטול איז הגם דער מענטש בלייבט על עמדו, אָבער דער גאַנצער קומת האדם ווערט נידעריגער, ווייל ער שטעלט זיך אויף די קני, איז הגם דער אופן הביטול איז גרעסער פון דעם אופן הא', מכל מקום איז אין דעם אופן הביטול אויך ניכר דער הפרש פון ראש און רגל. דער אופן הג' אין ביטול איז השתחואה בפישוט ידים ורגלים, וואָס דאָס איז דער העכסטער פאַל ביטול, אַז ראש ורגל זיינען גלייך.\nווען משה רבינו האָט דעזעהען דעם גילוי פון יגמה\"ר, איז ער נתבטל געוואָרען אין דעם העכסטען אופן ביטול, השתחואה, דערפאַר פרעגט די גמרא, וואָס האָט משה דערזעהען.\nאויף דער פראַגע, וואָס האָט משה דערזעהען ברענגט די גמרא צוויי תשובות, וועלכע זיינען צוויי דעות. ר' חנינא בן גמלא אמר ארך אפים ראה, ורבנן אמרי אמת ראה. ווען משה רבינו האָט דערזעהען מדת האמת איז ער נתבטל געוואָרען אין דעם העכסטן פאַל ביטול — דער ביטול פון השתחואה.\nח. דאָס אַלץ איז די צווייטע מדרגה אין אמת, אָבער די דריטע מדרגה אין אמת איז ניטאָ קיין ווערטער מיט וואָס דאָס מסביר זיין ד. ה. אַז דער ענין פון אמת לאמתו איז פון די ענינים וואָס בלייבען אין הגיון הלב, און גיבען זיך ניט אין קיין ווערטער.",[["721","29","ראה ברכות לד, ב. מגילה כב, ב. רמב\"ם הל' תפלה פ\"ה הי\"ג. רש\"י מקץ מב, ו. מג, כח."]]],[4301600278,"אָבער אויך די טיפסטע ענינים וואָס גיבען זיך ניט אין ווערטער, וויל חסידות אַז מען זאָל אין דעם האָבען אַ שכל'דיקן בעגריף, און דאָס איז וואָס דער טאַטע<sup data-n=\"710\">21</sup> האָט מיר גיזאָגט אין עטלעכע קורצע ווערטער, אַז די דריי חלוקים אין אמת, איז אין ספירות איז דאָס חב\"ד חג\"ת נה\"י, און אין עולמות איז דאָס אצילות בריאה יצירה.\nמיט דעם ביאור פון ספירות האָב איך געדאַרפט פאַרשטיין די ג' חלוקי דרגות אין אמת, וואָס די צוויי מדרגות שפת אמת און אמת האָט מען זיך געדאַרפט אַ סך האָרעווען, אָבער סוף כל סוף צו עפעס אַ ידיעה צוגעקומען, אָבער אַז עס איז געקומען צו דער מדריגה הג' פאַרשטיין וואָס איז דער ענין פון אמת לאמתו, האָט דער האָרעווען אויך ניט געהאָלפען.\nדער העדר הידיעה פון דעם ענין האָט מיך אַזוי טיף פאַראַרט, אַז איך האָב מחליט געווען גיין צום טאַטען<sup data-n=\"710\">21</sup> אויף יחידות, און איך האָב שוין פאַר זיך מסדר געווען די שאלות, שפּעט אין אָווענד איז צו מיר אַריינגעגאַנגען הרי\"ם<sup data-n=\"724\">30</sup>. איך האָב געזעהען אַז ער איז זייער צוטראָגען. ווען מיר האָבען זיך צורעדט זאָגט מיר הרי\"ם, אַז ער איז היינט געווען אויף יחידות האָט ער גערעדט, אַז ער וויל ניט לערנען און וויל ניט טאָן אין עבודה, ווייל ער פאַרשטייט ניט, האָט אים דער טאַטע געענטפערט, וואָס מאָנסטו באַ מיר, מאָן באַ זיך, ווען דו וועסט באַ זיך מאָנען וועסטו אָנהויבען פאַרשטיין.\nהערענדיג דעם ענטפער, אַז מען וועט מאָנען וועט מען פאַרשטיין, האָט עס מיר געגעבען אַ נייעם מוט אויף אָנהויבען ווייטער האָרעווען אין דעם ביאור ענין פון אמת לאמיתו. נאָך גאָר אַ גרויסער יגיעה האָט מיר השי\"ת געגעבען אַ מתנה טובה אין דעם הבנת הענין. דער מקור החיים פון דער הבנה איז באַ מיר געווען אין דעם ענין פון נקודה בהיכלא. היכלא איז בינה וואָס דאָס איז השגה, און נקודה איז חכמה וואָס דאָס איז השכלה.\nט. השכלה און השגה זיינען ביידע אמת, אָבער זיי זיינען צוויי באַזונדערע זאַכען. השכלה איז אמת פאַר זיך און השגה איז אמת פאַר זיך. עס קען זיין אַז איינער זאָל זיין אַ בעל השכלה און ניט קיין בעל השגה, ווי מיר זעהען במוחש אַז איינער קען אויפטאָן אַ המצאה שכלית און ער אַליין זאָל ניט בעגרייפען די טיפע שכל'דיגע ברייטקייט פון דער המצאה, און עס איז פאַראַן דער וואָס איז אַ בעל השגה און ניט קיין בעל המצאה. דער טעם הדבר איז, ווייל השכלה און השגה זיינען צוויי בעזונדערע גילוים פון צוויי בעזונדערע כחות, וואָס יעדער כח האָט זיך אַ באַזונדער מקור.\nהשכלה און השגה זיינען גילויים פון די כחות חכמה און בינה. השכלה איז אַ גילוי פון כח החכמה און השגה איז אַ גילוי פון כח הבינה, וואָס די כחות פון חכמה ובינה האָבען בעזונדערע מקורים<sup data-n=\"725\">31</sup>. הגם חכמה ובינה איז ביידענס",[["710","21","כ\"ק אדמו\"ר מהר\"ש."],["710","21","כ\"ק אדמו\"ר מהר\"ש."],["724","30","הרה\"ח הרה\"ג ר' יעקב מרדכי בעזפאלאוו. רב בפאלטאווע. ר' יעקב מרדכי פאלטאווער. מחסידי אדמו\"ר מהר\"ש ואח\"כ אדמו\"ר מהורש\"ב נ\"ע. י\"ב אייר תרט\"ו — ל' תשרי תרע\"ו. ראה אודותו לקמן בשיחה זו סכ\"א ואילך (ע' 104 ואילך). לקמן ע' 224. 272. 276. שיחת כ' כסלו תרצ\"ג סעיף ו. ספר השיחות: תרצ\"ו­ש\"ת ע' 179. ע' 349; קיץ ת\"ש ע' 26. תש\"ו ע' 10. וש\"נ."],["725","31","ראה סה\"מ תרפ\"ט ע' 61. וש\"נ."]]],[4301600279,"שורש פון כח המשכיל, איז דער ענין אין דעם, אַז אין כח המשכיל גופא האָבען זיי בעזונדערע מקורים.\nפון דעם וואָס מיר זעהען אַז עס איז דאָ אַ בעל השכלה, וועלכער איז ניט קיין בעל השגה און עס איז דאָ אַ בעל השגה וועלכער איז ניט קיין בעל המצאה, פאַרשטייען מיר צוויי זאַכען: א) אַז אַזוי איז אין די כחות אַליין, אַז יעדער פון זיי איז אַ דבר שלם פאַר זיך און עס פעלט אים ניט די שלימות פון דעם צווייטען. ב) אַז אין יעדער איינעם פון זיי מוז זיין עפּעס אַ זאַך וואָס האָט אַ עהנליכקייט צו דער צווייטער זאַך, וואָס מיט דעם פאַרבייט דאָס די צווייטע זאַך.\nאון דאָס — די ביידע זאַכען — איז דער טעם פאַר וואָס עס קען זיין אַז די הנחה זאָל זיין פאַלש און די השגה זאָל זיין זייער אַ ברייטע און אַ רייכע אין טיפע סברות שכלים, ווייל די השכלה געהערט ניט צו דער השגה, באַ אים האָט עס זיך בטעות צוזאַמען געטראָפען. דער טעות האָט פאַרשידענע סבות, אָבער דער פועל יוצא איז, אַז די השכלה וואָס דאָס איז די הנחה איז אַ פאַלשע, און די התרחבות ההשגה איז זייער אַ גוטע מיט פיינע סברות שכלים.\nדי אַלע אופני הטעות אין דעם צוזאַמענטרעפן פון השכלה און השגה, איז נאָר שייך אין די מדרגות פון שפת אמת און אמת, אָבער אין דער מדרגה פון אמת לאמיתו וואָס דאָס איז שכל עצמי, אין דער מדרגה, איז ניטאָ קיין טעותים. אין שכל עצמי קען זייער אָפט זיין אַז מצד די העכסט דקות ההשכלה איז די השגה ניט ביכולת מבאר זיין די נקודת ההשכלה, אָבער עס זאָל זיין אַ טעות אין דער שייכות ההשכלה וההשגה דאָס קען ניט זיין.\nפון דעם אַלעם וואָס עס איז ביז אַהער גערעדט געוואָרען איז, אַז די מדרגה פון אמת לאמיתו איז די העכסטע מדרגה אין דעם שכל עצמי פון שכל אלקי, איז הגם דאָס איז דאָך אַ בנין שכלי מכל מקום איז דער בנין שכלי ניט בדומה כלל צו דעם בנין פון שכל אנושי, אויך אפילו די נידעריגסטע מדרגה פון שכל אלקי וואָס דאָס איז שפת אמת, איז אויך גאָר אַ אַנדערער מהות המציאות ווי שכל אנושי.\nי. פיל מאָל איז ב\"ה אויסגיקומען צו הערן פון טאַטען<sup data-n=\"718\">26</sup> אין די שיחות הקדש וואָס ער האָט גערעדט אין מעלת תורת החסידות, און מיט אַ באַזונדער פּנים מאירות און פּנים מסבירות פלעגט ער זאָגען זייער בעשיידען און גוט הערציג אונזערע חסידות, די חסידות וואָס השכלה איז עבודה און עבודה איז השכלה.\nמיט גאָר אַ בעזונדער געהויבענער שטימונג פלעגט דער טאַטע<sup data-n=\"718\">26</sup> אַרויסזאָגן אַ שבח להשי\"ת פאַר דער התגלות תורת החסידות בכלל און חסידות חב\"ד בפרט.\nווינטער תרס\"ז איז דער טאַטע געווען אין דער שטאָט ווירצבורג (בייערען)<sup data-n=\"728\">32</sup> כ\"ד טבת<sup data-n=\"729\">33</sup> איז אויסגעקומען יום ה' וארא, יעמאָלט איז געקומען החסיד ר' צבי שי' גורארי'<sup data-n=\"730\">34</sup> און דער טאַטע האָט געזאָגט חסידות<sup data-n=\"731\">35</sup>. נאָך דעם",[["718","26","כ\"ק אדמו\"ר מהורש\"ב."],["718","26","כ\"ק אדמו\"ר מהורש\"ב."],["728","32","ראה ספר השיחות: תר\"פ­תרפ\"ז ע' 15; תרצ\"ו — חורף ה'ש\"ת ע' 175. וש\"נ."],["729","33","יום הילולא של כ\"ק אדמו\"ר הזקן בעל התניא. — הערה בלקו\"ד שם."],["730","34","ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 24 הערה 2."],["731","35","ד\"ה היושבת בגנים — נדפס בהוספות להמשך תרס\"ו (הוצאת קה\"ת, תנש\"א) ע' תקצז ואילך. ד\"ה היושבת בגנים תשי\"ג וד\"ה הנ\"ל תשי\"ז (סה\"מ מלוקט ח\"ב ע' רכט ואילך. סה\"מ תשי\"ז ע' 77 ואילך) מיוסדים על מאמר זה."]]],[4301600280,"חסידות זאָגט דער טאַטע<sup data-n=\"732\">36</sup> עס איז דאָ אַ מאמר העולם, ווען מען דערמאָנט דעם, וועלכער איז שוין אויפן עולם האמת, אַ ליכטיקן גן עדן זאָל ער האָבען.\nאַ ליכטיקן גן עדן — האָט געזאָגט דער טאַטע — זאָל דער רבי<sup data-n=\"733\">37</sup> האָבען, וואָס ער האָט אונז געעפענט די אויגן און ליכטיג געמאַכט אין די קעפּ און אין די הערצער מיט דער התגלות תורת החסידות.\nהערענדיג די עטליכע ווערטער, וועלכע דער טאַטע האָט געזאָגט מיט אַזאַ הייליגע פנימיות'דיקע התלהבות, האָט זיך מיר יעמאָלט דערמאָנט דער מדרש אין שיר השירים פרשה ה' אויף דעם פסוק<sup data-n=\"734\">*37</sup> באתי לגני וואָס ער זאָגט דאָרטען אין דעם ענין פון גילוי שכינה למטה דורך די זיבען צדיקים, זיבען דורות, אברהם יצחק יעקב לוי קהת עמרם ומשה.\nאונז איז ב\"ה גוט, די זיבען דורות, די זיבען נשיאי עולם פון מורנו הבעש\"ט ביז דעם טאַטען ועד בכלל, האָבען אונז געעפענט די שערי ההיכלות פון חב\"ד, יעדער רבי אין זיין דור, און דער טאַטע מיט זיינע פינף און פערציג יאָר יגיעה אין חסידות האָבען אונז געגעבען די בעסטע ערקלערונג אויף די טיפסטע ענינים פון השכלה.\nדער טאַטע אַלט זייענדיק קנאַפּע ניינצן יאָר, האָט אויף צו פאַרשטיין דעם ענין פון שכל עצמי, אין דער מדרגה השלישית אמת לאמתו, געהאָרעוועט מיט בלוטיגע שווייס — מיט אַזאַ נוסח האָט ער מיר געזאָגט — אָבער די שווערע בלוטיגע יגיעה האָט גיבראַכט דעם תועלת הנרצה אין בערך דרייסיג יאָר אַרום — זומער תרס\"ח אין מאַריענבאַד<sup data-n=\"735\">38</sup> — רעדט ער מיט מיר — גייענדיג שפּאַצירען — אין דעם זעלבען ענין פון שכל עצמי מיט ברייטען הסבר און ביאור ווי אין גאָר אַ ענין מוחשי, ווייל דורך דער צייט איז ב\"ה תורת החסידות נתבאר ונתרחב גיוואָרען מיט ביאורים והסברים ארוכים אין יעדער ענין.\nפון יענער צייט — תרל\"ט תר\"מ בערך — איז דורכגעגאַנגען מעהר פון פופציג יאָהר, אין דעם יובל איז, תהלה לאל, תורת החסידות נתבאר ונתרחב געוואָרען, אַז עס גיט אונז די מעגליכקייט, אַז מיר זאָלען דאָס אויך קענען פאַרשטיין.\nיא. די פערציג יאָהריקע תקופה פון תר\"מ ביז תר\"פ איז פאַראייביגט אין דער חסידות'ער וועלט אַלעס איינע פון די הצלחה'דיקע תקופות אין התרחבות תורת החסידות.\nאיבער דער תקופה איז פאַראַן זייער",[["732","36","ראה גם ספר השיחות תורת שלום ע' 86. ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 175."],["733","37","כ\"ק רבינו הגדול בעל התניא. — הערה בלקו\"ד שם."],["734","*37","שה\"ש ה, א."],["735","38","ראה חנוך לנער ע' 15­14: סוף סיון [תרס\"ח] נוסע לברלין ומאריענבאד. במאריענבאד הי' מכ\"ד סיון עד י\"ז אלול תרס\"ח (אגרות­קודש אדמו\"ר מהורש\"ב ח\"ד ע' עדר. ע' שכב). ראה עוד ע\"ד ר\"ד ששמע רבינו מאביו כ\"ק אדמו\"ר מהורש\"ב בתקופה זו — אגרות­קודש ח\"ד ע' סח ואילך. שיחת חג הפסח תרצ\"ד סל\"ה. ספר השיחות קיץ ה'ש\"ת ע' 13. ע' 41."]]],[4301600281,"אַ פולע וואָס צו ריידן, עס איז איינע פון די וויכטיגסטע טיילן אין דעם דברי ימי החסידות, אָבער ניט דאָ איז די מעגלעכקייט דאָס גענוי אַרומריידן.\nדי תקופה האָט בעזונדער חשיבות'דיקע מאָמענטען, אַז אויך אין דעם דברי הימים און תולדות החסידות איז דאָס קובע מקום לעצמו, נאָר צוליב דעם ענין וואָס מי רעדט איצטער, וועט מען קורץ בערירן אייניגע פרטים פון דער תקופה.\nווינטער תער\"ב איז דער טאַטע גיווען אין מענטאָן<sup data-n=\"736\">39</sup>. פאַר די ערשטע עטליכע וואָכען וואָס דער טאַטע האָט פאַרבראַכט אין מענטאָן, האָט ער זיך גוט אויסגירוהט, און זיין גיזונד צושטאַנד האָט זיך בעדייטענד פאַרבעסערט.\nבעגלייטענדיק דעם טאַטען אין דער נסיעה, פון ליובאַוויטש ביז וואַרשא, האָט מיר דער טאַטע געזאָגט, אַז ער האָפט, זייענדיג אין מענטאָן וועט ער האָבען די גענוגנדע צייט אויף אַרומטראַכטען אַ טיפען נייעם ענין אין חסידות<sup data-n=\"737\">40</sup>.\nדי גאַנצע חסידות'ע משכיל'שע וועלט האָט דעם טאַטען בעצייכנט אַלעס דעם גאון אין השכלה פון חסידות.\nהחסיד מורי הרשב\"ץ נ\"ע<sup data-n=\"738\">41</sup> האָט גירופען דעם טאַטען, דער רמב\"ם פון חסידות<sup data-n=\"739\">42</sup>, וויילע יעדער ענין איז באַ דעם טאַטען אַ הלכה קבועה ומסודרה מיט דעם גאַנצען הסבר פון דעם ענין, דבר דבר על אופנו.\nיעדער איינצלטער מאמר חסידות איז באַ דעם טאַטען אַ מעין פון ים החכמה, אַ מסכת שלמה.\nזומער תרנ\"ח זייענדיג אין דאַטשע באָליווקע פלעג איך פון דעם טאַטנס פאַרטראַכטקייט זיין איבערראַשט.\nיעמאָלט פלעגט דער טאַטע אָפט בלייבן זיצן אין גאָרטן, פערטיפט אין מחשבות אייניגע שעות.\nווי ער האָט מיר נאָכדעם דערציילט, איז יעמאָלט בשעת ער איז גיזעסן אין גאָרטן האָט ער אַרומגיטראַכט דעם מאמר, יום טוב של ראש השנה מיט אַלע",[["736","39","בחדשי שבט­אדר<sup data-n=\"e34\">*</sup> — ראה אגרות­קודש אדמו\"ר מהורש\"ב ח\"ב ע' תרב­תרכה. ובחנוך לנער ע' 15: תרע\"ב — לרגלי בריאותו נוסע בחדש כסלו לברלין קרלסבאד רומי מענטאן. . לחה\"פ שב לביתו."],["737","40","ראה לקמן ע' 102­101. ע' 105."],["738","41","החסיד ר' שמואל בצלאל ב\"ר שלום שבתי שעפטל. ראה תולדותיו ב\"התמים\" חוברת א ע' סז [לה, א] ואילך. וראה גם ספר השיחות: תר\"פ­תרפ\"ז ע' 29 ובהערה 9; תרצ\"ו — חורף ה'ש\"ת ע' 10. ע' 24 ובהערה 12. ע' 185. נזכר לעיל ע' 32. לקמן ע' 215. ס\"ע 217 ואילך."],["739","42","נתבאר בלקוטי שיחות חלק ז ע' 208. ועוד. וראה שיחת יג ניסן תשמ\"ו. ועוד."],["e34","*","מ\"ש רבינו במכתב משנת תרפ\"ה (אגרות­קודש חי\"ד ע' תלז. רשימות כ\"ק אדמו\"ר — ילקוט — חוברת ט ע' 4): \"תרע\"ב מענטאן, כשלשה שבועות\", הכוונה, כנראה, להזמן שהי' רבינו ביחד עם אביו — ראה מכתב אדמו\"ר מהורש\"ב לרבינו מיום ה' כ\"ז שבט תער\"ב (אגרות­קודש שלו ח\"ב ס\"ע תרכא): \"וכפה\"נ החלטת לנסוע אי\"ה לפה\". ובמכתבו מיום י\"ט אדר תער\"ב (אגרות­קודש שם ע' תרכה): \"בו\"א [=בני ואישיך] יחי' איז אפגעפארין מפה יום ג' [=ט\"ז אדר] בקר\"."]]],[4301600282,"המשכים וואָס ער האָט גיזאָגט בר\"ה תרנ\"ט ביז פרשת וירא<sup data-n=\"740\">43</sup>.\nיעדער מאמר חסידות וואָס דער טאַטע האָט גיזאָגט, יעדער מאמר חסידות, וואָס דער טאַטע האָט געשריבען, איז דאָס באַ דעם טאַטן גיווען אַ גיוויסע איבערלעבונג.\nזיייענדיג אין די קינדער יאָהרען תרמ\"ט­נ\"א האָב איך גיהאַט אַ טבע ליב צו האָבן קוקן ווי דער טאַטע פלעגט זיצן באַ זיך אין חדר, אָדער באַ דעם זיידן אין אהל, אַ טיף פאַרטראַכטער, און דעם טאַטנ'ס פאַרטראַכטקייט פלעגט מיך בעצויבערן.\nיב. דעם ערשטן זמן וואָס מורי הרשב\"ץ נ\"ע איז גיקומען אין ליובאַוויטש — חורף תרנ\"ד<sup data-n=\"741\">44</sup> — האָבן כבוד דודיי הרמ\"מ שי'<sup data-n=\"742\">45</sup> ומחות' הר\"מ שי'<sup data-n=\"743\">46</sup> גימאַכט אַ סדר, אַז אייניגע מאָהל אין וואָך זאָלן זיי לערנען באַ מורי הרשב\"ץ נ\"ע חסידות.\nדער יאָהר תרנ\"ד איז אַ גיבענטשטער יאָהר אין חסידות<sup data-n=\"744\">47</sup>, כמעט אַז אַלע שבתים פון יאָהר, ד. ה. פון ראש השנה ביז שבת פרשת בהעלותך<sup data-n=\"745\">48</sup>, ווען דער טאַטע פאָהרט אָפּ אויף קוראַציע אין אָדעס אויפן לימאן<sup data-n=\"746\">49</sup>, איז יעדן שבת האָט דער טאַטע גיזאָגט אַ מאמר חסידות<sup data-n=\"747\">50</sup>.\nדעם מאמר, וואָס דער טאַטע פלעגט זאָגען פרייטאָג פאַר קבלת שבת, איז אַ חוץ דעם וואָס ער פלעגט איבער גירעדט ווערן פון דעם חוזר, הרב ר' אהרן ז\"ל<sup data-n=\"748\">51</sup> פאַר די אורחים וואָס פלעגן",[["740","43","נדפסו בסה\"מ תרנ\"ט ע' א ואילך."],["741","44","ראה ספר השיחות: תרצ\"ו — חורף ה'ש\"ת ע' 185; קיץ ה'ש\"ת ע' 161."],["742","45","הר' מנחם מענדל בן כ\"ק אדמו\"ר מהר\"ש. נולד וא\"ו אדר תרכ\"ז. נפטר בצרפת. בהשתדלות כ\"ק אדמו\"ר<sup data-n=\"e35\">*</sup>, הועלתה גופו — בשנת תשט\"ז — לארה\"ק, ומ\"כ בצפת עיה\"ק. ראה אודותו: ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז) ע' 22. לקוטי שיחות חלק יג ע' 180. ועוד. וראה גם אגרות­קודש חי\"ג ע' טז ובהערות המו\"ל שם."],["743","46","הרה\"ח ר' משה הכהן הארענשטיין חתנו של כ\"ק אדמו\"ר מהר\"ש. בנו הרה\"ח ר' מנחם מענדל הכהן הארענשטיין הי\"ד — התחתן עם בתו הצעירה של רבינו — הרבנית מרת שיינא הי\"ד<sup data-n=\"e36\">*</sup> — י' סיון תרצ\"ב."],["744","47","ראה ספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 310. שיחת חג הפסח תרצ\"ד סל\"ז."],["745","48","ראה הערה 50."],["746","49","מקום מרפא סמוך לאדעס, נשפך נהר דניעסטער לים השחור."],["747","50","ראה מכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע מיום א', ד' תמוז תרנ\"ד (אגרות­קודש שלו ח\"א ע' קעב): הנני נוסע שבוע זו על ערך ב' חדשים לאדעס כי בריאותי חלוש. ובחנוך לנער ע' 12: יום ג' [ו' תמוז] פ' חוקת [תרנ\"ד] בא לחרקוב לשאול בעצת הרופאים, והתעכב שם כעשרה ימים. מחרקוב נסע לאדעס על משך ד­ה שבועות לרחוץ בהלימאן. ושם ע' 55: בשנה זו [תרנ\"ד] הי' מאמר דא\"ח כמעט בכל שבת עד חודש תמוז. ובשיחת חג הפסח תרצ\"ד סל\"ז: [תרנ\"ד] פון שבת בראשית ביז תמוז [דערנאך איז דער טאטע געפארן אויף א קור­ארט אין לימאן נעבן אדעס] איז יעדן שבת געווען א מאמר."],["748","51","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 17. לקמן ע' 274."],["e35","*","ראה מכתב כ\"ק אדמו\"ר מיום ט' טבת תשט\"ו (אגרות­קודש ח\"י ע' ריד): בהנוגע לדודי זקני — אחי אדמו\"ר מהורש\"ב הרמ\"מ ע\"ה, הנה זמן מדויק דפטירתו אינני יודע אבל הי' זה בעיר באסטיא שהיא עיר הראשה דהאי קארסיקא, ובהזמן שהיו הנציס ימ\"ש שולטים בצרפת, ומונח בבית העלמין דשם. . ובטח יש משרדים כגון זו בפריז, שע\"פ ידיעות הנ\"ל יוכלו למצוא המקום המדויק."],["e36","*","ראה אודותה ספר השיחות תר\"פ­תרפ\"ז ע' 23 הערה 26. וש\"נ."]]],[4301600283,"קומען אויף שבת, פלעגט דער מאמר ווערן איבער גירעדט פון דער היפּשער — כ\"י — צאָהל יושבים<sup data-n=\"749\">52</sup>, וואָס זיינען יעמאָלט גיווען אין ליובאַוויטש.\nדער סדר איז גיווען, אַז מאָנטאָג פלעגט שוין זיין דער כתב, די יושבים האָבן דעם מאמר גילערנט בעיון, און באַ עלטערע חסידים — ווי מורי הרשב\"ץ<sup data-n=\"738\">41</sup>, החסיד ר' חנוך הענדל<sup data-n=\"751\">53</sup>, החסיד ר' שמואל ברוך מווארשא<sup data-n=\"752\">54</sup>, החסיד ר' אבא מצאשניק<sup data-n=\"753\">55</sup>, החסיד ר' ניסן<sup data-n=\"754\">56</sup> — וואָס זיינען יעמאָלט גיווען אין ליובאַוויטש. איז דער תוכן פון דער שבת'דיקער חסידות גיווען דער נושא הדיבור פון דער וואָך.\nאין יענער צייט — חורף תרנ\"ד — האָבען כבוד דודיי הרמ\"מ שי'<sup data-n=\"742\">45</sup>, והר\"מ שי'<sup data-n=\"743\">46</sup> זיך שטאַרק פאַרנומען מיט דעם לימוד החסידות, און דאָס האָט שטאַרק גיווירקט אויף עטלעכע יונגע לייט, גרויסע בעלי כשרונות, וואָס זיינען גיוואָרן משכילים אין וועלטישער וויסענשאַפט און אָפּגעווייטערט זיך פון חסידות, און דורך דער קביעות פון לערנען חסידות האָבן זיי זיך דערנעהנט.\nהחסיד מורי הרשב\"ץ נ\"ע האָט גיהאַט אַ באַזונדער חוש אין קאָנען מבאר און מסביר זיין אַ חסידות'ן וואָרט, צו יעדער ענין האָט ער גיהאַט אַ משל, און יעדער זאַך פלעגט באַ אים אַרויסקומען קלוג און שאַרף.\nיג. פון צייט צו צייט פלעגן כבוד דודיי הרמ\"מ שי' והר\"מ שי' זיין באַ דעם טאַטן, פרעגן און ריידן פערשידענע זאַכן פון דעם וואָס זיי האָבן יעמאָלט גילערנט, אָפטמאָהל פלעגט אַזאַ שמועס דויערן אַ שיינע פּאָר שעה.\nגיוויינלעך פלעגן די שמועסן פאָר­קומען אין די אָוונט שעות, ווען באַ מיר איז שוין גיווען נאָך דער צייט וואָס איך האָב גילערנט בא מורי החסיד רשב\"ץ נ\"ע, און אָפט פלעג איך ביי זיין באַ די שמועסן.\nאין איינעם פון אַזלכע שמועסן האָט דער טאַטע מבאר גיווען דעם ענין פון השכלה השגה הרגשה — פיהלען — און הכרה.\nאיצטער אַז עס איז ב\"ה דורכ­גיגאַנגען מעהר ווי פערציג יאָהר און די אַלע ענינים זיינען ב\"ה ברייט אַרומ­גירעדט גיוואָרן אין פיל מאמרים, זיינען אויך די ענינים פאַררעכנט אין די ענינים חשובים בתורת החסידות, און בפרט יעמאָלט, ווען אין די אַלע ענינים",[["749","52","ראה אגרות­קודש ח\"ב ע' קח: בשנת תרנ\"ד קבוצה של ט\"ו­י\"ז בחורים. . . הבחורים האלה בני בע\"ב חסידים אשר שלחו בניהם לליובאוויטש להיות \"יושבים\" (בהיומן אשר לי<sup data-n=\"e37\">*</sup>, יחדתי פרק מיוחד בההבדל שבין \"יושב\" לתלמיד הישיבה, אשר כן הי' גם אצל רבינו בשנת תר\"א­כ\"ו שני מפלגות הא' \"תלמידים\" והב' \"יושבים\")."],["738","41","החסיד ר' שמואל בצלאל ב\"ר שלום שבתי שעפטל. ראה תולדותיו ב\"התמים\" חוברת א ע' סז [לה, א] ואילך. וראה גם ספר השיחות: תר\"פ­תרפ\"ז ע' 29 ובהערה 9; תרצ\"ו — חורף ה'ש\"ת ע' 10. ע' 24 ובהערה 12. ע' 185. נזכר לעיל ע' 32. לקמן ע' 215. ס\"ע 217 ואילך."],["751","53","ראה אודותו לעיל ע' 32 ובהערה 17. וש\"נ."],["752","54","ראה אודותו: שיחת חג הפסח תרצ\"ד סט\"ו. ספר השיחות קיץ ה'ש\"ת ע' 152. תש\"ד ע' 104. שיחת יב תמוז תש\"ז סעיף ו (לקו\"ד ח\"ג תצג, א). שיחת יב תמוז תש\"ח סעיף ד. ח (סה\"מ תש\"ט ע' 198­197). אגרות­קודש ח\"ג ע' תב ואילך. ח\"ד ע' תו. ח\"י ע' תכד."],["753","55","ראה אודותו ספר השיחות: תר\"פ­תרפ\"ז ע' 253; תרצ\"ו — חורף ה'ש\"ת ע' 213. וש\"נ."],["754","56","ראה אודותו ספר השיחות תר\"פ­תרפ\"ז ע' 17 ובהנסמן שם הערה 31."],["742","45","הר' מנחם מענדל בן כ\"ק אדמו\"ר מהר\"ש. נולד וא\"ו אדר תרכ\"ז. נפטר בצרפת. בהשתדלות כ\"ק אדמו\"ר<sup data-n=\"e35\">*</sup>, הועלתה גופו — בשנת תשט\"ז — לארה\"ק, ומ\"כ בצפת עיה\"ק. ראה אודותו: ספר התולדות אדמו\"ר מהר\"ש (קה\"ת, תש\"ז) ע' 22. לקוטי שיחות חלק יג ע' 180. ועוד. וראה גם אגרות­קודש חי\"ג ע' טז ובהערות המו\"ל שם."],["743","46","הרה\"ח ר' משה הכהן הארענשטיין חתנו של כ\"ק אדמו\"ר מהר\"ש. בנו הרה\"ח ר' מנחם מענדל הכהן הארענשטיין הי\"ד — התחתן עם בתו הצעירה של רבינו — הרבנית מרת שיינא הי\"ד<sup data-n=\"e36\">*</sup> — י' סיון תרצ\"ב."],["e37","*","ראה רשימת המאסר — ספר השיחות תר\"פ­תרפ\"ז ע' 255."],["e35","*","ראה מכתב כ\"ק אדמו\"ר מיום ט' טבת תשט\"ו (אגרות­קודש ח\"י ע' ריד): בהנוגע לדודי זקני — אחי אדמו\"ר מהורש\"ב הרמ\"מ ע\"ה, הנה זמן מדויק דפטירתו אינני יודע אבל הי' זה בעיר באסטיא שהיא עיר הראשה דהאי קארסיקא, ובהזמן שהיו הנציס ימ\"ש שולטים בצרפת, ומונח בבית העלמין דשם. . ובטח יש משרדים כגון זו בפריז, שע\"פ ידיעות הנ\"ל יוכלו למצוא המקום המדויק."],["e36","*","ראה אודותה ספר השיחות תר\"פ­תרפ\"ז ע' 23 הערה 26. וש\"נ."]]],[4301600284,"פלעגט מען אפילו אין חסידות זעלטן ריידן, און מכל שכן אין אַ גאָר גיוויינלעכן שמועס, איז דאָס גיווען איינע פון די גרעסטע זאַכן.\nדעם ענין פון השכלה און השגה מיט דעם ברייטן ביאור פון אַ בעל המצאה און אַ בעל הסברה, וואָס דער טאַטע האָט מבאר גיווען האָבן זיי גוט פאַרשטאַנען, אָבער דעם ענין פון הרגשה — גיפיהל — און הכרה, האָבן זיי גאַנץ שוואַך פאַרשטאַנען, און דער ביאור האָט גינומען היפּש צייט.\nענדלעך האָט דער טאַטע ערקלערט, אַז די ריכטיגע השגה קומט דאָך אין דער העמקת הדעת פון דער נקודת התמצית<sup data-n=\"757\">57</sup> ביז מי קומט צו צו דעם אמת'ן תכלית פון השגה, וואָס דער אמת'ער תכלית פון השגה איז, ווי דער מאמר הידוע<sup data-n=\"758\">58</sup>: תכלית הידיעה שלא נודע.\nאין דער השגה, הגם עס ווערט דאָך דער ביטול השגה, ווייל די השגה איז דאָך בעצם למעלה מהשגה, דאָך אַז מי פאַרטיפט זיך אין דעם בהעמקת הדעת איז אין אַ געוויסן מאָמענט העלפט השי\"ת אַז מי הויבט אָן פיהלן דעם ענין, און מי קומט צו דער הכרה פון דעם ענין.\nאין אַ אריכות'דיקן שמועס איז דער טאַטע מבאר דעם אונטערשייד פון נקודת ההשכלה, וואָס דאָס איז דער אָנהויב פון יעדער מושכל, און נקודת התמצית<sup data-n=\"757\">57</sup> וואָס דאָס איז דער תכלית המושג פון יעדער מושכל, און דערפיהרט דערצו, אַז תורת החסידות האָט געעפנט שערי בינה, אַז עס איז ביכולת האדם צו קומען צו די גרעסטע און טיפסטע השגות, במוחש ממש.\nמי דאַרף נאָר וועלן מיט אַ אמת און האָרעווען מיט אַ אמת, אמת איז דער שליסעל וואָס עפענט אַלע שלעסער פון השכלה.\nיד. אין די אַכטצעהן יאָהר פון ווינטער תרנ\"ד ביז ווינטער תער\"ב איז ב\"ה תורת החסידות שטאַרק נתרחב גיוואָרן און היפּש ענינים זיינען ברייט נתבאר גיוואָרן.\nדי פיר יאָהר תרנ\"ד—ז זיינען גיווען יושבים בעלי כשרונות און אויך גאַנץ פיינע מתמידים, דאָס רוב פון די יושבים האָבן גילערנט חסידות בהתמדה.\nמיט דער התייסדות ישיבת תומכי תמימים יצ\"ו — ט\"ו אלול תרנ\"ז<sup data-n=\"760\">59</sup> — הויבט זיך אָן אַ נייע תקופה אין לימוד החסידות, דער לימוד החסידות ווערט מסודר ווי דער לימוד הנגלה, און מזמן לזמן זעהט מען דעם שינוי לטוב.\nדי וואָס לערנען חסידות און האָבן אין דעם אַ פאַרשטענדעניש, זעהען אין דעם טאַטנס מאמרים פון די יאָהרן תרנ\"ח­נ\"ט, תר\"ס, אַ געוויסן אונטערשייד, הן אין די עצם ענינים פון די מאמרים און הן אין דעם אופן פון די ביאורים און הסברים, פון יאָהר צו יאָהר.",[["757","57","נקודת התמצית — ענינה נתבאר בתורת חיים ר\"פ נח. בד\"ה השמים מספרים תרס\"ו [המשך תרס\"ו ע' רנב ואילך], וביום השמע\"צ תרס\"ז [המשך הנ\"ל ע' שעג], אני לדודי תרס\"ט [סה\"מ תרס\"ט ע' יא ואילך], וכל העם רואים תרצ\"ט [סה\"מ תרצ\"ט ע' 187 ואילך]. — הערת כ\"ק אדמו\"ר בסה\"מ תרנ\"ט ע' עה. סה\"מ תרפ\"ט ע' 131."],["758","58","ראה בחינות עולם חלק ח פרק ב. עיקרים מאמר ב סוף פרק ל. של\"ה קצא, ב."],["757","57","נקודת התמצית — ענינה נתבאר בתורת חיים ר\"פ נח. בד\"ה השמים מספרים תרס\"ו [המשך תרס\"ו ע' רנב ואילך], וביום השמע\"צ תרס\"ז [המשך הנ\"ל ע' שעג], אני לדודי תרס\"ט [סה\"מ תרס\"ט ע' יא ואילך], וכל העם רואים תרצ\"ט [סה\"מ תרצ\"ט ע' 187 ואילך]. — הערת כ\"ק אדמו\"ר בסה\"מ תרנ\"ט ע' עה. סה\"מ תרפ\"ט ע' 131."],["760","59","ראה גם לעיל ע' 75 ואילך."]]],[4301600285,"די מאמרים פון יאָהר תרנ\"ח ביז די מאמרים פון חג השבועות, זיינען איינצלנע מאמרים, און די ענינים פון די מאמרים זיינען אַזעלכע וואָס מתחילים אין לימוד החסידות זאָלן דאָס אויך קאָנען בעגרייפן.\nדעם מאמר פון חג השבועות תרנ\"ח איז אַ טיפער מאמר, אָבער דאָך איז דאָס לפי ערך די תלמידי תומכי תמימים אין יענער צייט.\nדי מאמרים פון יאָהר תרנ\"ט זיינען שוין פאַר אַזעלכע וואָס פאַרשטייען טיפערע ענינים אין חסידות, און די מאמרים פון יאָהר תר\"ס זיינען נאָך טיפערע ענינים.\nאין יאָהר תר\"ס האָבן אַ טייל תלמידי ישיבת תומכי תמימים שטאַרק גיטאָן אין די מאמרים, וואָס דער טאַטע האָט געזאָגט, און התלמיד מובהק החסיד הרב ר' אברהם דוד ז\"ל פויזנער מקלימאָוויטש<sup data-n=\"761\">60</sup> האָט גישריבן הנחות אויף די מאמרים.\nאויף וויפל באַ דעם טאַטען איז גיווען חשוב די הנחות וואָס התלמיד הרא\"ד האָט גישריבן, איז צו זעהן דערפון וואָס ער פלעגט זיי דורכזעהען און אין פאַרשידענע ערטער גיזאָגט ווי צו פאַרריכטן, און דאָס איז דער טעם וואָס אין יאָהר תר\"ס האָט דער טאַטע ווייניק גישריבן די מאמרים וואָס ער האָט געזאָגט בשבתות השנה<sup data-n=\"762\">61</sup>.\nטו. אין יאָהר תר\"ס נאָך חג הסוכות, בעפאָהר דער טאַטע פאָהרט אָפּ אין חאַרקוב<sup data-n=\"763\">62</sup> — וואו ער מאַכט דורך אַ געוויסע קוראַציע אונטער דער אופפאַסונג פון פּראָפעסאָרן — גיט דער טאַטע אַרויס דעם ערשטן קונטרס<sup data-n=\"764\">63</sup> פאַר די תלמידי ישיבת תומכי תמימים יצ\"ו.\nדער קונטרס הייסט קונטרס התפלה, דער אינהאַלט פון דעם קונטרס זאָגט דער טאַטע אַרויס אין אַ פּאָר קורצע ווערטער, אַז דער קונטרס איז אַ ענטפער די וואָס פרעגן ווי דאַוונט מען, און מיט וואָס דאַוונט מען.\nדער קונטרס איז אַ ברייטער טיפער ענטפער אויף די שאלות וואָס אַ חסיד דאַרף פרעגן באַ דעם רבי'ן אויף יחידות, ווי מען דאַרף דינען השי\"ת אין דער עבודה שבלב פון תפלה.\nדער קונטרס התפלה איז אַ הוראה ווי אַזוי עס דאַרף זיין די עבודה פון דער הכנה פון תפלה, און די פעולה פון",[["761","60","ראה ספר השיחות תר\"פ­תרפ\"ז ע' 17 ובהערה 35."],["762","61","בשנת תר\"ס הי' עבודה מרובה בעניני הכלל, דבר הבית חרושת בדובראוונא, דבר תחום המושב, וכו'<sup data-n=\"e38\">*</sup>. — הערה בלקו\"ד שם."],["763","62","ראה חנוך לנער ע' 13: אחר חנוכה [תר\"ס] נוסע לחרקוב לרגלי בריאותו. ובמכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע מאור יום ד' י\"א טבת תר\"ס (אגרות­קודש שלו ח\"ג ע' סז): \"באנו ת\"ל שלו' לפה [חרקוב] היום בקר\"."],["764","63","\"קונטרס התפלה. . הניתן. . בשביל התלמידים. . בתחלת טבת, שנת חמשת אלפים שש מאות וששים לבריאה\" (הקדמת רבינו להקונטרס). וכ\"ה באגרות­קודש ח\"ג ע' שכג. אבל בקונטרס התפלה דפוס ווילנא, תרפ\"ד נדפס בראשה: קונטרס ראשון של כ\"ק אדמו\"ר הרה\"ק זצוקללה\"ה נבג\"מ זי\"ע מ\"ח תר\"ס. וראה גם רשימת \"ספריו מאמריו ומכתביו שנדפסו\" — חנוך לנער ע' 21."],["e38","*","ראה אגרות­קודש אדמו\"ר מהורש\"ב ח\"א ע' ע' רלז ואילך. ח\"ג ע' קיא ואילך ובהערות שם. ע' רלא. ספר השיחות תר\"פ­תרפ\"ז ע' 15. אגרות­קודש ח\"ד ס\"ע תפט ואילך."]]],[4301600286,"עבודת התפלה, הן אין דעם תיקון ובירור המדות, און הן אין דער פיהרונג פון דעם טעגליכן לעבן.\nעס איז צו דערמאָנען אַז אין יאָהר תר\"ס האָט זיך שוין גיפיהלט אין דער חסידות'ער וועלט די גרויסע ווירקונג וואָס האָט געהאַט דעם טאַטענס ברייטער שמחת תורה שמועס<sup data-n=\"765\">64</sup>, און דער גוט באַוואוסטער מאמר החלצו<sup data-n=\"766\">65</sup>.\nדער תרנ\"ט'דיקער שמחת תורה שמועס, וואו דער טאַטע האָט ברייט אַרומגירעדט וואָס דער אלטער רבי האָט גימיינט ווי אַ חסיד דאַרף זיין, דעם גרויסען מסירת נפש וואָס אַלע רביים האָבן געהאַט אויף חסידות און חסידים, דעם מצב החסידים בעבר און דער מצב בהוה און נאָכדעם דער מאמר החלצו, איז במשך השנה גיוואָרן גוט פאַרשפּרייט במחנה החסידים, און עס האָט גיהאַט ב\"ה גאָר אַ גרויסע ווירקונג.\nדער קונטרס התפלה איז צוגינומען גיוואָרן באַ חסידים בכלל און באַ די תלמידי ישיבת תומכי תמימים בפרט מיט אַ גרויסער שמחה, אַלס אַ וועג ווייזער אין עבודת ה' בעבודה שבלב.\nטז. דער קונטרס התפלה איז אַ עד מוחשי אויף דעם רוחניות'דיקן צושטאַנד פון די תלמידי ישיבת תומכי תמימים און אויף דעם מצב פון עבודת החסידים אין יענער צייט.\nפון יענער צייט אָן, הויבט זיך אָן אַ נייע תקופה אין הרחבת תורת החסידות.\nדער יאָהר תרס\"א איז באַ די תלמידי ישיבת תומכי תמימים — וואָס האָבן שוין יעמאָלט גיציילט — כ\"י — אַ מספר נכון, און האָבן גיהאַט אַ געוויסע ווירקונג אויף דעם עדת החסידים בכלל — איז דער יאָהר תרס\"א גיווען אַ שנת עבודה מיט גאָר אַ גרויסער שקידה.\nאין יאָהר תרס\"א איז דער טאַטע גיווען דעם רוב יאָהר אין אויסלאַנד<sup data-n=\"767\">66</sup>, זייענדיק אין אויסלאַנד האָט ער מיר געשריבן בריף איבער דער הנהגה פון דער ישיבה, איינצלנע בריף זיינען בעקאַנט גיוואָרן צו די תלמידי ישיבת תומכי תמימים, און דאָס האָט אַריין גיטראָגן פרישע כחות און שקידה בלימוד החסידות.\nדי מאמרים וואָס דער טאַטע זאָגט אין די יאָהרן תרס\"ב, ס\"ג, ס\"ד, תרס\"ה, הן די איינצלטע מאמרים און הן די המשכים, די שמועסן פון די זמני שמחה, שמחת תורה און י\"ט כסלו, און די צוויי קונטרסים וואָס זיינען אַרויס אין די יאָהרן תרס\"ג<sup data-n=\"768\">67</sup> תרס\"ד<sup data-n=\"769\">68</sup> זיינען אַ בעווייז אויף דעם מצב החסידים און תלמידי ישיבת תומכי תמימים אין יענער צייט.\nיעדער איינער קאָן לויט די פערשידענע מאמרי חסידות, וואָס דער טאַטע האָט גיזאָגט אין דעם משך פון די",[["765","64","קטעים מדברי כ\"ק אדמו\"ר מהורש\"ב נ\"ע משמח\"ת תרנ\"ט הועתקו באגרות­קודש ח\"י ע' ד. ע' שסח. שיחת יט כסלו תרצ\"ג סעיף כו."],["766","65","נדפס בסה\"מ תרנ\"ט ע' נג ואילך."],["767","66","נסע יום ב', ד' כסלו תרס\"א. וחזר יום ג', ה' אלול תרס\"א (ראה אגרות­קודש אדמו\"ר מהורש\"ב ח\"ג ע' קנו. ע' שטז­שיז). במשך ימי שבתו בחו\"ל הי' ב: וועריסהאפען אצל מינכען, פאריז, ברלין, וויען ובאד האמבורג. בא בדברים עם עסקני הכלל ממדינות שונות (אגרות­קודש ח\"ז ע' שכה, רשימות רבינו בקונטרס ומעין ע' 7. ושם: שחזר ז אלול תרס\"א)."],["768","67","קונטרס ומעין."],["769","68","קונטרס עץ החיים."]]],[4301600287,"צוועלף יאָהר תרנ\"ד—תרס\"ה, זיך בעקאָנען מיט דעם גאָר גרויסען שינוי פון התרחבות החסידות און עבודת החסידים, וואָס עס איז פאָרגיקומען פאַר דעם משך זמן.\nדי צוועלף יאָהר האָבן גימאַכט אַ הכשרה אויף מגדל זיין אַ דור דעה, וואָס זאָלען לערנען חסידות בעיון און האָבען אַ טיפן גישמאַק אין עבודה שבלב.\nיז. דער מאמר, יום טוב של ראש השנה, וואָס דער טאַטע הויבט אָן ראש השנה תרס\"ו מיט די זעכציג המשכים — איין און פערציג מאמרים פון דעם המשך — אַ חוץ איינצלנע מאמרים — האָט דער טאַטע גיזאָגט אין יאָהר תרס\"ו, פופצען מאמרים פון דעם המשך — אַ חוץ איינצלנע מאמרים — האָט דער טאַטע געזאָגט אין יאָהר תרס\"ז, און פיר מאמרים פון דעם המשך האָט דער טאַטע גיזאָגט אין יאָהר תרס\"ח — איז אַן עד מוחשי אויף די התרחבות תורת החסידות, און אויף דעם מצב לומדי החסידות אין יענער צייט.\nדי וואָס בעקאָנען זיך מיט די ענינים אין חסידות, וואָס און ווי עס ווערט ברייט און דייטליך קלאָהר אַרומגערעדט אין די מאמרים פון די יאָהרן תרס\"ו, ס\"ז ס\"ח, ס\"ט; די גוט באַוואוסטע המשכים פון די יאָהרן עת\"ר, תרע\"א; און די עלף מאמרים פון דעם המשך יום טוב של ראש השנה תער\"ב, זעען אַז פון יאָהר תרס\"ו בעגינט אַ נייע תקופה אין דער התרחבות תורת החסידות.\nדי זעקס יאָהר פון תרס\"ו ביז תער\"ב האָבען רייך געמאַכט תורת החסידות מיט גרונטיקע בעלי כשרון און געוויסע בעלי עבודה.\nאין דעם מיטעלן רבי'נס פער­צייכנונגען — ווי עס ווייזט אויס, זאָל דאָס זיין גישריבן גאָר אין די יונגע יאָהרן — איז פאַראַן אַ אויסשפּראַך: ועל דרך צחות יש לומר.\nבדרך צחות קען מען זאָגן אויף דער התרחבות החסידות און עבודת החסידים פון תרס\"ו ביז תער\"ב, דעם מאמר<sup data-n=\"770\">69</sup> יותר ממה שבעל הבית עושה עם העני, העני עושה עם בעל הבית.\nתורת החסידות האָט גימאַכט גיבוירענע חסידים פאַר אמת'ע חסידים, און חסידים האָבן גימאַכט פּאַפּירענע חסידות פאַר לעבדיקע חסידות.\nאין פערלויף פון די אַכטצעהן יאָהר תרנ\"ד—תער\"ב האָט זיך דער ענין החסידות, הן דער לימוד החסידות, און הן די עבודה פון חסידות, גישטעלט אויף דער ריכטיקער גובה וואָס תורת און עבודת החסידות בעדאַרף פאַר­נעמען.\nדאָס אַלעס וואָס איך האָב אייך בקיצור נמרץ בעקאַנט גימאַכט מיט דעם סדר השתלשלות התרחבות החסידות און עבודת החסידים ותלמידי התמימים ביז דעם יאָהר תער\"ב, איז צוליב דעם אַז מי זאָל גרונטיק פאַרשטיין דעם וואָרט וואָס דער טאַטע האָט גיזאָגט<sup data-n=\"771\">70</sup> אַז קומענדיק אין מענטאָן האָפט ער, אַז ער וועט האָבען די גינוגענדע צייט אויף אַרומטראַכטן מסדר זיין אַ נייעם ענין אין חסידות.\nיח. די וואָס האָבען זוכה גיווען צו קענען דעם טאַטען און הערן חסידות",[["770","69","ויק\"ר פל\"ד, י."],["771","70","לעיל ע' 95. וראה לקמן ע' 105."]]],[4301600288,"און אַ שמחת תורה'דיקער אָדער י\"ט כסלו'דיקער רייד, ווייסן וואָס פאַר אַ אומבעגרענעצטע אהבה דער טאַטע האָט גיהאַט צו די וואָס לערנען חסידות און זיינען זיך עוסק בעבודה שבלב, און ווי גערן דער טאַטע איז גיווען מיטהעלפן זיי, אַז זיי זאָלן שטייגן אין השגה און אין עבודה.\nאין איינעם פון דעם טאַטענ'ס בריף צו מיר פון מענטאָן אין יענער צייט שרייבט מיר דער טאַטע, אַז ער איז ב\"ה זייער צופרידן, השי\"ת האָט אים ממלא רצונו גיווען, און זיין האָפענונג, וואָס ער האָט מיר גיזאָגט פאָהרנדיק פון ליובאַוויטש אין וואַרשא, און וואָס איך פרעג באַ אים אין איינעם פון מיינע בריף, קומט מהכח אל הפועל.\nעס איז מעהר ניט — שרייבט מיר דער טאַטע אין זיין בריף צו מיר — ווי דער בנין פון דעם ענין, און אויך דאָס איז מעהר ניט ווי בתכלית הקיצור, אָבער דאָס איז שוין ב\"ה אַ ענין כללי מסודר און דרך אגב — דער דרך אגב אַליין איז יקר מכל יקר — איז ער מיר מבאר ווי איז דער אופן הגילוי פון אַ השכלה, וואָס זי ווערט נתגלה פון כח השכל ההיולי העצמי, וואָס איז נטוע ומושרש בעצם הנפש.\nנקודת ההשכלה פון חכמה הגלוי' איז אויך טבעה להתעלם כידוע, ובפרט די נקודת ההשכלה ווי זי איז אין כח המשכיל, און מכש\"כ ווי די נקודת ההשכלה איז אַ המצאה שכלית ווי זי שטייט נאָך אין כח ההיולי פון שכל, וואָס איז נטוע אין נפש.\nעס איז איבעריג צו זאָגען אַז באַ מיר איז גיווען אַ שטאַרקע תשוקה וויסען וואָס איז דער נייער ענין אין חסידות וואָס דער טאַטע טוט אין אים, אָבער איך האָב גירעכנט אַז באמת דאַרף מען אַזעלכע זאַכן ניט וועלן וויסען.\nאַז איך בין גיקומען אויף שבת פ' וארא ר\"ח שבט אין מענטאָן<sup data-n=\"772\">71</sup> האָב איך גיטראָפן דעם טאַטן אַז ער איז גיווען זייער אויפגילייגט און צופרידן, איך האָב גיפיהלט אַז די אויפגילייגטקייט און די צופרידנקייט איז, פון אַ זייער איהם אַ פאַרגיניגונדיקע אַרבעט אין חסידות.\n* * *\nיט. איבער פערשידענע עניני הכלל האָב איך גידאַרפט זיין תחלת אדר באַ דעם טאַטן אין מענטאָן<sup data-n=\"773\">72</sup>, בין איך גיווען איבער פורים, יעמאָלט איז דאָרט גיווען ידידנו הרה\"ג החסיד הר' יעקב מרדכי נ\"ע מפּאלטאווע<sup data-n=\"724\">30</sup>.\nאויף פורים זיינען גיקומען אייניגע מידידינו אנ\"ש ובראשם ידידינו החסיד ר' שמואל נ\"ע גורארי'<sup data-n=\"775\">73</sup> מקרעמענטשוג.\nפורים צו דער סעודה איז גיווען אַ שטאַרקער פאַרבריינגען<sup data-n=\"776\">74</sup>, דער טאַטע",[["772","71","ראה רשימת היומן של רבינו מיום ב', [פ' בא], ג' שבט, מענטאן — \"התמים\" חוברת ג ע' כה [קכט, א]. יום ג' [פ' בשלח], יא שבט, פטרבורג — \"התמים\" שם ע' פח [קס, ב] ואילך."],["773","72","ראה לעיל הערה 39 בשוה\"ג. רשימת היומן של רבינו מיום ג' [פ' בשלח], יא שבט, פטרבורג — התמים חוברת ג ע' פט [קסא, א]."],["724","30","הרה\"ח הרה\"ג ר' יעקב מרדכי בעזפאלאוו. רב בפאלטאווע. ר' יעקב מרדכי פאלטאווער. מחסידי אדמו\"ר מהר\"ש ואח\"כ אדמו\"ר מהורש\"ב נ\"ע. י\"ב אייר תרט\"ו — ל' תשרי תרע\"ו. ראה אודותו לקמן בשיחה זו סכ\"א ואילך (ע' 104 ואילך). לקמן ע' 224. 272. 276. שיחת כ' כסלו תרצ\"ג סעיף ו. ספר השיחות: תרצ\"ו­ש\"ת ע' 179. ע' 349; קיץ ת\"ש ע' 26. תש\"ו ע' 10. וש\"נ."],["775","73","ר' שמואל ב\"ר שניאור זלמן גורארי'. מה\"יושבים\" אצל אדמו\"ר מהר\"ש, ואח\"כ נצטווה ממנו להתעסק במסחר. מחסידי אדמו\"ר מהורש\"ב ואדמו\"ר מהוריי\"צ. נפטר בחודש אד\"ר תרפ\"א. ראה אגרות­קודש ח\"א ס\"ע קיט ואילך (בהערה). שם ע' שכו. חי\"ד ע' קעה."],["776","74","ע\"ד ההתוועדות דפורים תער\"ב — ראה גם ספר השיחות: תרצ\"ו — חורף ה'ש\"ת ע' 179; קיץ ה'ש\"ת ס\"ע 41 ואילך; תש\"ד ע' 17 ואילך. אגרות­קודש ח\"ג ס\"ע תקנו ואילך. ע' תקסז ואילך."]]],[4301600289,"האָט מבאר גיווען אַז די וואָס לערנען חסידות בעיון קענען צו קומען צו די טיפסטע השגות במוחש ממש.\nדער תוכן הנושא פון דעם שמועס איז גיווען יעדער איינער קען זאָגן מתי יגיעו מעשי למעשה אבותי אברהם יצחק ויעקב<sup data-n=\"777\">75</sup>, יעדער איד קען צוקומען אויף זיין אַ מרכבה צו אלקות ווי די אבות<sup data-n=\"778\">76</sup> וואָס אבריהם היו קדושים ומובדלים פון עניני עולם.\nאין אַ טיפן ברייטן שמועס האָט דער טאַטע מבאר גיווען אַז שעבוד המוח צו אלקות איז אַ ענג נפלא.\nאַז מי פאַרטיפט זעך — זאָגט דער טאַטע — מיט אַ העמקת הדעת אין דער השגה פון אַ השכלה אין אַ ענין פון חסידות, פיהלט מען דעם אויר פון גן עדן.\nאיך האָב יאָהרן גיהאָרעוועט אויף ניט נאַרין זיך, מיינע כחות האָב איך אַוועקגיגעבן אויף דער השגה אין עבודה פון חסידות, דער גישמאַק פון חסידות האָט מיך אַרומגינומען, איך בין זיך כלל ניט מחזיק טובה דערפאַר דאָס איז אַ גיוויסע מתנה.\nאַלע ווייסן ווי מאוס עס איז דער ענין פון הגזמה, נאָך אַלעם דעם זאָג איך גלוי לעין כל, אַז דער אויבערשטער העלפט און איז מזכה פאַרטיפן זיך מיט אַ העמקת הדעת אין אַ השגה עיונית פון אַ ענין אין חסידות, פיהלט מען דעם אויר פון גן עדן.\nאַז דער כח השכל וואָס איז מלובש אין מוח הגשמי טראַכט זיך אַריין און נעמט אַרום דעם ענין פון חכמה סתימאה, אָדער דעם ענין פון ז' תחתונות דעתיק און ג' ראשונות דעתיק, אָדער דעם ענין פון אתה הוא הוי'<sup data-n=\"779\">77</sup> ווי דאָס איז נאָך לבדך<sup data-n=\"779\">77</sup> היינו לפני הצמצום, איז לא זו בלבד וואָס דער אדם החושב ווערט העכער דורך דער מחשבה, נאָר דער ענין וואָס דער אדם החושב טראַכט, ווערט דער ענין העכער, דאָס הייסט אַז דורך דער דביקות מחשבת החושב אין דעם ענין וואָס ער טראַכט, ווערט דער ענין העכער, און דער ענין אַליין הויבט אויף דעם אדם החושב אין דעם אָרט, וואו דער אדם החושב האָט מיט זיין עבודת המוח אים מעלה גיווען.\nכ. דער שמועס אי?עראַשט אַלע מסובים, עס איז אַ אמת'ער ענג רוחני הערן אַזא ואָס?עזאָנדערע טיפע רייד.\nנאָך אַ הפסקה פון התלהבות'דיקע דביקות נעימות'דיקע נגונים, איז דער טאַטע ממשיך די רייד.\nאַלע לבד עצמותו ומהותו יתברך ויתעלה זיינען נבראים, איך מיין ניט צו זאָגן דוקא נבראים, די זעלבע זאך איז נאצלים, נאצלים און נבראים איז איינע און די זעלבע זאַך לגבי דעם ענין וואָס מציאותו מעצמותו, דער ענין פון מציאותו מעצמותו איז נאָר אין עצמות<sup data-n=\"781\">78</sup>, אַ חוץ עצמותו ית' איז הן נבראים און הן נאצלים זיינען ניט מציאותן מעצמותן, נאָר נבראים זיינען אַזאַ מציאות און נאצלים זיינען אַ אַנדער מציאות.\nאָט די הנחה שכלית אַז אַלע לבד",[["777","75","תדבא\"ר פכ\"ה."],["778","76","ב\"ר פמ\"ז, ו. פפ\"ב, ו. וראה תניא פכ\"ג. פל\"ד. פל\"ט."],["779","77","נחמי' ט, ו. וראה סה\"מ תרפ\"ט ס\"ע 19 ואילך. וש\"נ."],["779","77","נחמי' ט, ו. וראה סה\"מ תרפ\"ט ס\"ע 19 ואילך. וש\"נ."],["781","78","ראה אגה\"ק ס\"כ (קל, ב)."]]],[4301600290,"עצמותו ית' זיינען נבראים בריינגט אונז צו דעם פאַרשטאַנד, אַז כשם ווי אין נבראים למטה איז פאַראַן אַ הפרש צי דער נברא בריינגט אַ תועלת אין עבודת ה', ובפרט אַז דאָס ווערט אַ מצוה כמו צמר פון ציצית קלף פון תפילין והדומה בכל המצות, וואָס דורך דער מצוה ווערט דער נברא העכער און איז מעלה דעם אדם וואָס איז מקיים די מצוה, וואָס בדוגמא כזאת איז אויך מיט די נאצלים חכמה סתימאה און פרצופי עתיק אַז דורך דעם דביקות המחשבה ווערט דער ענין נתעלה, און דורך דעם וואָס דער ענין ווערט נתעלה ווערט דער אדם החושב נתעלה במקום שנתעלה הענין שחשב בו.\nואני כברוש רענן ממני פריך נמצא<sup data-n=\"782\">79</sup>, עצמות א\"ס כביכול בויגט זיך<sup data-n=\"783\">80</sup> צו יעדער איינעם וואָס לערנט חסידות בעיון און האָרעוועט אין דער עבודה פון חסידות און זאָגט אים ממני פון עצמות וואָס בלתי מושג, איז פריך נמצא אין השגה ממש.\nדער וואָס האָרעוועט אין חסידות בעיון מיט אַ דביקות המוח, איז דער מוח הגשמי מיט זיין שכל אנושי משיג אַ השגה אלקית במוחש ממש.\nיעדער איינער וואָס האָרעוועט אין השכלה און עבודה פון חסידות קען צו קומען צו די העכסטע און טיפסטע ענינים.\nכא. איהר גידיינקט — זאָגט דער טאַטע צו החסיד הרה\"ג הר' יעקב מרדכי נ\"ע — דאָס וואָס איהר האָט מיר דערציילט<sup data-n=\"784\">81</sup> דעם טאַטנ'ס ענטפער אויף יחידות, וואָס מאָנסטו באַ מיר מאָהן באַ זיך, אַז דו וועסט באַ זיך מאָנען באמת וועסטו פאַרשטיין.\nאָט דער ענטפער דעם טאַטנ'ס האָט מיר גיהאָלפן אין אַלע צייטן באַ די טיפסטע ענינים, ביז איצטער געלויבט השי\"ת איז ניט גיווען אַ ענין אין חסידות וואָס מי זאָל אים ניט קאָנען דורכטאָן, געוויס איז גיווען זמנים וואָס מי האָט גידאַרפט לייגן גרויס יגיעה.\nבעלי עסקים מיינען אַז זיי ווייסן וואָס יגיעה איז און זיי ווייסן וואָס טרדא איז און בפרט נאָך אַ בעל עסק שלאָפט ניט אַ נאַכט מיינט ער אַז דאָס איז די אמת'ע יגיעה און טרדא.\nגאָר ניט קיין גרויסער בר דעת פאַרשטייט, אַז די יגיעה און טרדא פון מושכלות איז ניט בערך מעהר ווי די יגיעה און טרדא וואָס באַ בעלי עסקים.\nאמת אַז דער אויבערשטער העלפט און די יגיעה אין דעם מושכל בריינגט די ריכטיגע טיפע השגה איז דער ענג ושמחה פון דער ידיעה אויך באין ערוך לגבי דעם ענג ושמחה פון אַ בעל עסק.\nאַז דער אויבערשטער העלפט אַז מי פאַרשטייט אַ ענין שכלי אין חסידות בהשגה גמורה מיט אַ גיזונטן גיזעצטן אָפּלייג איז הגם דער שכלי וואָס ער פאַרשטייט איז דאָך אַ רוחני און דער שכל אנושי איז דאָך אַ גשמי בערך דעם רוחניות פון שכל אלקי מ\"מ איז די הנחה שכלית אַ מוחש'דיקע, אַז מי זעהט דעם שכל אלקי וואָס מי פאַרשטייט ווי איינער וואָס קוקט אויף אַ ציור נאה ביותר, וואָס יעדער שטריכעלע פון דעם",[["782","79","הושע יד, ט. וראה גם לעיל ע' 25."],["783","80","ראה לקו\"ת אחרי כו, ב."],["784","81","לעיל סעיף ח (ע' 92)."]]],[4301600291,"ציור ווערט ביי איהם איינגיזונקען אין אויג, און ער ווערט אינגאַנצען פאַרכאַפּט פון דעם ענג, און אַזוי און נאָך מעהרער איז דער ענג פון השגה און השכלה, ביז מי קען קומען צו כלות הנפש מגודל הענג.\nכב. דערמאהנענדיק דעם ענטפער פון יחידות הנ\"ל האָט דער טאַטע אָנגיהויבען דערציילען איבער יענער צייט, ווי ער און החסיד הרה\"ג ר' יעקב מרדכי נ\"ע פלעגן אין איינעם לערנען חסידות חזר'ן די מאמרים, לייגן הנחות, און שעות­ווייז ריידן אין עניני עבודה והשכלה.\nאין דעם האָט זיך החסיד הרה\"ג הרי\"מ נ\"ע זייער צו­וויינט בדמעות שליש, דאָס איז גיווען דער אמת'ער חסידות געוויין, אין דעם געוויין האָט מען גיהערט די חסידות'ע אָפטע אויסשפּראַך יתמרמר ויבכה במר נפשו, אַ געוויין פון מרירות, נפש'דיקע ביטערקייט, אַ געוויין וואָס בלייבט איינגיקריצט אין האַרצען אויף אייביג.\nמיט גרויס שוועריגקייט האָט מען החסיד הרה\"ג הרי\"מ נ\"ע בערואיגט, אַז ער איז גיקומען צו זיך האָט מען ערשט גוט פאַרבראַכט. דער טאַטע האָט מבאר גיווען אַז דער שכל פון חסידות איז שכל אלקי און ער — דער שכל — איז אַ שכל המתקבל, דער עיקר עבודה דאַרף זיין מאַכן זיך פאַר אַ כלי לקבלה.\nדער טאַטע איז מבאר דעם רבי'נס לשון<sup data-n=\"785\">82</sup> ונפש השנית בישראל היא חלק אלוקה ממעל<sup data-n=\"786\">83</sup>, דעם דיוק אין וואָרט ממעל, למטה איז אלקות אין הלבשה אין טבע, למעלה בלי שום הלבשה, ונפש השנית היא חלק אלוקה ממעל איז כשם ווי יכולת העצמות איז בכל הענינים איז כמו\"כ דער יכולת הנשמה שהיא חלק אלוקה ממעל אויף צו קומען צו די טיפסטע השכלות און השגות במוחש ממש.\nשפּעטער מיט אַ האַלב יאָהר אַז דער טאַטע האָט אָנגיהויבן חג השבועות תער\"ב דעם גוט בעוואוסטען הונדערט דריי און פערציג<sup data-n=\"787\">84</sup> המשך מאמר בשעה שהקדימו וואָס דער טאַטע האָט איהם גיזאָגט — מיט געוויסע הפסקים — פון חג השבועות תער\"ב ביז פרשה וירא תרע\"ו, האָט מיר דער טאַטע גיזאָגט אַז דעם ענין האָט ער אָנגיהויבען אין מענטאן<sup data-n=\"788\">85</sup>.\nמיט דעם מאמר בשעה שהקדימו הויבט זיך אָן אַ נייע תקופה אין התרחבות החסידות, און די אַלע טיפסטע ענינים פון חסידות ווערן ברייט אַרומגירעט, ווי גאָר געוויינליכע מוחש'דיקע זאַכן.\nכג. נאָך דער הקדמה וועלן מיר איצטער זיך צוריק קעהרן צו דעם ענין וואָס מיר האָבן אָנגיהויבען זיך צו ערקלערן.\nשכל איז אַ מציאות, יעדע מציאות מוז האָבן גדרים, וואָס די גדרים בעטאָנען און שטרייכען אונטער דעם מהות און מציאות פון דער זאַך.",[["785","82","תניא רפ\"ב."],["786","83","ראה גם אגרות­קודש ח\"ד ע' תב ואילך."],["787","84","אוצ\"ל: הונדערט פיר און פערציג (144). — ראה הוספות להמשך תער\"ב חלק א ע' ד (בהוצאת קה\"ת, תשנ\"ב)."],["788","85","ראה ספר השיחות תשנ\"ב ח\"א ע' 181­180. ולהעיר מספר השיחות תרצ\"ו — חורף ה'ש\"ת ע' 45 ובהערה 14."]]],[4301600292,"עס איז אַ מושכל ראשון, אַז מהות איז אַ מציאות, און מציאות איז אַ מהות, וואָס לפי זה דאַרף אויסקומען וויבאַלד אַז יעדער זאַך ווערט בעצייכנט און בעגרעניצט פון זיין מהות און מציאות, הייסט דאָס אַז יעדער איינער פון די צוויי זאַכן מהות און מציאות בעציי­כענען איין זאַך.\nאָבער באמת זיינען מציאות און מהות צוויי בעזונדערע זאַכן<sup data-n=\"789\">86</sup>, דאָס הייסט, הן אמת אַז מהות איז אַ מציאות און מציאות איז אַ מהות, אָבער מהות המציאות איז ניט מציאות המהות.\nקלערער געזאָגט, אָט דער מושכל ראשון, אַז מהות איז אַ מציאות, און מציאות איז אַ מהות, בריינגט אונז צו אַ בעשלוס אַז יעדער איינצעלטער פון די צוויי, בעזיצט ביידע זאַכן, אין מציאות איז פאַראַן מציאות המציאות און מהות המציאות, און אין מהות איז פאַראַן מציאות המהות און מהות המהות.\nוואָס לפי זה איז יעדער זאַך דער מהות און דער מציאות זיינער, איז הגם זיי זיינען דאָך ביידע איין זאַך, איז דאָס ניט נאָר צוויי נעמען אין איין זאַך, נאָר מציאות און מהות בעדייטן און שטרייכן אונטער איין זאַך פון צוויי בעזונדערע און פערשידענע שטאַנד און גרונד פונקטן.\nדער מציאות פון שכל — הן דער שכל עצמי און הן דער שכל הנקנה — האָט גדרים, וואָס די גדרים דייטן אונז זייער מציאות און מהות.\nדי גדרים פון שכל אנושי זיינען דריי זאַכן א) שכל איז מוגבל און איז מגביל, אַליין אַ באַגרעניצטער און באַגרעניצט די וואָס ער נעמט אַרום מיט זיין פאַרשטאַנד, שכל נעמט אַרום און פאַרשטייט אַ זאַך וואָס איז מחוץ ממנו. דער אופן פאַרשטאַנד פון שכל אנושי איז, אַז פריהער איז ער דאָס מגביל און באַגרעניצט און נאָכדעם פאַרשטייט ער דאָס, דאָס הייסט, אַז שכל אנושי פאַרשטייט אַ זאַך דוקא נאָך דעם ווי ער האָט פריהער באַגרעניצט און מגביל געווען די זאַך.\nב) שכל איז קרירות, קאַלטקייט, ניט התפעלות, וואָס מיט דעם טיילט זיך אָפּ שכל פון מדות, מדות הם התרגשות והתפעלות, אופרעגונג און פלאַם, וגדר השכל מתינות וקרירות (המתינות הוא ג\"כ חסרון בשכל אנושי לגבי שכל אלקי, ומכש\"כ קרירות).\nג) שכל אנושי הוא וואָס ער איז ניט אמת (בעצם ענינו אינו שקר, אבל לא אמת), דאָס איז ניט געלייקנט, אָבער דאָס איז ניט אמת, א) אין שכל איז פאַראַן נטיות, אַ סברא לחיוב און אַ סברא הפכית לשלילה, איז דאָך דער עצם שכל ניט אמת, ב) ענין השכל בא לבאר מה שהוא למעלה מן השכל, ובזה עצמו הוא מודה ומגלה על עצמו, אַז ער (שכל אנושי) אַליין, איז נאָך ניט אמת.\nכד. שכל אלקי האָט אויך גדרים, געוויסע גרעניצן וואָרום דאָס איז דאָך דער אלקות וואָס האָט זיך מלביש געווען אַז ער זאָל זיין בערך השגת הנבראים, אַז באַשעפענישן זאָלן אויך קאָנען בעגרייפן געטליכקייט, און דערפאַר איז דער שכל אלקי אויך מוגדר אין גדרים.\nאָבער די גדרים פון שכל אלקי זיינען כלל ניט ווי די גדרים פון שכל אנושי, שכל אלקי איז בלי גבול, ניט באַגרעניצט, און שכל אנושי איז באַגרעניצט.",[["789","86","ראה סה\"מ תרפ\"ט ע' 49. וש\"נ."]]]]});
